/* Palm-to-sleep (design #34 deliberate cover): covering the panel with a hand sleeps the watch,
 * same net effect as "back out to Home, then PWR to screen-off". Two signals feed it — the
 * CST9217's own COVER-SCREEN gesture (nocsif_touch_cover(), the reliable one) and, as a fallback,
 * >= PALM_MIN_POINTS simultaneous contacts. We require the cover to persist PALM_HOLD_US before
 * sleeping (rejects an accidental brush). Because the controller may report the cover only
 * intermittently (or once), a brief gap with no real finger down is BRIDGED (PALM_GRACE_US, kept
 * > HOLD so a one-shot gesture still reaches the threshold) rather than resetting the timer. The
 * cover is SWALLOWED (RELEASED to LVGL) so it never lands as a tap/gesture. Time-based, so it is
 * independent of the indev poll rate. */
#define PALM_MIN_POINTS  3                /* >= this many contacts at once = a hand, not a finger */
#define PALM_HOLD_US     (400 * 1000)     /* sustained cover before sleep (~0.4 s) */
#define PALM_GRACE_US    (600 * 1000)     /* bridge gaps in intermittent cover reports (> HOLD) */

static int64_t s_palm_since;   /* esp_timer us the cover began (0 = not covering) */
static int64_t s_palm_last;    /* esp_timer us of the last REAL covering frame (for the gap bridge) */
static bool    s_palm_fired;   /* one sleep per cover episode (cleared when the cover lifts/wakes) */

static void palm_sleep_async(void *unused);   /* defined with the lock/peek state machine below */

/* POINTER indev read: reuse the CST9217 driver. Coordinates are already native, so
 * pass through with no transform. Sole reader of nocsif_touch_read (main.c's polling
 * task is gone). Blocking I2C here is safe: the port calls this from the LVGL task
 * with the mutex already held. Also runs the palm-to-sleep detector. */
/* P8 v2.6 double-tap-to-wake — while the panel sleeps the touch indev stays ENABLED (screen_sleep no
 * longer disables it) so this read cb keeps polling, but every touch is swallowed (reported RELEASED)
 * so nothing navigates under the dark panel. Two quick taps within WAKE_DTAP_US wake the watch. */
static void screen_wake(void);                 /* defined below with the lock/sleep helpers */
#define WAKE_DTAP_US    420000                  /* max gap between the two taps (0.42 s) */
#define WAKE_TAP_MAX_US 320000                  /* a tap's max press duration (a long hold doesn't count) */
static bool    s_wake_down;                     /* last polled finger-down state (edge detect) */
static int64_t s_wake_press_t0;                 /* current press start */
static int64_t s_wake_tap1;                     /* release time of the first tap (0 = none armed) */

static void wake_from_touch_async(void *u) { (void)u; screen_wake(); lv_display_trigger_activity(NULL); }

static void wake_tap_detect(bool down, int64_t now)
{
    if (down && !s_wake_down) s_wake_press_t0 = now;              /* press edge */
    if (!down && s_wake_down) {                                   /* release edge -> a tap completed */
        bool quick = (now - s_wake_press_t0) < WAKE_TAP_MAX_US;
        if (quick && s_wake_tap1 != 0 && (now - s_wake_tap1) < WAKE_DTAP_US) {
            s_wake_tap1 = 0;
            lv_async_call(wake_from_touch_async, NULL);           /* second quick tap in time -> wake */
        } else {
            s_wake_tap1 = quick ? now : 0;                        /* arm the first tap (reset on a long press) */
        }
    }
    s_wake_down = down;
}

static void touch_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    nocsif_touch_point_t pts[NOCSIF_TOUCH_MAX_POINTS];
    int n = 0;
    esp_err_t r = nocsif_touch_read(pts, NOCSIF_TOUCH_MAX_POINTS, &n);
    int64_t now = esp_timer_get_time();

    /* Asleep: swallow every touch (never navigate under a black panel) but watch for a double-tap wake. */
    if (nocsif_display_is_asleep()) {
        wake_tap_detect(r == ESP_OK && n > 0, now);
        s_pressed = false;
        data->state = LV_INDEV_STATE_RELEASED;
        data->point.x = s_last_x;
        data->point.y = s_last_y;
        return;
    }

    bool cover = nocsif_touch_cover();                          /* hardware cover-screen gesture */
    bool real_cover = cover || (r == ESP_OK && n >= PALM_MIN_POINTS);

    /* Bridge a brief gap in intermittent cover reports: still recently covering, no real finger. */
    bool covering = real_cover ||
        (s_palm_since != 0 && n == 0 && (now - s_palm_last) < PALM_GRACE_US);

    if (covering) {
        if (s_palm_since == 0) {
            s_palm_since = now;
            ESP_LOGI(TAG, "palm: cover start (gesture=%d n=%d)", (int)cover, n);
        }
        if (real_cover) {
            s_palm_last = now;                                 /* only real frames refresh the bridge */
        }
        if (!s_palm_fired && (now - s_palm_since) >= PALM_HOLD_US) {
            s_palm_fired = true;
            ESP_LOGI(TAG, "palm: cover held -> sleep");
            lv_async_call(palm_sleep_async, NULL);             /* off the read cb: watchface + panel off */
        }
        s_pressed = false;                                     /* swallow: a cover is never a tap/swipe */
        data->state = LV_INDEV_STATE_RELEASED;
        data->point.x = s_last_x;
        data->point.y = s_last_y;
        return;
    }
    s_palm_since = 0;
    s_palm_fired = false;

    if (r == ESP_OK && n > 0) {
        s_last_x = pts[0].x;
        s_last_y = pts[0].y;
        s_pressed = true;
        data->state = LV_INDEV_STATE_PRESSED;
    } else {
        s_pressed = false;
        data->state = LV_INDEV_STATE_RELEASED;
    }
    data->point.x = s_last_x;
    data->point.y = s_last_y;
}

/* ===== §4.8a Companion — remote pointer (phone drives the UI) ================================== *
 * A SECOND LVGL pointer indev, fed by the companion WS uplink. The phone sends watch-space touch
 * points; nocsif_companion_touch packs {x,y,pressed} into ONE 32-bit word (an aligned store is atomic
 * on Xtensa → no lock across the httpd/LVGL tasks), and remote_read_cb reports it so taps, swipes and
 * dial drags from the phone drive the shell exactly like the touchscreen. The physical touch keeps its
 * own indev; whichever produces events wins. s_remote_last_us lets the mirror tick keep the watch awake
 * while it is being driven remotely. */
#define RPT_PACK(x, y, p) (((uint32_t)((p) & 1) << 30) | ((uint32_t)((y) & 0x7FFF) << 15) | ((uint32_t)((x) & 0x7FFF)))
static volatile uint32_t s_remote_pt;       /* pressed<<30 | y<<15 | x */
static volatile int64_t  s_remote_last_us;   /* last remote-touch time (idle-reset gate) */

/* Registered with wifi.c; called on the httpd task from the WS uplink. */
static void nocsif_companion_touch(int x, int y, int pressed)
{
    if (x < 0) x = 0; if (x >= NOCSIF_DISP_W) x = NOCSIF_DISP_W - 1;
    if (y < 0) y = 0; if (y >= NOCSIF_DISP_H) y = NOCSIF_DISP_H - 1;
    s_remote_pt = RPT_PACK(x, y, pressed ? 1 : 0);
    s_remote_last_us = esp_timer_get_time();
}
static void remote_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    uint32_t v = s_remote_pt;
    data->point.x = (int32_t)(v & 0x7FFF);
    data->point.y = (int32_t)((v >> 15) & 0x7FFF);
    data->state   = (v & (1u << 30)) ? LV_INDEV_STATE_PRESSED : LV_INDEV_STATE_RELEASED;
}

/* Snap every invalidated (redraw) area to a 2-pixel grid. The CO5300 addresses its
 * RAM in 2-px column/row units, so a partial flush on an odd column/width is written
 * with a per-row offset -> the content shears diagonally. Rounding start down to even
 * and end up to odd makes both origin and size even. Safe at the edges: the panel's
 * max coords (409, 501) are both odd, so |1 never exceeds bounds. */
static void ui_rounder_cb(lv_area_t *area)
{
    area->x1 &= ~1;
    area->y1 &= ~1;
    area->x2 |= 1;
    area->y2 |= 1;
}

#if NOCSIF_UI_FLUSH_AUDIT
/* --- P2 render-once flush audit (debug; NOCSIF_UI_FLUSH_AUDIT) --------------------
 * Counts genuine widget invalidations and tracks the largest dirty rect; a 5 s timer
 * logs the tally. LVGL emits a synthetic LV_EVENT_INVALIDATE_AREA from get_max_row
 * DURING rendering (a draw-buffer sizing probe), so bracket the render pass with
 * RENDER_START/READY and skip those. All callbacks run on the LVGL task. */
static volatile uint32_t s_inval_count;
static int32_t s_inval_max_px, s_inval_max_w, s_inval_max_h, s_inval_max_x, s_inval_max_y;
static volatile bool s_rendering;

static void render_start_cb(lv_event_t *e) { (void)e; s_rendering = true;  }
static void render_ready_cb(lv_event_t *e) { (void)e; s_rendering = false; }

static void inval_area_cb(lv_event_t *e)
{
    if (s_rendering) return;
    lv_area_t *a = lv_event_get_invalidated_area(e);
    int32_t w = a->x2 - a->x1 + 1;
    int32_t h = a->y2 - a->y1 + 1;
    s_inval_count++;
    if (w * h > s_inval_max_px) {
        s_inval_max_px = w * h;
        s_inval_max_w = w;  s_inval_max_h = h;
        s_inval_max_x = a->x1;  s_inval_max_y = a->y1;
    }
}

static void inval_report_timer_cb(lv_timer_t *t)
{
    (void)t;
    ESP_LOGI(TAG, "flush-audit: %u invalidations/5s; largest %ldx%ld @ (%ld,%ld) "
                  "[whole-screen 410x502 would mean a background repaint]",
             (unsigned)s_inval_count,
             (long)s_inval_max_w, (long)s_inval_max_h,
             (long)s_inval_max_x, (long)s_inval_max_y);
    s_inval_count = 0;
    s_inval_max_px = 0; s_inval_max_w = 0; s_inval_max_h = 0;
    s_inval_max_x = 0;  s_inval_max_y = 0;
}
#endif /* NOCSIF_UI_FLUSH_AUDIT */

#if NOCSIF_UI_FRAME_TIMING
/* --- Per-frame render pacing timing (debug; NOCSIF_UI_FRAME_TIMING) ----------------
 * All callbacks + the report timer run on the LVGL task, so the accumulators need no
 * locking. period = gap between consecutive RENDER_START = the visible frame cadence
 * (composite + wait for the previous flush to free a buffer). A gap longer than
 * FT_IDLE_GAP_US means animation had stopped, so that first-after-idle sample is
 * dropped rather than counted as one enormous frame. composite = START->READY = the
 * CPU software-compositor cost of the frame (the orrery re-blit lives here). */
#define FT_REPORT_MS    2000
#define FT_IDLE_GAP_US  200000   /* > this = idle gap between motion bursts, not a frame */

static int64_t s_ft_prev_start;      /* us; 0 = no previous START yet */
static int64_t s_ft_render_start;    /* us; START ts of the in-flight composite */
static uint32_t s_ft_n;              /* periods counted this window */
static int64_t s_ft_sum, s_ft_min, s_ft_max;   /* period stats (us) */
static uint32_t s_ft_nr;             /* composites counted this window */
static int64_t s_ft_rsum, s_ft_rmax;           /* composite stats (us) */

static void ft_render_start_cb(lv_event_t *e)
{
    (void)e;
    int64_t now = esp_timer_get_time();
    s_ft_render_start = now;
    if (s_ft_prev_start != 0) {
        int64_t period = now - s_ft_prev_start;
        if (period <= FT_IDLE_GAP_US) {
            s_ft_n++;
            s_ft_sum += period;
            if (s_ft_min == 0 || period < s_ft_min) s_ft_min = period;
            if (period > s_ft_max) s_ft_max = period;
        }
    }
    s_ft_prev_start = now;
}

static void ft_render_ready_cb(lv_event_t *e)
{
    (void)e;
    if (s_ft_render_start == 0) return;
    int64_t comp = esp_timer_get_time() - s_ft_render_start;
    s_ft_nr++;
    s_ft_rsum += comp;
    if (comp > s_ft_rmax) s_ft_rmax = comp;
}

static void ft_report_timer_cb(lv_timer_t *t)
{
    (void)t;
    if (s_ft_n == 0) return;   /* idle window — say nothing */
    int64_t mean   = s_ft_sum / s_ft_n;
    int64_t spread = s_ft_max - s_ft_min;
    long    jit    = mean > 0 ? (long)(spread * 100 / mean) : 0;
    long    fps    = mean > 0 ? (long)(1000000 / mean) : 0;
    int64_t rmean  = s_ft_nr ? s_ft_rsum / s_ft_nr : 0;
    ESP_LOGI(TAG, "frame-timing: %u frames ~%ldfps | period mean=%ld min=%ld max=%ld us "
                  "spread=%ld (jit=%ld%%) | composite mean=%ld max=%ld us",
             (unsigned)s_ft_n, fps,
             (long)mean, (long)s_ft_min, (long)s_ft_max, (long)spread, jit,
             (long)rmean, (long)s_ft_rmax);
    s_ft_n = 0; s_ft_sum = 0; s_ft_min = 0; s_ft_max = 0;
    s_ft_nr = 0; s_ft_rsum = 0; s_ft_rmax = 0;
}
#endif /* NOCSIF_UI_FRAME_TIMING */

/* ---- USB mode picker (P4.5.3) --------------------------------------------------- *
 * The #usb screen (mockup: connection line + mode band + hid-keyboard band). Rows only SIGNAL the
 * worker task (non-blocking, LVGL-safe): the USB mode server re-enumerates off the LVGL thread by
 * rewriting the active descriptor + tud_disconnect()/tud_connect() (install-once, never uninstalled).
 * Each mode row shows a right-aligned status — its idle descriptor, "active" (violet) when it is the
 * current mode, or ".." while a switch toward it is in flight. Tapping a mode row requests that mode;
 * tapping the ACTIVE row (or the Disconnect row) returns to Detached (design #3). Per-row poll timers
 * are torn down with their row, so they can never fire against a freed label. */

typedef struct {
    nocsif_usb_mode_t mode;
    lv_obj_t         *status;   /* right-aligned status label */
    const char       *desc;     /* idle descriptor (static string) */
    lv_timer_t       *timer;    /* this row's status poll timer  */
} usb_mode_ctx_t;

/* Free a mode row's context (and delete its timer) when the row is deleted (screen freed on back). */
static void usb_mode_row_deleted_cb(lv_event_t *e)
{
    usb_mode_ctx_t *c = (usb_mode_ctx_t *)lv_event_get_user_data(e);
    if (c->timer) {
        lv_timer_delete(c->timer);
    }
    free(c);
}

static void usb_mode_row_click_cb(lv_event_t *e)
{
    const usb_mode_ctx_t *c = (const usb_mode_ctx_t *)lv_event_get_user_data(e);
    /* These rows are File Share / Console (HID moved to its own drill row) — picking either ends any
     * latched HID session (design: HID stays armed "until switched detached", incl. to another mode). */
    s_hid_latched = false;
    /* Tap the live mode to turn it off (back to Detached); otherwise switch to it. */
    bool active = nocsif_usb_gadget_mode() == c->mode &&
                  nocsif_usb_gadget_state() == NOCSIF_USB_GADGET_ON;
    nocsif_usb_gadget_request_mode(active ? NOCSIF_USB_MODE_DETACHED : c->mode);
}

static void usb_mode_row_timer_cb(lv_timer_t *t)
{
    usb_mode_ctx_t *c = (usb_mode_ctx_t *)lv_timer_get_user_data(t);
    nocsif_usb_gadget_state_t st = nocsif_usb_gadget_state();
    const char *txt;
    lv_color_t col;
    if (st == NOCSIF_USB_GADGET_STARTING && nocsif_usb_gadget_target_mode() == c->mode) {
        txt = "..";     col = NOCSIF_STEEL;              /* switching toward this mode */
    } else if (nocsif_usb_gadget_mode() == c->mode && st == NOCSIF_USB_GADGET_ON) {
        txt = "active"; col = NOCSIF_VIOLET;             /* live */
    } else {
        txt = c->desc;  col = NOCSIF_ASH;                /* idle descriptor */
    }
    /* Only touch the label on change: under full_refresh any label write repaints the whole frame. */
    if (strcmp(lv_label_get_text(c->status), txt) != 0) {
        lv_label_set_text(c->status, txt);
        lv_obj_set_style_text_color(c->status, col, 0);
    }
}

/* Connection status line — also the switching indicator (P4.5.4 will persist it through the host
 * drive-mount). One label, one poll timer (freed with the label via control_timer_deleted_cb). */
static void usb_conn_timer_cb(lv_timer_t *t)
{
    lv_obj_t *label = (lv_obj_t *)lv_timer_get_user_data(t);
    const char *txt;
    switch (nocsif_usb_gadget_state()) {
    case NOCSIF_USB_GADGET_STARTING: txt = "switching\xE2\x80\xA6"; break;   /* … */
    case NOCSIF_USB_GADGET_FAILED:                                   /* A3: say WHY, not just that */
        txt = (nocsif_usb_gadget_fail_reason()[0] != '\0') ? nocsif_usb_gadget_fail_reason() : "switch failed";
        break;
    default:
        switch (nocsif_usb_gadget_mode()) {
        case NOCSIF_USB_MODE_CDC: txt = "CDC serial " NOCSIF_DOT " linked";       break;
        case NOCSIF_USB_MODE_HID: txt = "HID keyboard " NOCSIF_DOT " linked";     break;
        case NOCSIF_USB_MODE_MSC:
            /* P4.5.4: hold the switching indicator until the host has actually taken the drive.
             * The host FS-mount is invisible to the device (see nocsif_usb_gadget_msc_host), so
             * this is enumerate + a ~5 s settle: waiting-for-host -> preparing -> mounted. */
            switch (nocsif_usb_gadget_msc_host()) {
            case NOCSIF_USB_MSC_HOST_NONE:     txt = "File Share " NOCSIF_DOT " waiting for host";  break;
            case NOCSIF_USB_MSC_HOST_SETTLING: txt = "File Share " NOCSIF_DOT " preparing\xE2\x80\xA6"; break;
            case NOCSIF_USB_MSC_HOST_READY:
            default:                           txt = "File Share " NOCSIF_DOT " /sd on host";      break;
            }
            break;
        case NOCSIF_USB_MODE_DETACHED:
        default:                  txt = "detached " NOCSIF_DOT " pick a mode";    break;
        }
    }
    if (strcmp(lv_label_get_text(label), txt) != 0) {
        lv_label_set_text(label, txt);
    }
}

static void usb_disconnect_click_cb(lv_event_t *e)
{
    (void)e;
    s_hid_latched = false;   /* explicit Detached clears the HID latch */
    nocsif_usb_gadget_request_mode(NOCSIF_USB_MODE_DETACHED);
}

/* P4.5.3b: "Run Macro" no longer runs a hardcoded default from the USB screen — it drills into the
 * HID submenu's /sd/ducky file picker (build_macro_pick, below), which runs the tapped file. */

static void keymap_click_cb(lv_event_t *e)
{
    (void)e;
    const char *cur = nocsif_hid_kbd_locale();   /* cycle US -> GB -> DE -> US */
    const char *next = (strcmp(cur, "US") == 0) ? "GB"
                     : (strcmp(cur, "GB") == 0) ? "DE" : "US";
    nocsif_hid_kbd_set_locale(next);
}

static void keymap_status_timer_cb(lv_timer_t *t)
{
    lv_obj_t *label = (lv_obj_t *)lv_timer_get_user_data(t);
    const char *txt = nocsif_hid_kbd_locale();
    if (strcmp(lv_label_get_text(label), txt) != 0) {
        lv_label_set_text(label, txt);
    }
}

/* Delete a control button's poll timer when the button is deleted (its parent USB screen
 * is freed on nav-back). Runs on the LVGL task before the target label is torn down, so
 * the timer can never fire against a freed widget. Without this the timer would dangle. */
static void control_timer_deleted_cb(lv_event_t *e)
{
    lv_timer_t *t = (lv_timer_t *)lv_event_get_user_data(e);
    if (t) lv_timer_delete(t);
}

/* Header HID-armed badge (P4.5.4): returns "HID" whenever the HID keyboard is the live USB class
 * (mode()==HID), else "" (the header then hides the badge — see nocsif_nav_header_tick). Because a
 * transient HID connection auto-detaches on leaving the submenu, a badge that persists across screens
 * means HID was LATCHED armed — exactly the "what's armed" safety cue design #4 asks for. Returns a
 * string literal (stable) and only reads volatile state: LVGL-task-safe, like the other live getters. */
static const char *usb_hid_badge_str(void)
{
    return (nocsif_usb_gadget_mode() == NOCSIF_USB_MODE_HID) ? "HID" : "";
}

/* P8 v2.4 — refresh the peek's show/hide info elements. Defined down by build_peek (it reads the CC
 * flag statics); the one header tick calls it every ~0.5 s. */
static void peek_info_tick(void);
static void ui_accent_tick(void);   /* P8 v2.5: list-row connected-state accents */
static int  scr_timeout_secs(void); /* M11 power: configured screen-sleep timeout (s); 0 = never */
static void ui_predim_update(uint32_t inactive_ms, int timeout_s); /* M11 power: dim just before sleep */
static void ui_predim_cancel(void);                                /* M11 power: restore full brightness */
static bool s_saver_active;         /* M11 power: Battery Saver overlay currently in effect */
static void batt_saver_refresh(void);  /* recompute + apply/restore the Battery Saver overlay */
static bool ui_reduce_motion(void);    /* reduce_motion setting OR battery-saver active */
static void tm_bg_tick(void);       /* M11 C1·2: countdown-timer background expiry */
static void alarm_bg_tick(void);    /* M11 C1·4: per-minute alarm match */
static void alarms_load(void);      /* M11 C1·4: load persisted alarms at UI init */
static void alert_tick(void);       /* M11 C1: shared alarm/timer ring pump (header tick) */
static bool alert_active(void);     /* M11 C1: true while an alert is ringing */
static void alert_ack(void);        /* M11 C1: acknowledge/stop the ring (PWR / Stop) */
static void alert_snooze(void);     /* M11 C1: snooze the ring 2 min (FN / Snooze) */
static void cc_flashlight_open(void);  /* Control-Center torch overlay; reused by the Life Flashlight row */
/* §Home carousel style: 0=ring (default), 1=dual dials (peek-style), 2=bottom arc (half-ring). The peek
 * watchface shares the same three-style enum but its own setting (PEEK_CAR_KEY); default = dual (today). */
#define HOME_CAR_KEY   "home.car"
#define PEEK_CAR_KEY   "peek.car"
enum { HOME_CAR_RING = 0, HOME_CAR_DUAL, HOME_CAR_BOTTOM };
