/* ==== Unified Alert Center — a shell-wide alert log =============================== *
 * One RAM ring that every alert source funnels into, so the Alerts screen (build_alerts) shows phone
 * notifications AND on-watch events (alarm/timer fired, low battery, radio anomaly, notable weather)
 * as one uniform, swipe-to-dismiss / clear-all feed. ALL access is on the LVGL task — pushed from the
 * header tick's poll (alerts_ingest_tick) and from the alarm/timer alert_start — so NO lock is needed.
 * Phone notifications are INGESTED from the existing ANCS mirror (copied in, deduped by UID); the log
 * never mutates ble.c, so dismiss/clear operate purely on our copy. Watch sources read each subsystem's
 * LVGL-safe cached getter, so no worker-task file changes.
 *
 * §4.13 two-way sync scope: phone→watch dismiss IS wired (ANCS emits Notification-Removed; ble.c drops
 * it from its mirror + bumps its gen, and alerts_ingest_tick reconciles our log against the live mirror).
 * Watch→phone dismiss is NOT possible over ANCS: it offers only Perform-Notification-Action (positive/
 * negative, actionable notifications only), never a generic accessory-dismiss, so a swipe on the watch
 * clears only our local copy. A true watch→phone clear needs an Android companion or the §4.8 Approvals
 * lane — deliberately not faked here. */
typedef enum {
    ALERT_KIND_SYSTEM = 0, ALERT_KIND_PHONE, ALERT_KIND_ALARM, ALERT_KIND_TIMER,
    ALERT_KIND_BATTERY, ALERT_KIND_RADIO, ALERT_KIND_WEATHER, ALERT_KIND_N,
} alert_kind_t;

/* §4.13 verify hook: build with -DNOCSIF_ALERTS_SYNC_DEBUG=1 to log each swipe-dismiss and each
 * phone→watch reconcile over COM7 (the swipe + sync logic is otherwise a rendered/paired-phone outcome,
 * not serial-observable). Ships OFF so the flashed binary is quiet. */
#ifndef NOCSIF_ALERTS_SYNC_DEBUG
#define NOCSIF_ALERTS_SYNC_DEBUG 0
#endif

#define ALERT_LOG_MAX 6        /* log depth == visible cards; conservative for the LVGL pool (heavy cards) */
typedef struct {
    uint32_t     id;          /* unique, monotonic — the dismiss key */
    alert_kind_t kind;
    int64_t      when_us;     /* esp_timer_get_time at push (for age) */
    char         title[40];
    char         body[100];
    uint32_t     src_uid;     /* §4.13: ANCS NotificationUID (PHONE entries only; 0 otherwise) — the
                               * key that ties a card back to the live ANCS mirror for phone→watch sync */
} alert_log_t;
static alert_log_t s_alog[ALERT_LOG_MAX];
static int         s_alog_n;
static uint32_t    s_alog_next_id = 1;
static uint32_t    s_alog_gen;         /* bumped on any change (drives the screen self-refresh) */

static const char *alert_kind_icon(alert_kind_t k)
{
    switch (k) {
    case ALERT_KIND_PHONE:   return NOCSIF_ICON_PHONE;
    case ALERT_KIND_ALARM:   return NOCSIF_ICON_BELL;
    case ALERT_KIND_TIMER:   return NOCSIF_ICON_CLOCK;
    case ALERT_KIND_BATTERY: return NOCSIF_ICON_BATT;
    case ALERT_KIND_RADIO:   return NOCSIF_ICON_WIFI;
    case ALERT_KIND_WEATHER: return NOCSIF_ICON_WX;
    default:                 return NOCSIF_ICON_SYS;
    }
}
static const char *alert_kind_name(alert_kind_t k)
{
    static const char *const n[ALERT_KIND_N] = { "System", "Phone", "Alarm", "Timer", "Battery", "Radio", "Weather" };
    return ((unsigned)k < ALERT_KIND_N) ? n[k] : "System";
}

/* Newest-first: insert at [0], shift the rest down, evict the oldest at the cap. LVGL task only. */
static void alert_log_push(alert_kind_t kind, const char *title, const char *body)
{
    if (s_alog_n < ALERT_LOG_MAX) s_alog_n++;
    for (int i = s_alog_n - 1; i > 0; i--) s_alog[i] = s_alog[i - 1];
    alert_log_t *e = &s_alog[0];
    e->id      = s_alog_next_id++;
    e->kind    = kind;
    e->when_us = esp_timer_get_time();
    e->src_uid = 0;    /* §4.13: default; the ANCS ingest sets it on phone entries after this returns */
    snprintf(e->title, sizeof e->title, "%s", (title && title[0]) ? title : alert_kind_name(kind));
    snprintf(e->body,  sizeof e->body,  "%s", body ? body : "");
    s_alog_gen++;
}
static void alert_log_dismiss(uint32_t id)
{
    for (int i = 0; i < s_alog_n; i++) if (s_alog[i].id == id) {
        for (int j = i; j < s_alog_n - 1; j++) s_alog[j] = s_alog[j + 1];
        s_alog_n--; s_alog_gen++; return;
    }
}
static void alert_log_clear(void) { if (s_alog_n) { s_alog_n = 0; s_alog_gen++; } }

/* Relative age string from a push timestamp: "now" / "5m" / "3h" / "2d". */
static void alert_age_str(int64_t when_us, char *out, size_t n)
{
    int64_t s = (esp_timer_get_time() - when_us) / 1000000;
    if      (s < 45)    snprintf(out, n, "now");
    else if (s < 3600)  snprintf(out, n, "%dm", (int)((s + 30) / 60));
    else if (s < 86400) snprintf(out, n, "%dh", (int)(s / 3600));
    else                snprintf(out, n, "%dd", (int)(s / 86400));
}

/* Dedup ring for ingested ANCS UIDs (handles attrs arriving out of order across ticks). */
#define ALERT_UID_RING 32
static uint32_t s_ing_uid[ALERT_UID_RING];
static int      s_ing_head;
static bool alert_uid_seen(uint32_t uid)
{
    for (int i = 0; i < ALERT_UID_RING; i++) if (s_ing_uid[i] == uid) return true;
    return false;
}
static void alert_uid_mark(uint32_t uid)
{
    s_ing_uid[s_ing_head] = uid;
    s_ing_head = (s_ing_head + 1) % ALERT_UID_RING;
}
/* §4.13 phone→watch sync: forget a UID so if the phone re-posts the same notification later it ingests
 * fresh (a removed notification that comes back is a new event to the operator). */
static void alert_uid_unmark(uint32_t uid)
{
    for (int i = 0; i < ALERT_UID_RING; i++) if (s_ing_uid[i] == uid) s_ing_uid[i] = 0;
}

/* Poll every alert source into the log — driven by the header tick (LVGL task). Reads only cached,
 * LVGL-safe getters; alarm/timer push directly from alert_start instead. Gated by a tick counter so
 * each source runs at its own cadence (the header tick is ~0.5 s). */
static void alerts_ingest_tick(void)
{
    static uint32_t t;
    t++;

    /* Phone (ANCS) — ~1 s. Ingest notifications not yet logged (deduped by UID), oldest→newest. */
    if ((t & 1) == 0) {
        int n = nocsif_ble_ancs_count();
        for (int i = n - 1; i >= 0; i--) {
            nocsif_ble_ancs_notif_t nt;
            if (!nocsif_ble_ancs_get(i, &nt)) continue;
            if (alert_uid_seen(nt.uid)) continue;
            if (!nt.have_attrs && nt.age_ms < 2000) continue;   /* give the attr fetch a moment */
            const char *cat = nocsif_ble_ancs_category_str(nt.category);
            char title[40], body[100];
            snprintf(title, sizeof title, "%s", nt.title[0] ? nt.title : (nt.app[0] ? nt.app : cat));
            snprintf(body,  sizeof body,  "%s", nt.message[0] ? nt.message : cat);
            alert_log_push(ALERT_KIND_PHONE, title, body);
            s_alog[0].src_uid = nt.uid;   /* §4.13: tie this card to its ANCS UID for phone→watch sync */
            alert_uid_mark(nt.uid);
        }

        /* §4.13 phone→watch: reconcile removals. When the ANCS mirror changes (a notification was cleared
         * on the phone), drop any PHONE card whose UID is no longer live and forget it from the seen-ring.
         * Gated on the generation counter so this only runs when the mirror actually changed. */
        static uint32_t seen_ancs_gen;
        uint32_t g = nocsif_ble_ancs_gen();
        if (g != seen_ancs_gen) {
            seen_ancs_gen = g;
            int live = nocsif_ble_ancs_count();
            for (int i = 0; i < s_alog_n; ) {
                if (s_alog[i].kind != ALERT_KIND_PHONE || s_alog[i].src_uid == 0) { i++; continue; }
                bool present = false;
                for (int j = 0; j < live; j++) {
                    nocsif_ble_ancs_notif_t lt;
                    if (nocsif_ble_ancs_get(j, &lt) && lt.uid == s_alog[i].src_uid) { present = true; break; }
                }
                if (present) { i++; continue; }
#if NOCSIF_ALERTS_SYNC_DEBUG
                ESP_LOGI(TAG, "alerts: phone-removed uid=%u -> dismiss id=%u",
                         (unsigned)s_alog[i].src_uid, (unsigned)s_alog[i].id);
#endif
                alert_uid_unmark(s_alog[i].src_uid);
                alert_log_dismiss(s_alog[i].id);   /* compacts in place — do NOT advance i */
            }
        }
    }

    /* Battery — ~4 s. Two-stage low warning with hysteresis; reset while charging / recovered. */
    if ((t % 8) == 0) {
        static int warned;   /* 0 none · 1 low@15 · 2 crit@5 */
        int  pct = nocsif_power_batt_pct();
        bool chg = (nocsif_power_charging() == NOCSIF_CHG_CHARGING);
        if (chg || pct < 0) {
            warned = 0;
        } else if (pct <= 5 && warned < 2) {
            char b[48]; snprintf(b, sizeof b, "%d%% " NOCSIF_NDASH " charge now", pct);
            alert_log_push(ALERT_KIND_BATTERY, "Battery critical", b); warned = 2;
        } else if (pct <= 15 && warned < 1) {
            char b[48]; snprintf(b, sizeof b, "%d%% " NOCSIF_NDASH " consider charging", pct);
            alert_log_push(ALERT_KIND_BATTERY, "Battery low", b); warned = 1;
        } else if (pct > 20) {
            warned = 0;   /* re-arm after it recovers */
        }
    }

    /* Radio — ~4 s. A deauth/disassoc burst (accrues only while the WiFi monitor/parser runs);
     * 30 s cooldown so a flood posts one alert, not dozens. */
    if ((t % 8) == 4) {
        static uint32_t last_cnt; static bool init; static int64_t last_push_us;
        uint32_t c = nocsif_wifi_deauth_count() + nocsif_wifi_disassoc_count();
        if (!init) { last_cnt = c; init = true; }
        else if (c > last_cnt) {
            int64_t now = esp_timer_get_time();
            if (now - last_push_us > 30000000LL) {
                char b[64]; snprintf(b, sizeof b, "%u deauth/disassoc frames seen", (unsigned)c);
                alert_log_push(ALERT_KIND_RADIO, "Radio anomaly", b);
                last_push_us = now;
            }
            last_cnt = c;
        }
    }

    /* Weather — ~30 s. One alert when conditions first turn notable (rain/snow/storm, WMO >= 61);
     * re-arms once they clear. */
    if ((t % 60) == 12) {
        static int last_code = -1;
        nocsif_weather_t wx;
        if (nocsif_weather_snapshot(&wx) && wx.valid) {
            bool notable = (wx.code >= 61);
            if (notable && wx.code != last_code) {
                alert_log_push(ALERT_KIND_WEATHER, nocsif_weather_code_text(wx.code), "current conditions");
                last_code = wx.code;
            } else if (!notable) {
                last_code = -1;
            }
        }
    }
}

/* The one header live-data timer (P4.2 clock + P4.3 battery + P4.5.4 HID-armed badge). The label
 * PUSH runs every tick (~0.5 s) so the badge tracks arm/disarm promptly; the I2C cache refreshes are
 * gated slow (RTC ~20 s, battery ~40 s — the battery moves slowly, spec §6). Then it updates every
 * registered live label update-on-change. One timer for the whole shell — the nav registry routes it
 * to whichever header/readout labels are currently alive. Runs on the LVGL task; each I2C read is
 * short (a few bytes), like the touch indev. Created once in nocsif_ui_init. */
static void header_tick_cb(lv_timer_t *t)
{
    (void)t;
    static uint32_t ticks;
    if ((ticks % UI_HEADER_RTC_EVERY) == 0) {   /* clock: refresh the RTC cache ~20 s   */
        nocsif_rtc_tick();
    }
    if ((ticks % UI_HEADER_BATT_EVERY) == 0) {  /* battery: refresh the gauge cache ~40 s */
        nocsif_power_batt_tick();
    }
    ticks++;
    nocsif_nav_header_tick();   /* push caches + the badge into the live labels, update-on-change */
    peek_info_tick();           /* P8 v2.4: show/hide the peek BT · DND · activity elements */
    ui_accent_tick();           /* P8 v2.5: hub + list-row connected-state accents */
    batt_saver_refresh();       /* M11 power P4: auto-enter/leave Battery Saver on the battery % */
    tm_bg_tick();               /* M11 C1·2: fire the countdown timer even when its screen is closed */
    alarm_bg_tick();            /* M11 C1·4: fire a matching alarm even when its screen is closed */
    alert_tick();               /* M11 C1: pump the ring chime + snooze while an alert is up */
    alerts_ingest_tick();       /* Alert Center: poll phone/battery/radio/weather into the log */
    movie_geofence_tick();      /* §4.1 Automations: auto-exit Movie mode once you leave the set location */
}

/* A USB mode-picker row: [icon] name … [right status], chevron-less like the power-menu action row
 * but with a live status label + a per-row poll timer. Tapping toggles the mode (usb_mode_row_click_cb).
 * The context is heap-allocated and freed with the row (usb_mode_row_deleted_cb). */
static void add_mode_row(lv_obj_t *list, const char *icon, const char *name,
                         const char *desc, nocsif_usb_mode_t mode)
{
    usb_mode_ctx_t *c = (usb_mode_ctx_t *)calloc(1, sizeof(*c));
    if (c == NULL) {
        return;
    }
    c->mode = mode;
    c->desc = desc;

    lv_obj_t *row = lv_obj_create(list);
    lv_obj_remove_style_all(row);
    lv_obj_add_style(row, &nocsif_style_row, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_set_scrollbar_mode(row, LV_SCROLLBAR_MODE_OFF);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *ic = lv_label_create(row);
    lv_label_set_text(ic, icon);
    lv_obj_add_style(ic, &nocsif_style_row_icon, 0);
    lv_obj_set_width(ic, 24);
    lv_obj_set_style_text_align(ic, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_t *nm = lv_label_create(row);
    lv_label_set_text(nm, name);
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_flex_grow(nm, 1);

    c->status = lv_label_create(row);
    lv_label_set_text(c->status, desc);                  /* seeded; the timer keeps it live */
    lv_obj_set_style_text_font(c->status, &nocsif_mono_11, 0);
    lv_obj_set_style_text_color(c->status, NOCSIF_ASH, 0);

    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, usb_mode_row_click_cb, LV_EVENT_CLICKED, c);
    lv_obj_add_event_cb(row, usb_mode_row_deleted_cb, LV_EVENT_DELETE, c);
    c->timer = lv_timer_create(usb_mode_row_timer_cb, 300, c);
}

/* A chevron-less action row with a live right-status label (Run Macro, Keymap). The status label is
 * the timer's user_data; the timer is freed with the row (control_timer_deleted_cb). status_cb runs
 * once here to seed the label so it never flashes empty. */
static void add_status_row(lv_obj_t *list, const char *icon, const char *name,
                           lv_event_cb_t click_cb, lv_timer_cb_t status_cb)
{
    lv_obj_t *row = lv_obj_create(list);
    lv_obj_remove_style_all(row);
    lv_obj_add_style(row, &nocsif_style_row, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_set_scrollbar_mode(row, LV_SCROLLBAR_MODE_OFF);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *ic = lv_label_create(row);
    lv_label_set_text(ic, icon);
    lv_obj_add_style(ic, &nocsif_style_row_icon, 0);
    lv_obj_set_width(ic, 24);
    lv_obj_set_style_text_align(ic, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_t *nm = lv_label_create(row);
    lv_label_set_text(nm, name);
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_flex_grow(nm, 1);

    lv_obj_t *status = lv_label_create(row);
    lv_label_set_text(status, "");
    lv_obj_set_style_text_font(status, &nocsif_mono_11, 0);
    lv_obj_set_style_text_color(status, NOCSIF_ASH, 0);

    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, click_cb, LV_EVENT_CLICKED, NULL);
    lv_timer_t *timer = lv_timer_create(status_cb, 300, status);
    lv_obj_add_event_cb(row, control_timer_deleted_cb, LV_EVENT_DELETE, timer);
    status_cb(timer);   /* seed the status label from the current state */
}

/* ---- app registry + launch-by-id (app layer) ---------------------------------- *
 * The menu tree is built as an APP REGISTRY: every screen/action has a stable string id
 * (e.g. "wifi", "wifi.scan", "system.about"), and a menu row resolves its target THROUGH
 * the registry by id — never a hardcoded pointer. nocsif_app_launch(id) is the single
 * entry point that brings the shell to a screen, so later bindings (the FN side-button,
 * the peek-screen planets, gestures) can target any app without touching the nav mechanism
 * (which stays root-based in ui_nav). Screens build lazily and are cached while alive, but a
 * non-pinned screen is FREED when popped (nocsif_nav_back) and its cache pointer cleared on
 * delete, so cached widgets never accumulate in LVGL's fixed 48 KB object pool (unbounded
 * caching ran it dry after a few screens -> a render-time alloc failed -> LVGL span in
 * lv_draw_label). Only Home is pinned and survives a pop. Un-built actions (everything
 * past M4 + the hero screens) are
 * present-but-disabled STUBS with a registered id, so a later milestone just flips the
 * entry enabled and gives it a build fn. */
typedef lv_obj_t *(*app_build_fn)(void);
typedef struct {
    const char  *id;         /* stable target id                                    */
    const char  *title;      /* serif header title (NULL = Home)                    */
    const char  *icon;       /* canonical icon (informational; rows pass their own) */
    app_build_fn build;      /* builds+returns the screen root; NULL = stub         */
    lv_obj_t    *root;       /* cached while alive; cleared on the root's delete     */
    bool         enabled;    /* false = present-but-disabled stub                   */
    bool         pin;        /* keep alive when popped (owns timers/state) — see nav */
} app_t;

