/* §4.13 fix #6 — Cyber > Audio: a small tone-player hub. First (only) entry is Carts, which plays the
 * published ~7.8 kHz shopping-cart wheel-lock tone through the MAX98357A. Reuses the existing tone
 * generator (nocsif_audio_tone), so no audio.c change and zero new internal-DMA (the I2S TX channel is
 * already boot-reserved). Both the row and its play button gate on nocsif_audio_tx_ready(). */
static const rowspec_t k_audio_rows[] = {
    { "audio.carts", "Carts", NOCSIF_ICON_PLAY, NULL, NOCSIF_TAG_NONE },
};
static lv_obj_t *build_audio(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Audio", "speaker " NOCSIF_DOT " tone tools", &content);
    ROWS(nocsif_menu_list(content), k_audio_rows);
    return scr;
}

/* Carts (Phase B rebuild, PLAN §4.17 B): play published cart-lock tone files from the card.
 * /sd/nocsif/carts/<folder>/*.wav — the first screen lists the FOLDERS under carts (plus any loose .wav at
 * the root); tapping a folder pushes its file list; tapping a file plays it, a Stop row stops it, and tapping
 * another file switches. Playback is the Phase B audio engine: ANY PCM WAV (8/16/24/32-bit or float, mono or
 * stereo, 8–48 kHz — the I2S clock follows the file), streamed from the card, unity make-up gain (published
 * tones are already normalised). Both screens share one builder; a 400 ms timer drives the "playing …" line.
 * Still best-effort on the hardware: the speaker is a small mono amp and ~7.8 kHz tones sit near its useful
 * ceiling — confirm range on hardware. The old synth-tone fallback row is gone (it was a pure carrier). */
#define UI_CARTS_DIR    "/sd/nocsif/carts"
#define UI_CARTS_MAX    32
#define UI_CARTS_NAMEL  48
static char s_carts_dir[96];        /* folder chosen on the root screen (full path), for the pushed file screen */
static char s_carts_title[UI_CARTS_NAMEL];

static bool carts_is_audio(const char *name)     /* .wav or .mp3 (Phase B + minimp3) */
{
    const char *dot = strrchr(name, '.');
    return name[0] != '.' && dot != NULL && (strcasecmp(dot, ".wav") == 0 || strcasecmp(dot, ".mp3") == 0);
}
static int carts_cmp(const void *a, const void *b) { return strcasecmp((const char *)a, (const char *)b); }

/* Snapshot one level of `dir` under the SD lock — folders (want_dirs) or playable files — sorted. The
 * macro-picker idiom: readdir under the lock into a fixed table, then build rows with the lock released. */
static int carts_scan(const char *dir, bool want_dirs, char names[][UI_CARTS_NAMEL], int max)
{
    int n = 0;
    if (!nocsif_sdcard_lock(1000)) return 0;
    if (want_dirs) {                          /* make the drop folder discoverable (EEXIST ignored) */
        mkdir("/sd/nocsif", 0777);
        mkdir(UI_CARTS_DIR, 0777);
    }
    DIR *d = opendir(dir);
    if (d != NULL) {
        struct dirent *ent;
        while ((ent = readdir(d)) != NULL && n < max) {
            if (ent->d_name[0] == '.') continue;
            const bool is_dir = (ent->d_type == DT_DIR);
            if (want_dirs ? !is_dir : (is_dir || !carts_is_audio(ent->d_name))) continue;
            strncpy(names[n], ent->d_name, UI_CARTS_NAMEL - 1);
            names[n][UI_CARTS_NAMEL - 1] = '\0';
            n++;
        }
        closedir(d);
    }
    nocsif_sdcard_unlock();
    if (n > 1) qsort(names, (size_t)n, UI_CARTS_NAMEL, carts_cmp);
    return n;
}

static lv_obj_t *carts_screen(const char *title, const char *dir, bool root_level);

static void carts_folder_click_cb(lv_event_t *e)
{
    const char *path = (const char *)lv_event_get_user_data(e);
    strncpy(s_carts_dir, path, sizeof s_carts_dir - 1);
    s_carts_dir[sizeof s_carts_dir - 1] = '\0';
    const char *nm = strrchr(s_carts_dir, '/');
    strncpy(s_carts_title, nm ? nm + 1 : "Folder", sizeof s_carts_title - 1);
    s_carts_title[sizeof s_carts_title - 1] = '\0';
    lv_obj_t *root = carts_screen(s_carts_title, s_carts_dir, false);
    if (root) nocsif_nav_push(root);
}
static void carts_file_click_cb(lv_event_t *e)
{
    const char *path = (const char *)lv_event_get_user_data(e);
    if (path && nocsif_audio_tx_ready()) nocsif_audio_play_file(path, 100);   /* unity make-up; switches */
}
static void carts_stop_cb(lv_event_t *e)     { (void)e; nocsif_audio_stop(); }
static void carts_row_deleted_cb(lv_event_t *e) { free(lv_event_get_user_data(e)); }   /* the per-row heap path */

static void carts_add_row(lv_obj_t *list, const char *dir, const char *name, bool is_dir)
{
    char *path = (char *)malloc(strlen(dir) + 1 + strlen(name) + 1);
    if (path == NULL) return;
    strcpy(path, dir);
    strcat(path, "/");
    strcat(path, name);
    lv_obj_t *row = nocsif_menu_add_row(list, is_dir ? NOCSIF_ICON_FOLDER : NOCSIF_ICON_PLAY, name, NULL,
                                        is_dir ? "folder" : NULL, is_dir ? NOCSIF_TAG_VALUE : NOCSIF_TAG_NONE,
                                        false, NULL);
    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, is_dir ? carts_folder_click_cb : carts_file_click_cb, LV_EVENT_CLICKED, path);
    lv_obj_add_event_cb(row, carts_row_deleted_cb, LV_EVENT_DELETE, path);
}

/* "playing · <file>" / "idle" — update-on-change on a 400 ms timer whose user data is the status label. */
static void carts_tick(lv_timer_t *t)
{
    lv_obj_t *lbl = (lv_obj_t *)lv_timer_get_user_data(t);
    char path[96], buf[80];
    if (nocsif_audio_playing_path(path, sizeof path)) {
        const char *nm = strrchr(path, '/');
        snprintf(buf, sizeof buf, "playing " NOCSIF_DOT " %s", nm ? nm + 1 : path);
    } else {
        strcpy(buf, nocsif_audio_tx_ready() ? "idle " NOCSIF_DOT " tap a file to play" : "speaker n/a");
    }
    if (strcmp(lv_label_get_text(lbl), buf) != 0) lv_label_set_text(lbl, buf);
}
static void carts_deleted_cb(lv_event_t *e)
{
    lv_timer_t *t = (lv_timer_t *)lv_event_get_user_data(e);
    if (t) lv_timer_delete(t);
    /* Playback deliberately continues in the background (the Stop row on any Carts screen ends it). */
}

static lv_obj_t *carts_screen(const char *title, const char *dir, bool root_level)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold(title, "cart-lock tones " NOCSIF_DOT " tap to play", &content);
    const bool ok = nocsif_audio_tx_ready();

    lv_obj_t *stat = nocsif_content_line(content, ok ? "idle" : "speaker n/a", &nocsif_mono_13, NOCSIF_ASH, 0);

    /* Stop row (always first; disabled when the amp never claimed its I2S DMA). */
    lv_obj_t *ctl = nocsif_menu_list(content);
    lv_obj_t *stop = nocsif_menu_add_row(ctl, NOCSIF_ICON_PAUSE, "Stop", NULL, ok ? NULL : "n/a",
                                         ok ? NOCSIF_TAG_NONE : NOCSIF_TAG_VALUE, !ok, NULL);
    if (ok) {
        lv_obj_add_flag(stop, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(stop, carts_stop_cb, LV_EVENT_CLICKED, NULL);
    }

    static char names[UI_CARTS_MAX][UI_CARTS_NAMEL];   /* LVGL-task only */
    lv_obj_t *list = nocsif_menu_list(content);
    int total = 0;
    if (root_level) {
        int nd = carts_scan(dir, true, names, UI_CARTS_MAX);   /* folders first */
        for (int i = 0; i < nd; i++) carts_add_row(list, dir, names[i], true);
        total += nd;
    }
    int nf = carts_scan(dir, false, names, UI_CARTS_MAX);       /* then the playable files at this level */
    for (int i = 0; i < nf; i++) carts_add_row(list, dir, names[i], false);
    total += nf;

    if (total == 0) {
        lv_obj_t *empty = lv_label_create(list);
        lv_label_set_text(empty, root_level
                          ? "nothing here yet " NOCSIF_NDASH " put folders of .wav / .mp3 files under /sd/nocsif/carts"
                          : "no .wav / .mp3 files in this folder");
        lv_label_set_long_mode(empty, LV_LABEL_LONG_WRAP);
        lv_obj_set_width(empty, lv_pct(100));
        lv_obj_add_style(empty, &nocsif_style_font_tag_small, 0);
        lv_obj_set_style_text_color(empty, NOCSIF_ASH, 0);
        lv_obj_set_style_pad_all(empty, 8, 0);
    }

    lv_timer_t *timer = lv_timer_create(carts_tick, 400, stat);
    lv_obj_add_event_cb(scr, carts_deleted_cb, LV_EVENT_DELETE, timer);
    carts_tick(timer);   /* seed immediately */
    return scr;
}

static lv_obj_t *build_audio_carts(void)
{
    return carts_screen("Carts", UI_CARTS_DIR, true);
}

/* P8 v2.4 — Alerts: the notifications screen (USER moved notifications out of the Control Center into
 * their own screen; also the peek carousel's Alerts bubble target). PLACEHOLDER cards until the M7 ANCS
 * mirror populates this from the phone. */
/* ---- Alerts — the unified Alert Center (fills `alerts`; Life + peek-carousel target) ------- *
 * Renders the shell-wide alert log (alert_log_*) as swipe-to-dismiss cards + a Clear-all button.
 * A FIXED card pool (the live-list rule: update in place, never clean+recreate on a timer) refreshed
 * on a gen tick. Swipe a card LEFT to dismiss (back-gesture is swipe-RIGHT, so left is free; children
 * clear CLICKABLE so the press lands on the card for the gesture). Phone notifications flow in via the
 * header tick's ANCS ingest; watch events push directly — this screen only VIEWS + dismisses the log. */
#define ALERT_VIEW_ROWS ALERT_LOG_MAX
typedef struct { lv_obj_t *card, *icon, *title, *body, *age; uint32_t id; } alert_card_t;
static alert_card_t s_acard[ALERT_VIEW_ROWS];
static lv_obj_t    *s_alerts_empty;    /* "no alerts" note */
static lv_obj_t    *s_alerts_clear;    /* Clear-all button */
static uint32_t     s_alerts_seen_gen;

static void alerts_view_refresh(void)
{
    if (!s_acard[0].card) return;
    int n = s_alog_n;
    for (int i = 0; i < ALERT_VIEW_ROWS; i++) {
        alert_card_t *c = &s_acard[i];
        if (!c->card) continue;
        if (i < n) {
            alert_log_t *e = &s_alog[i];
            c->id = e->id;
            lv_label_set_text(c->icon, alert_kind_icon(e->kind));
            lv_label_set_text(c->title, e->title[0] ? e->title : alert_kind_name(e->kind));
            lv_label_set_text(c->body, e->body);
            char age[8]; alert_age_str(e->when_us, age, sizeof age);
            lv_label_set_text(c->age, age);
            lv_obj_clear_flag(c->card, LV_OBJ_FLAG_HIDDEN);
        } else {
            c->id = 0;
            lv_obj_add_flag(c->card, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (s_alerts_empty) (n == 0 ? lv_obj_clear_flag : lv_obj_add_flag)(s_alerts_empty, LV_OBJ_FLAG_HIDDEN);
    if (s_alerts_clear) (n == 0 ? lv_obj_add_flag : lv_obj_clear_flag)(s_alerts_clear, LV_OBJ_FLAG_HIDDEN);
    s_alerts_seen_gen = s_alog_gen;
}

static void alerts_tick_cb(lv_timer_t *t)
{
    (void)t;
    if (!s_acard[0].card) return;
    if (s_alog_gen != s_alerts_seen_gen) {
        alerts_view_refresh();
    } else {                       /* no log change: just keep the visible age labels fresh */
        for (int i = 0; i < s_alog_n && i < ALERT_VIEW_ROWS; i++)
            if (s_acard[i].card && !lv_obj_has_flag(s_acard[i].card, LV_OBJ_FLAG_HIDDEN)) {
                char age[8]; alert_age_str(s_alog[i].when_us, age, sizeof age);
                lv_label_set_text(s_acard[i].age, age);
            }
    }
}

static void alerts_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    for (int i = 0; i < ALERT_VIEW_ROWS; i++) s_acard[i] = (alert_card_t){ 0 };
    s_alerts_empty = s_alerts_clear = NULL;
}

static void alerts_card_gesture_cb(lv_event_t *e)
{
    lv_indev_t *indev = lv_indev_active();
    if (!indev) return;
    lv_dir_t dir = lv_indev_get_gesture_dir(indev);
    /* The card clears GESTURE_BUBBLE (so a swipe on it isn't stolen by the screen root), which also means
     * a right-swipe that starts on a card no longer bubbles to screen_gesture_cb. Handle back here too so
     * swipe-right-to-go-back still works when the finger lands on a card. */
    if (dir == LV_DIR_RIGHT) { nocsif_nav_back(); return; }
    if (dir != LV_DIR_LEFT) return;   /* up/down = scroll */
    alert_card_t *c = (alert_card_t *)lv_event_get_user_data(e);
    if (c && c->id) {
#if NOCSIF_ALERTS_SYNC_DEBUG
        ESP_LOGI(TAG, "alerts: swipe-dismiss id=%u", (unsigned)c->id);
#endif
        alert_log_dismiss(c->id);
        alerts_view_refresh();
    }
}

static void alerts_clear_cb(lv_event_t *e) { (void)e; alert_log_clear(); alerts_view_refresh(); }

static void alerts_make_card(lv_obj_t *parent, alert_card_t *c)
{
    c->card = lv_obj_create(parent);
    lv_obj_remove_style_all(c->card);
    lv_obj_set_width(c->card, lv_pct(100));
    lv_obj_set_height(c->card, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(c->card, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(c->card, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_all(c->card, 18, 0);      /* taller card = bigger tap / swipe target */
    lv_obj_set_style_pad_column(c->card, 14, 0);
    lv_obj_set_style_radius(c->card, 16, 0);
    lv_obj_set_style_bg_color(c->card, lv_color_hex(0x0d0d11), 0);
    lv_obj_set_style_bg_opa(c->card, LV_OPA_COVER, 0);
    lv_obj_remove_flag(c->card, LV_OBJ_FLAG_SCROLLABLE);
    /* Clear GESTURE_BUBBLE so LVGL v9.3 delivers the swipe to THIS card, not the top-most bubble-flagged
     * ancestor (the screen root, whose handler only acts on RIGHT=back). Without this the per-card
     * swipe-to-dismiss never fires. Same idiom as the brightness/volume drag + colour wheel. §4.13. */
    lv_obj_remove_flag(c->card, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_flag(c->card, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_event_cb(c->card, alerts_card_gesture_cb, LV_EVENT_GESTURE, c);

    c->icon = lv_label_create(c->card);
    lv_obj_remove_flag(c->icon, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_text_font(c->icon, &nocsif_icons, 0);
    lv_obj_set_style_text_color(c->icon, NOCSIF_VIOLET, 0);   /* accent badge */

    lv_obj_t *col = lv_obj_create(c->card);
    lv_obj_remove_style_all(col);
    lv_obj_remove_flag(col, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_flex_grow(col, 1);
    lv_obj_set_height(col, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(col, 3, 0);

    c->title = lv_label_create(col);
    lv_obj_remove_flag(c->title, LV_OBJ_FLAG_CLICKABLE);
    lv_label_set_long_mode(c->title, LV_LABEL_LONG_DOT);
    lv_obj_set_width(c->title, lv_pct(100));
    lv_obj_set_style_text_font(c->title, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(c->title, NOCSIF_WHITE, 0);

    c->body = lv_label_create(col);
    lv_obj_remove_flag(c->body, LV_OBJ_FLAG_CLICKABLE);
    lv_label_set_long_mode(c->body, LV_LABEL_LONG_DOT);
    lv_obj_set_width(c->body, lv_pct(100));
    lv_obj_set_style_text_font(c->body, &nocsif_mono_14, 0);
    lv_obj_set_style_text_color(c->body, NOCSIF_STEEL, 0);

    c->age = lv_label_create(c->card);
    lv_obj_remove_flag(c->age, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_text_font(c->age, &nocsif_mono_14, 0);
    lv_obj_set_style_text_color(c->age, NOCSIF_ASH, 0);
}

static lv_obj_t *build_alerts(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Alerts", "swipe a card left to dismiss", &content);
    lv_obj_set_style_pad_hor(content, 18, 0);
    lv_obj_set_scroll_dir(content, LV_DIR_VER);

    /* Clear-all (accent pill; hidden while the log is empty). */
    s_alerts_clear = lv_obj_create(content);
    lv_obj_remove_style_all(s_alerts_clear);
    lv_obj_set_width(s_alerts_clear, lv_pct(100));
    lv_obj_set_height(s_alerts_clear, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(s_alerts_clear, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_bg_opa(s_alerts_clear, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(s_alerts_clear, NOCSIF_VIOLET, 0);
    lv_obj_set_style_border_width(s_alerts_clear, 1, 0);
    lv_obj_set_style_radius(s_alerts_clear, 8, 0);
    lv_obj_set_style_pad_ver(s_alerts_clear, 9, 0);
    lv_obj_set_style_margin_bottom(s_alerts_clear, 8, 0);
    lv_obj_clear_flag(s_alerts_clear, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_alerts_clear, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_alerts_clear, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_alerts_clear, alerts_clear_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *cl = lv_label_create(s_alerts_clear);
    lv_obj_remove_flag(cl, LV_OBJ_FLAG_CLICKABLE);
    lv_label_set_text(cl, "Clear all");
    lv_obj_center(cl);
    lv_obj_set_style_text_font(cl, &nocsif_mono_15, 0);
    lv_obj_set_style_text_color(cl, NOCSIF_WHITE, 0);

    /* Fixed card pool. */
    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(list, 10, 0);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    for (int i = 0; i < ALERT_VIEW_ROWS; i++) alerts_make_card(list, &s_acard[i]);

    /* Empty state. */
    s_alerts_empty = lv_label_create(content);
    lv_label_set_long_mode(s_alerts_empty, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_alerts_empty, lv_pct(100));
    lv_obj_add_style(s_alerts_empty, &nocsif_style_font_tag, 0);
    lv_obj_set_style_text_color(s_alerts_empty, NOCSIF_ASH, 0);
    lv_obj_set_style_text_align(s_alerts_empty, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_pad_top(s_alerts_empty, 30, 0);
    lv_label_set_text(s_alerts_empty,
        "No alerts\n\nphone notifications show here once paired (Cyber " NOCSIF_DOT " BLE " NOCSIF_DOT " Phone Notifications)");

    s_alerts_seen_gen = s_alog_gen - 1;   /* force a first paint */
    lv_timer_t *timer = lv_timer_create(alerts_tick_cb, 700, NULL);
    lv_obj_add_event_cb(scr, alerts_deleted_cb, LV_EVENT_DELETE, timer);
    alerts_view_refresh();
    return scr;
}

/* WiFi-page device-wide controls (auto-join + Set MAC) — these are NOT per-network, so they live
 * on the WiFi menu. wifi_menu_row + build_wifi_macmenu are defined further down (forward-declared). */
static lv_obj_t *wifi_menu_row(lv_obj_t *parent, const char *name, lv_color_t name_col,
                               const char *acc, lv_obj_t **out_acc, lv_event_cb_t cb, void *ud);
static lv_obj_t *build_wifi_macmenu(void);
static lv_obj_t *s_wifi_aj_tag;
static void wifi_page_autojoin_cb(lv_event_t *e)
{
    (void)e;
    bool on = !nocsif_wifi_autojoin();
    nocsif_wifi_set_autojoin(on);
    if (s_wifi_aj_tag) {
        lv_label_set_text(s_wifi_aj_tag, on ? "on" : "off");
    }
}
static void wifi_page_mac_cb(lv_event_t *e)
{
    (void)e;
    lv_obj_t *root = build_wifi_macmenu();
    if (root) {
        nocsif_nav_push(root);
    }
}

static const rowspec_t k_wifi_rows[] = {
        { "wifi.scan",      "Join Networks",       NOCSIF_ICON_WIFI,  "ready",   NOCSIF_TAG_READY },
        { "wifi.monitor",   "Monitor",             NOCSIF_ICON_MON,   "off",     NOCSIF_TAG_RUN, nocsif_wifi_monitor_tag_str },
        { "wifi.aplist",    "Live Networks",       NOCSIF_ICON_WIFI,  "off",     NOCSIF_TAG_RUN, nocsif_wifi_mon_ap_tag_str },
        { "wifi.stations",  "Clients",             NOCSIF_ICON_AP,    "off",     NOCSIF_TAG_RUN, nocsif_wifi_mon_sta_tag_str },
        { "wifi.probes",    "Probe Requests",      NOCSIF_ICON_HUNT,  "off",     NOCSIF_TAG_RUN, nocsif_wifi_mon_probe_tag_str },
        { "wifi.pcap",      "Record All Traffic",  NOCSIF_ICON_DRIVE, "off",     NOCSIF_TAG_RUN, nocsif_wifi_pcap_tag_str },
        { "wifi.handshake", "Handshake / PMKID",   NOCSIF_ICON_KEY,   "off",     NOCSIF_TAG_RUN, nocsif_wifi_mon_hs_tag_str },
        { "wifi.anomalies", "Anomalies",           NOCSIF_ICON_BELL,  "off",     NOCSIF_TAG_RUN, nocsif_wifi_anomaly_tag_str },
        { "wifi.mgmt",      "Management-Frame TX", NOCSIF_ICON_RADIO, "off",     NOCSIF_TAG_RUN, nocsif_wifi_mgmt_tx_tag_str },
        /* Access Point hub — the software AP plus its Captive Portal and Beacon TX live inside. */
        { "wifi.aphub",     "Access Point",        NOCSIF_ICON_AP,    NULL,      NOCSIF_TAG_NONE },
        { "wifi.wardrive",  "Wardrive",            NOCSIF_ICON_LOC,   "+gnss",   NOCSIF_TAG_VALUE },
        { "hunt",           "Signal Hunt",         NOCSIF_ICON_HUNT,  NULL,      NOCSIF_TAG_NONE },
        /* Saved networks pushed to the bottom (least-used once joined; user request). */
        { "wifi.saved",     "Saved Networks",      NOCSIF_ICON_WIFI,  NULL,      NOCSIF_TAG_NONE },
};
static lv_obj_t *build_wifi(void)
{
    nocsif_wifi_init();   /* lazy worker create (idempotent; a no-op in safe mode) */
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("WiFi", NULL, &content);
    lv_obj_t *list = nocsif_menu_list(content);

    /* M5-P1 — live connection readout at the TOP, as a TAPPABLE row (user request): opens the
     * current network's menu directly (info + settings) so you needn't rescan just to manage it.
     * "WiFi off" / "Joining <ssid>..." / "<ssid> · <ip>" / an error; accent-coloured, header-tick
     * refreshed. The radio spec moved to the bottom. */
    lv_obj_t *strow = lv_obj_create(list);
    lv_obj_remove_style_all(strow);
    lv_obj_set_width(strow, lv_pct(100));
    lv_obj_set_height(strow, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(strow, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(strow, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_ver(strow, 6, 0);
    lv_obj_set_style_pad_bottom(strow, 10, 0);
    lv_obj_clear_flag(strow, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(strow, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(strow, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(strow, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(strow, wifi_current_row_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *st = lv_label_create(strow);
    lv_label_set_long_mode(st, LV_LABEL_LONG_WRAP);
    lv_obj_set_flex_grow(st, 1);
    lv_obj_add_style(st, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(st, NOCSIF_VIOLET, 0);
    lv_label_set_text(st, nocsif_wifi_detail_str());
    nocsif_nav_register_live_label(st, nocsif_wifi_detail_str);

    lv_obj_t *chev = lv_label_create(strow);
    lv_label_set_text(chev, ">");
    lv_obj_add_style(chev, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(chev, NOCSIF_ASH, 0);

    ROWS(list, k_wifi_rows);

    /* Device-wide WiFi settings (not per-network): auto-join toggle + Set MAC address. */
    wifi_menu_row(list, "Auto-join", NOCSIF_BONE,
                  nocsif_wifi_autojoin() ? "on" : "off", &s_wifi_aj_tag, wifi_page_autojoin_cb, NULL);
    wifi_menu_row(list, "Set MAC address", NOCSIF_BONE, ">", NULL, wifi_page_mac_cb, NULL);

    /* Static radio spec at the BOTTOM (moved down from the header per user request). */
    lv_obj_t *info = lv_label_create(list);
    lv_label_set_text(info, "802.11 b/g/n " NOCSIF_DOT " 2.4 GHz " NOCSIF_DOT " esp32-s3");
    lv_obj_add_style(info, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(info, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(info, 14, 0);
    return scr;
}

/* ============================ M5-P1: WiFi scan + join =============================== *
 * The WiFi "Join Networks" row drills here. build_wifi_scan lists live APs (the worker's
 * lock-free snapshot, polled by scan generation) with the mockup's signal bars + security +
 * lock glyph; tapping an AP opens build_wifi_join (an on-screen keyboard) to enter the
 * passphrase and connect. Every screen only READS published state + POSTS worker requests —
 * no radio I/O on the LVGL task. */

/* Signal strength 0..4 bars from RSSI (dBm). */
static int wifi_bars(int8_t rssi)
{
    if (rssi >= -55) return 4;
    if (rssi >= -66) return 3;
    if (rssi >= -75) return 2;
    if (rssi >= -84) return 1;
    return 0;
}

/* Four rising bars (mockup .ap .bars) — active ones STEEL, the rest ASH. */
static void wifi_build_bars(lv_obj_t *parent, int active)
{
    static const int h[4] = { 5, 8, 11, 14 };
    lv_obj_t *box = lv_obj_create(parent);
    lv_obj_remove_style_all(box);
    lv_obj_set_size(box, 20, 14);
    lv_obj_set_flex_flow(box, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(box, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_column(box, 2, 0);
    lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
    for (int i = 0; i < 4; i++) {
        lv_obj_t *b = lv_obj_create(box);
        lv_obj_remove_style_all(b);
        lv_obj_set_size(b, 3, h[i]);
        lv_obj_set_style_radius(b, 1, 0);
        lv_obj_set_style_bg_opa(b, LV_OPA_COVER, 0);
        lv_obj_set_style_bg_color(b, (i < active) ? NOCSIF_STEEL : NOCSIF_ASH, 0);
    }
}

/* Tapped-AP target, read by build_wifi_join (built fresh per tap so it always shows the
 * tapped network — no stale-cache issue). */
static char    s_wifi_join_ssid[33];
static uint8_t s_wifi_join_auth;
static char    s_netmenu_ssid[33];        /* which saved network the per-network menu manages */
static lv_obj_t *build_wifi_join(void);
static lv_obj_t *build_wifi_connecting(void);
static lv_obj_t *build_wifi_netmenu(void);   /* tap a saved/connected net: manage/info    */
static lv_obj_t *build_wifi_macmenu(void);   /* Set MAC address: randomize / restore       */
static lv_obj_t *build_wifi_macentry(void);  /* Set MAC address: type a specific MAC        */
static lv_obj_t *build_wifi_saved(void);     /* Saved Networks list                         */

static void wifi_ap_click_cb(lv_event_t *e)
{
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    nocsif_wifi_ap_t ap;
    if (!nocsif_wifi_ap_get(idx, &ap) || ap.ssid[0] == '\0') {
        return;                          /* hidden SSID isn't tap-joinable in P1 */
    }
    const char *saved = nocsif_wifi_saved_ssid();
    bool is_saved = (saved[0] && strcmp(saved, ap.ssid) == 0);

    /* The current (connected) network -> the management menu (disconnect / forget / MAC / info). */
    if (is_saved && nocsif_wifi_connected()) {
        snprintf(s_netmenu_ssid, sizeof s_netmenu_ssid, "%s", ap.ssid);
        ESP_LOGI(TAG, "wifi netmenu: '%s' (connected)", ap.ssid);
        lv_obj_t *root = build_wifi_netmenu();
        if (root) {
            nocsif_nav_push(root);
        }
        return;
    }
    /* A saved network we're not on -> reconnect with the stored passphrase (no keyboard). */
    if (is_saved) {
        ESP_LOGI(TAG, "wifi tap saved '%s' -> reconnect (no prompt)", ap.ssid);
        nocsif_wifi_request_reconnect();
        lv_obj_t *root = build_wifi_connecting();
        if (root) {
            nocsif_nav_push(root);
        }
        return;
    }
    /* A new network -> the keyboard join flow (open nets skip the passphrase inside build_wifi_join). */
    snprintf(s_wifi_join_ssid, sizeof s_wifi_join_ssid, "%s", ap.ssid);
    s_wifi_join_auth = ap.authmode;
    ESP_LOGI(TAG, "wifi AP row tapped: idx=%d ssid='%s' auth=%u", idx, ap.ssid, ap.authmode);
    lv_obj_t *root = build_wifi_join();
    if (root) {
        nocsif_nav_push(root);
    }
}

/* One AP row: [bars] [ssid / meta] [lock?]. */
static void wifi_add_ap_row(lv_obj_t *parent, int idx, const nocsif_wifi_ap_t *ap, int order)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_remove_style_all(row);
    lv_obj_set_width(row, lv_pct(100));
    lv_obj_set_height(row, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(row, 14, 0);
    lv_obj_set_style_pad_ver(row, 15, 0);
    lv_obj_set_style_min_height(row, 60, 0);   /* generous tap target — on-wrist taps are imprecise */
    lv_obj_set_style_border_side(row, LV_BORDER_SIDE_BOTTOM, 0);
    lv_obj_set_style_border_color(row, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_width(row, 1, 0);
    lv_obj_set_style_border_opa(row, LV_OPA_COVER, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    wifi_build_bars(row, wifi_bars(ap->rssi));

    lv_obj_t *col = lv_obj_create(row);
    lv_obj_remove_style_all(col);
    lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_grow(col, 1);
    lv_obj_set_height(col, LV_SIZE_CONTENT);
    lv_obj_clear_flag(col, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *nm = lv_label_create(col);
    lv_label_set_text(nm, ap->ssid[0] ? ap->ssid : "(hidden)");
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(nm, NOCSIF_BONE, 0);
    lv_obj_set_width(nm, lv_pct(100));
    lv_label_set_long_mode(nm, LV_LABEL_LONG_DOT);

    lv_obj_t *meta = lv_label_create(col);
    lv_label_set_text_fmt(meta, "ch %d " NOCSIF_DOT " %s " NOCSIF_DOT " %d dBm",
                          ap->channel, nocsif_wifi_authmode_str(ap->authmode), ap->rssi);
    lv_obj_add_style(meta, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(meta, NOCSIF_ASH, 0);

    if (!nocsif_wifi_authmode_open(ap->authmode)) {
        lv_obj_t *lk = lv_label_create(row);
        lv_label_set_text(lk, NOCSIF_ICON_LOCK);
        lv_obj_add_style(lk, &nocsif_style_row_icon, 0);
        lv_obj_set_style_text_color(lk, NOCSIF_ASH, 0);
    }

    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, wifi_ap_click_cb, LV_EVENT_CLICKED, (void *)(intptr_t)idx);

    /* Rows appear instantly (no per-row fade): a running opacity anim under the finger made the
     * first tap get absorbed by scroll/anim handling, so a network took two taps to select. The
     * progressive reveal (P5b motion) can return later as a single non-interfering container fade. */
    (void)order;
}

/* Scan-screen widgets (single instance alive at a time — registry-cached). Nulled on the
 * screen's delete so the poll timer (also deleted then) can never touch freed objects. */
static lv_obj_t *s_scan_list, *s_scan_status, *s_scan_sweep, *s_scan_seg;
static uint32_t  s_scan_seen_gen;
static bool      s_scan_sweeping;

static void wifi_sweep_x_cb(void *obj, int32_t v) { lv_obj_set_x((lv_obj_t *)obj, v); }

static void wifi_scan_tick(lv_timer_t *t)
{
    (void)t;
    if (s_scan_list == NULL) {
        return;
    }
    bool scanning = nocsif_wifi_scanning();

    /* Sweep: animate ONLY while scanning. Under full_refresh every anim step repaints the
     * whole frame, so a sweep left running at idle would repaint forever — start on scan,
     * delete on done. */
    if (scanning && !s_scan_sweeping && s_scan_seg) {
        lv_obj_clear_flag(s_scan_sweep, LV_OBJ_FLAG_HIDDEN);
        lv_anim_t a;
        lv_anim_init(&a);
        lv_anim_set_var(&a, s_scan_seg);
        lv_anim_set_exec_cb(&a, wifi_sweep_x_cb);
        lv_anim_set_values(&a, -90, 380);
        lv_anim_set_time(&a, 1300);
        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
        lv_anim_set_path_cb(&a, lv_anim_path_linear);
        lv_anim_start(&a);
        s_scan_sweeping = true;
    } else if (!scanning && s_scan_sweeping) {
        lv_anim_delete(s_scan_seg, wifi_sweep_x_cb);
        lv_obj_add_flag(s_scan_sweep, LV_OBJ_FLAG_HIDDEN);
        s_scan_sweeping = false;
    }

    /* Status line — update-on-change (any label write is a full-frame repaint). */
    if (s_scan_status) {
        char buf[48];
        const char *msg;
        int n = nocsif_wifi_ap_count();
        if (scanning) {
            msg = "scanning...";
        } else if (n <= 0) {
            msg = "no networks " NOCSIF_NDASH " tap to rescan";
        } else {
            snprintf(buf, sizeof buf, "%d network%s " NOCSIF_DOT " tap to rescan", n, n == 1 ? "" : "s");
            msg = buf;
        }
        if (strcmp(lv_label_get_text(s_scan_status), msg) != 0) {
            lv_label_set_text(s_scan_status, msg);
        }
    }

    /* Rebuild the AP rows when a fresh scan result was published. */
    uint32_t gen = nocsif_wifi_scan_gen();
    if (gen != s_scan_seen_gen) {
        s_scan_seen_gen = gen;
        lv_obj_clean(s_scan_list);
        int n = nocsif_wifi_ap_count();
        for (int i = 0; i < n; i++) {
            nocsif_wifi_ap_t ap;
            if (nocsif_wifi_ap_get(i, &ap)) {
                wifi_add_ap_row(s_scan_list, i, &ap, i);
            }
        }
    }
}

static void wifi_scan_rescan_cb(lv_event_t *e) { (void)e; nocsif_wifi_request_scan(); }

static void wifi_scan_root_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_scan_list = s_scan_status = s_scan_sweep = s_scan_seg = NULL;
    s_scan_sweeping = false;
}

static lv_obj_t *build_wifi_scan(void)
{
    nocsif_wifi_init();   /* ensure the worker exists (idempotent; no-op in safe mode) */
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Join Networks", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset (matches the menu list) */
    /* Rigid scroll (no elastic bounce / momentum throw) so a tap on a network selects on the FIRST
     * touch — with momentum on, the first tap was being spent stopping the scroll settle. */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    /* Tappable accent status header -> rescan. */
    lv_obj_t *hdr = lv_obj_create(content);
    lv_obj_remove_style_all(hdr);
    lv_obj_set_width(hdr, lv_pct(100));
    lv_obj_set_height(hdr, LV_SIZE_CONTENT);
    lv_obj_clear_flag(hdr, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(hdr, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(hdr, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_event_cb(hdr, wifi_scan_rescan_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_set_style_pad_bottom(hdr, 6, 0);

    s_scan_status = lv_label_create(hdr);
    lv_label_set_text(s_scan_status, "scanning...");
    lv_obj_add_style(s_scan_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_scan_status, NOCSIF_VIOLET, 0);

    /* Sweep line (mockup .sweep) — hidden until scanning. */
    s_scan_sweep = lv_obj_create(content);
    lv_obj_remove_style_all(s_scan_sweep);
    lv_obj_set_size(s_scan_sweep, lv_pct(100), 2);
    lv_obj_set_style_bg_color(s_scan_sweep, NOCSIF_EDGE, 0);
    lv_obj_set_style_bg_opa(s_scan_sweep, LV_OPA_COVER, 0);
    lv_obj_clear_flag(s_scan_sweep, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_scan_sweep, LV_OBJ_FLAG_HIDDEN);
    s_scan_seg = lv_obj_create(s_scan_sweep);
    lv_obj_remove_style_all(s_scan_seg);
    lv_obj_set_size(s_scan_seg, 90, 2);
    lv_obj_set_style_bg_color(s_scan_seg, NOCSIF_VIOLET, 0);
    lv_obj_set_style_bg_opa(s_scan_seg, LV_OPA_COVER, 0);

    /* AP list — grows with content; the scaffold's content column scrolls. */
    s_scan_list = lv_obj_create(content);
    lv_obj_remove_style_all(s_scan_list);
    lv_obj_set_width(s_scan_list, lv_pct(100));
    lv_obj_set_height(s_scan_list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_scan_list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(s_scan_list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(s_scan_list, 4, 0);

    s_scan_sweeping = false;

    lv_timer_t *timer = lv_timer_create(wifi_scan_tick, 300, NULL);
    lv_obj_add_event_cb(scr, wifi_scan_root_deleted_cb, LV_EVENT_DELETE, timer);

    /* Seed any cached results (the last scan) at once, then kick a fresh scan. Holding
     * s_scan_seen_gen at the current gen means the tick rebuilds only when a NEW scan lands, so
     * the status label stays "scanning..." (set above) with no "no networks" flash on entry. */
    int n0 = nocsif_wifi_ap_count();
    for (int i = 0; i < n0; i++) {
        nocsif_wifi_ap_t ap;
        if (nocsif_wifi_ap_get(i, &ap)) wifi_add_ap_row(s_scan_list, i, &ap, i);
    }
    s_scan_seen_gen = nocsif_wifi_scan_gen();
    nocsif_wifi_request_scan();
    return scr;
}

/* ---- join screen: SSID + on-screen keyboard --------------------------------------- */

/* Shared submit: request the join and open the full-screen connecting view. The keyboard
 * screen stays underneath, so "Try Again" on a failure returns to it with the text intact. */
static void wifi_do_join(lv_obj_t *ta)
{
    const char *pass = ta ? lv_textarea_get_text(ta) : "";
    nocsif_wifi_request_connect(s_wifi_join_ssid, pass);
    lv_obj_t *root = build_wifi_connecting();
    if (root) {
        nocsif_nav_push(root);
    }
}
static void wifi_join_ready_cb(lv_event_t *e)   /* keyboard ✓ / apply key */
{
    wifi_do_join(lv_keyboard_get_textarea(lv_event_get_target(e)));
}
static void wifi_join_btn_cb(lv_event_t *e)     /* the explicit Join button */
{
    wifi_do_join((lv_obj_t *)lv_event_get_user_data(e));
}
static void wifi_join_cancel_cb(lv_event_t *e) { (void)e; nocsif_nav_back(); }

/* Show/hide-password toggle. Default SHOWN (on-wrist typing wants to see the characters); the box
 * fills when shown and the label states the current mode ("Show password" / "Hide password"). */
static lv_obj_t *s_join_pw_box, *s_join_pw_lbl;
static bool      s_join_pw_shown;
static void wifi_join_pw_cb(lv_event_t *e)
{
    lv_obj_t *ta = (lv_obj_t *)lv_event_get_user_data(e);
    s_join_pw_shown = !s_join_pw_shown;
    lv_textarea_set_password_mode(ta, !s_join_pw_shown);
    if (s_join_pw_box) {
        lv_obj_set_style_bg_opa(s_join_pw_box, s_join_pw_shown ? LV_OPA_COVER : LV_OPA_TRANSP, 0);
    }
    if (s_join_pw_lbl) {
        lv_label_set_text(s_join_pw_lbl, s_join_pw_shown ? "Hide password" : "Show password");
    }
}

static lv_obj_t *build_wifi_join(void)
{
    bool open = nocsif_wifi_authmode_open(s_wifi_join_auth);
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Join", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */

    lv_obj_t *ss = lv_label_create(content);
    lv_label_set_text(ss, s_wifi_join_ssid);
    lv_obj_add_style(ss, &nocsif_style_title, 0);
    lv_obj_set_style_text_color(ss, NOCSIF_WHITE, 0);
    lv_obj_set_width(ss, lv_pct(100));
    lv_label_set_long_mode(ss, LV_LABEL_LONG_DOT);

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, open ? "open network " NOCSIF_DOT " no password needed"
                                  : "type the password, then tap Join");
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 6, 0);

    lv_obj_t *ta = lv_textarea_create(content);
    lv_textarea_set_one_line(ta, true);
    lv_textarea_set_password_mode(ta, false);   /* default SHOWN; the toggle below can hide it */
    lv_textarea_set_password_bullet(ta, "*");   /* mask with '*' (in-font) not the default bullet */
    lv_textarea_set_placeholder_text(ta, open ? "(no password needed)" : "password");
    lv_obj_set_width(ta, lv_pct(100));
    lv_obj_set_style_bg_color(ta, NOCSIF_PIT, 0);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(ta, NOCSIF_BONE, 0);
    lv_obj_add_style(ta, &nocsif_style_row_name, 0);    /* mono: 'l' reads clearly, not like a caret */
    lv_obj_set_style_border_color(ta, NOCSIF_EDGE2, 0);
    lv_obj_set_style_border_width(ta, 1, 0);
    lv_obj_set_style_radius(ta, 6, 0);
    lv_obj_set_style_bg_color(ta, NOCSIF_VIOLET, LV_PART_CURSOR);   /* violet caret, unmistakable */
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, LV_PART_CURSOR);

    /* Show/hide-password checkbox (secured nets only). Default = shown (box filled). */
    if (!open) {
        s_join_pw_shown = true;
        lv_obj_t *pw = lv_obj_create(content);
        lv_obj_remove_style_all(pw);
        lv_obj_set_width(pw, lv_pct(100));
        lv_obj_set_height(pw, LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(pw, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(pw, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_column(pw, 10, 0);
        lv_obj_set_style_pad_ver(pw, 8, 0);
        lv_obj_clear_flag(pw, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_add_flag(pw, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_flag(pw, LV_OBJ_FLAG_GESTURE_BUBBLE);
        lv_obj_add_style(pw, &nocsif_style_row_press, LV_STATE_PRESSED);

        s_join_pw_box = lv_obj_create(pw);
        lv_obj_remove_style_all(s_join_pw_box);
        lv_obj_set_size(s_join_pw_box, 20, 20);
        lv_obj_set_style_radius(s_join_pw_box, 4, 0);
        lv_obj_set_style_border_color(s_join_pw_box, NOCSIF_VIOLET, 0);
        lv_obj_set_style_border_width(s_join_pw_box, 2, 0);
        lv_obj_set_style_bg_color(s_join_pw_box, NOCSIF_VIOLET, 0);
        lv_obj_set_style_bg_opa(s_join_pw_box, LV_OPA_COVER, 0);   /* filled = shown */
        lv_obj_clear_flag(s_join_pw_box, LV_OBJ_FLAG_SCROLLABLE);

        s_join_pw_lbl = lv_label_create(pw);
        lv_label_set_text(s_join_pw_lbl, "Hide password");   /* default shown -> tap hides */
        lv_obj_add_style(s_join_pw_lbl, &nocsif_style_row_name, 0);
        lv_obj_set_style_text_color(s_join_pw_lbl, NOCSIF_BONE, 0);

        lv_obj_add_event_cb(pw, wifi_join_pw_cb, LV_EVENT_CLICKED, ta);
    } else {
        s_join_pw_box = s_join_pw_lbl = NULL;
    }

    /* Explicit Join button — the on-wrist "enter", clearer than hunting for the keyboard's key. */
    lv_obj_t *join = lv_obj_create(content);
    lv_obj_remove_style_all(join);
    lv_obj_set_width(join, lv_pct(100));
    lv_obj_set_height(join, LV_SIZE_CONTENT);
    lv_obj_set_style_margin_top(join, 8, 0);
    lv_obj_set_style_bg_color(join, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_bg_opa(join, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(join, NOCSIF_VIOLET, 0);
    lv_obj_set_style_border_width(join, 1, 0);
    lv_obj_set_style_radius(join, 8, 0);
    lv_obj_set_style_pad_ver(join, 11, 0);
    lv_obj_clear_flag(join, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(join, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(join, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(join, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_t *jl = lv_label_create(join);
    lv_label_set_text(jl, "Join");
    lv_obj_center(jl);
    lv_obj_add_style(jl, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(jl, NOCSIF_WHITE, 0);
    lv_obj_add_event_cb(join, wifi_join_btn_cb, LV_EVENT_CLICKED, ta);

    /* Keyboard: LIFTED above the rounded bottom corners (they were clipping the ✓/close keys) and
     * enlarged. IGNORE_LAYOUT keeps it out of the scaffold's flex column; bottom ~444 clears the
     * ~56px corner arc so every key is fully tappable. */
    lv_obj_t *kb = lv_keyboard_create(scr);
    lv_obj_add_flag(kb, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_keyboard_set_textarea(kb, ta);
    nocsif_companion_track_ta(ta);   /* §4.8a P2: remote /api/type targets this field */
    lv_keyboard_set_mode(kb, LV_KEYBOARD_MODE_TEXT_LOWER);
    lv_obj_set_size(kb, lv_pct(100), 196);
    lv_obj_align(kb, LV_ALIGN_BOTTOM_MID, 0, -58);
    lv_obj_set_style_bg_color(kb, NOCSIF_VOID, 0);
    lv_obj_set_style_bg_opa(kb, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(kb, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_all(kb, 3, 0);
    lv_obj_add_event_cb(kb, wifi_join_ready_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(kb, wifi_join_cancel_cb, LV_EVENT_CANCEL, NULL);
    return scr;
}

/* ---- connecting screen: full-screen join status (joining / wrong password / connected) --- */
static lv_obj_t *s_conn_status, *s_conn_btn, *s_conn_btnlbl;

static void wifi_conn_action_cb(lv_event_t *e)
{
    (void)e;
    if (nocsif_wifi_join_state() == NOCSIF_WIFI_JOIN_CONNECTED) {
        nocsif_app_launch("wifi");   /* Done -> WiFi menu (shows "<ssid> · <ip>") */
    } else {
        nocsif_nav_back();           /* Try Again -> back to the keyboard, text intact */
    }
}

static void wifi_conn_tick(lv_timer_t *t)
{
    (void)t;
    if (s_conn_status == NULL) {
        return;
    }
    const char *msg = nocsif_wifi_detail_str();
    if (strcmp(lv_label_get_text(s_conn_status), msg) != 0) {
        lv_label_set_text(s_conn_status, msg);
    }
    nocsif_wifi_join_state_t st = nocsif_wifi_join_state();
    lv_color_t col = NOCSIF_VIOLET;                 /* joining */
    if (st == NOCSIF_WIFI_JOIN_CONNECTED) {
        col = NOCSIF_WHITE;
        lv_label_set_text(s_conn_btnlbl, "Done");
        lv_obj_clear_flag(s_conn_btn, LV_OBJ_FLAG_HIDDEN);
    } else if (st == NOCSIF_WIFI_JOIN_FAILED) {
        col = NOCSIF_GOLD;
        lv_label_set_text(s_conn_btnlbl, "Try Again");
        lv_obj_clear_flag(s_conn_btn, LV_OBJ_FLAG_HIDDEN);
    } else {
        lv_obj_add_flag(s_conn_btn, LV_OBJ_FLAG_HIDDEN);   /* still joining: no button yet */
    }
    lv_obj_set_style_text_color(s_conn_status, col, 0);
}

static void wifi_conn_root_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_conn_status = s_conn_btn = s_conn_btnlbl = NULL;
}

static lv_obj_t *build_wifi_connecting(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("WiFi", NULL, &content);
    lv_obj_set_style_pad_hor(content, 30, 0);
    lv_obj_set_flex_align(content, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    s_conn_status = lv_label_create(content);
    lv_label_set_long_mode(s_conn_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_conn_status, lv_pct(100));
    lv_obj_set_style_text_align(s_conn_status, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_add_style(s_conn_status, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_conn_status, NOCSIF_VIOLET, 0);
    lv_label_set_text(s_conn_status, nocsif_wifi_detail_str());
    lv_obj_set_style_pad_bottom(s_conn_status, 26, 0);

    s_conn_btn = lv_obj_create(content);
    lv_obj_remove_style_all(s_conn_btn);
    lv_obj_set_width(s_conn_btn, 190);
    lv_obj_set_height(s_conn_btn, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(s_conn_btn, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_bg_opa(s_conn_btn, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(s_conn_btn, NOCSIF_VIOLET, 0);
    lv_obj_set_style_border_width(s_conn_btn, 1, 0);
    lv_obj_set_style_radius(s_conn_btn, 8, 0);
    lv_obj_set_style_pad_ver(s_conn_btn, 13, 0);
    lv_obj_clear_flag(s_conn_btn, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_conn_btn, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_conn_btn, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_conn_btn, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_flag(s_conn_btn, LV_OBJ_FLAG_HIDDEN);
    s_conn_btnlbl = lv_label_create(s_conn_btn);
    lv_label_set_text(s_conn_btnlbl, "Done");
    lv_obj_center(s_conn_btnlbl);
    lv_obj_add_style(s_conn_btnlbl, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_conn_btnlbl, NOCSIF_WHITE, 0);
    lv_obj_add_event_cb(s_conn_btn, wifi_conn_action_cb, LV_EVENT_CLICKED, NULL);

    lv_timer_t *timer = lv_timer_create(wifi_conn_tick, 200, NULL);
    lv_obj_add_event_cb(scr, wifi_conn_root_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_conn_tick(timer);   /* seed immediately */
    return scr;
}

/* ==================== M5-P1: per-network menu (manage a saved network) ==================== *
 * Tapping the CONNECTED network opens this: read-only link info (IP / subnet / router / MAC)
 * plus actions — Auto-join toggle, Set MAC address (drills to the spoof screen), Disconnect,
 * Forget. Every field READS published wifi.c state; the actions only POST worker requests. */

/* Update a label only when its text actually changed (any write is a full-frame repaint under
 * full_refresh, so guarding on change keeps idle ticks from repainting the whole screen). */
static void wifi_set_label(lv_obj_t *l, const char *s)
{
    if (l && strcmp(lv_label_get_text(l), s) != 0) {
        lv_label_set_text(l, s);
    }
}

/* One read-only "key   value" row for the info card. Returns the VALUE label (for live update). */
static lv_obj_t *wifi_kv_row(lv_obj_t *parent, const char *key, const char *val)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_remove_style_all(row);
    lv_obj_set_width(row, lv_pct(100));
    lv_obj_set_height(row, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_ver(row, 4, 0);
    lv_obj_set_style_pad_column(row, 10, 0);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *k = lv_label_create(row);
    lv_label_set_text(k, key);
    lv_obj_add_style(k, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(k, NOCSIF_STEEL, 0);
    lv_obj_set_width(k, 66);

    lv_obj_t *v = lv_label_create(row);
    lv_label_set_text(v, val);
    lv_obj_add_style(v, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(v, NOCSIF_BONE, 0);
    lv_obj_set_flex_grow(v, 1);
    return v;
}

/* One full-width tappable action row: [name .......... accessory]. *out_acc (if non-NULL)
 * receives the right accessory label (a live on/off tag or a ">" chevron) for later updates. */
static lv_obj_t *wifi_menu_row(lv_obj_t *parent, const char *name, lv_color_t name_col,
                               const char *acc, lv_obj_t **out_acc, lv_event_cb_t cb, void *ud)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_remove_style_all(row);
    lv_obj_set_width(row, lv_pct(100));
    lv_obj_set_height(row, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_ver(row, 15, 0);
    lv_obj_set_style_min_height(row, 56, 0);
    lv_obj_set_style_border_side(row, LV_BORDER_SIDE_BOTTOM, 0);
    lv_obj_set_style_border_color(row, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_width(row, 1, 0);
    lv_obj_set_style_border_opa(row, LV_OPA_COVER, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *nm = lv_label_create(row);
    lv_label_set_text(nm, name);
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(nm, name_col, 0);
    lv_obj_set_flex_grow(nm, 1);

    lv_obj_t *acc_lbl = NULL;
    if (acc) {
        acc_lbl = lv_label_create(row);
        lv_label_set_text(acc_lbl, acc);
        lv_obj_add_style(acc_lbl, &nocsif_style_row_name, 0);
        lv_obj_set_style_text_color(acc_lbl, NOCSIF_STEEL, 0);
    }
    if (out_acc) {
        *out_acc = acc_lbl;
    }
    if (cb) {
        lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(row, cb, LV_EVENT_CLICKED, ud);
    }
    return row;
}

/* Live handles for the two management screens (nulled on delete so the ticks are safe). */
static lv_obj_t *s_nm_status, *s_nm_ip, *s_nm_mask, *s_nm_gw, *s_nm_mac;
static lv_obj_t *s_nm_pw, *s_nm_pw_acc;   /* saved-password reveal (value + "show"/"hide" tag) */
static bool      s_nm_pw_shown;
static lv_obj_t *s_mm_mac;

static void wifi_nm_disconnect_cb(lv_event_t *e) { (void)e; nocsif_wifi_request_disconnect(); nocsif_nav_back(); }
static void wifi_nm_forget_cb(lv_event_t *e)     { (void)e; nocsif_wifi_forget_ssid(s_netmenu_ssid); nocsif_app_launch("wifi"); }
static void wifi_nm_connect_cb(lv_event_t *e)
{
    (void)e;
    nocsif_wifi_connect_saved(s_netmenu_ssid);       /* stored passphrase, no prompt */
    lv_obj_t *root = build_wifi_connecting();
    if (root) {
        nocsif_nav_push(root);
    }
}
static void wifi_nm_showpw_cb(lv_event_t *e)
{
    (void)e;
    s_nm_pw_shown = !s_nm_pw_shown;
    const char *p = nocsif_wifi_pass_of(s_netmenu_ssid);
    if (s_nm_pw)     lv_label_set_text(s_nm_pw, s_nm_pw_shown ? (p[0] ? p : "(none)") : "********");
    if (s_nm_pw_acc) lv_label_set_text(s_nm_pw_acc, s_nm_pw_shown ? "hide" : "show");
}

static void wifi_netmenu_tick(lv_timer_t *t)
{
    (void)t;
    if (s_nm_status == NULL) {
        return;
    }
    bool conn = nocsif_wifi_connected();
    char buf[72];
    if (conn) {
        snprintf(buf, sizeof buf, "connected " NOCSIF_DOT " %s", nocsif_wifi_ip_str());
    } else {
        snprintf(buf, sizeof buf, "saved " NOCSIF_DOT " not connected");
    }
    wifi_set_label(s_nm_status, buf);
    lv_obj_set_style_text_color(s_nm_status, conn ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    const char *ip = nocsif_wifi_ip_str(), *nm = nocsif_wifi_netmask_str(), *gw = nocsif_wifi_gateway_str();
    wifi_set_label(s_nm_ip,   ip[0] ? ip : NOCSIF_NDASH);
    wifi_set_label(s_nm_mask, nm[0] ? nm : NOCSIF_NDASH);
    wifi_set_label(s_nm_gw,   gw[0] ? gw : NOCSIF_NDASH);
    wifi_set_label(s_nm_mac,  nocsif_wifi_mac_str());
}

static void wifi_netmenu_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_nm_status = s_nm_ip = s_nm_mask = s_nm_gw = s_nm_mac = NULL;
    s_nm_pw = s_nm_pw_acc = NULL;
}

static lv_obj_t *build_wifi_netmenu(void)
{
    /* Is this the network we're actually on right now? (drives Connect vs Disconnect). */
    bool connected_here = nocsif_wifi_connected() &&
                          strcmp(nocsif_wifi_saved_ssid(), s_netmenu_ssid) == 0;
    bool secured = nocsif_wifi_pass_of(s_netmenu_ssid)[0] != '\0';
    s_nm_pw_shown = false;

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Network", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *ss = lv_label_create(content);
    lv_label_set_text(ss, s_netmenu_ssid);
    lv_obj_add_style(ss, &nocsif_style_title, 0);
    lv_obj_set_style_text_color(ss, NOCSIF_WHITE, 0);
    lv_obj_set_width(ss, lv_pct(100));
    lv_label_set_long_mode(ss, LV_LABEL_LONG_DOT);

    s_nm_status = lv_label_create(content);
    lv_obj_add_style(s_nm_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_nm_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_nm_status, "");
    lv_obj_set_style_pad_bottom(s_nm_status, 12, 0);

    /* read-only link info */
    s_nm_ip   = wifi_kv_row(content, "IP",     NOCSIF_NDASH);
    s_nm_mask = wifi_kv_row(content, "Subnet", NOCSIF_NDASH);
    s_nm_gw   = wifi_kv_row(content, "Router", NOCSIF_NDASH);
    s_nm_mac  = wifi_kv_row(content, "MAC",    NOCSIF_NDASH);
    if (secured) {
        s_nm_pw = wifi_kv_row(content, "Password", "********");   /* revealed by "Show password" */
    } else {
        s_nm_pw = NULL;
    }

    lv_obj_t *gap = lv_obj_create(content);   /* small spacer before the actions */
    lv_obj_remove_style_all(gap);
    lv_obj_set_size(gap, 1, 10);

    /* actions (auto-join + MAC are device-wide -> they live on the WiFi page, not per-network) */
    if (secured) {
        wifi_menu_row(content, "Show password", NOCSIF_BONE, "show", &s_nm_pw_acc, wifi_nm_showpw_cb, NULL);
    }
    if (connected_here) {
        wifi_menu_row(content, "Disconnect",  NOCSIF_VIOLET, NULL, NULL, wifi_nm_disconnect_cb, NULL);
    } else {
        wifi_menu_row(content, "Connect",     NOCSIF_VIOLET, NULL, NULL, wifi_nm_connect_cb, NULL);
    }
    wifi_menu_row(content, "Forget network",  NOCSIF_GOLD, NULL, NULL, wifi_nm_forget_cb, NULL);

    lv_timer_t *timer = lv_timer_create(wifi_netmenu_tick, 250, NULL);
    lv_obj_add_event_cb(scr, wifi_netmenu_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_netmenu_tick(timer);   /* seed immediately */
    return scr;
}

/* The WiFi menu's top status row -> the current/saved network's management menu (no rescan). */
static void wifi_current_row_cb(lv_event_t *e)
{
    (void)e;
    const char *s = nocsif_wifi_saved_ssid();
    if (s[0] == '\0') {
        return;                 /* nothing saved/connected to manage yet */
    }
    snprintf(s_netmenu_ssid, sizeof s_netmenu_ssid, "%s", s);
    lv_obj_t *root = build_wifi_netmenu();
    if (root) {
        nocsif_nav_push(root);
    }
}

/* ---- Set MAC address: show the current station MAC, randomize / type / restore ------ */
static void wifi_mm_rand_cb(lv_event_t *e)  { (void)e; nocsif_wifi_request_randomize_mac(); }
static void wifi_mm_rest_cb(lv_event_t *e)  { (void)e; nocsif_wifi_request_restore_mac(); }
static void wifi_mm_enter_cb(lv_event_t *e) { (void)e; lv_obj_t *r = build_wifi_macentry(); if (r) nocsif_nav_push(r); }

static void wifi_macmenu_tick(lv_timer_t *t)
{
    (void)t;
    if (s_mm_mac) {
        wifi_set_label(s_mm_mac, nocsif_wifi_mac_str());
    }
}

static void wifi_macmenu_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_mm_mac = NULL;
}

static lv_obj_t *build_wifi_macmenu(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("MAC address", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_mm_mac = lv_label_create(content);
    lv_label_set_text(s_mm_mac, nocsif_wifi_mac_str());
    lv_obj_set_style_text_font(s_mm_mac, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(s_mm_mac, NOCSIF_WHITE, 0);
    lv_obj_set_style_pad_top(s_mm_mac, 4, 0);

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, "station address " NOCSIF_DOT " spoof for this session");
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 12, 0);

    wifi_menu_row(content, "Randomize",         NOCSIF_BONE, NULL, NULL, wifi_mm_rand_cb,  NULL);
    wifi_menu_row(content, "Enter MAC address", NOCSIF_BONE, ">",  NULL, wifi_mm_enter_cb, NULL);
    wifi_menu_row(content, "Restore default",   NOCSIF_BONE, NULL, NULL, wifi_mm_rest_cb,  NULL);

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_text(note, "locally-administered address " NOCSIF_DOT " the link re-joins after a change");
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(note, 14, 0);

    lv_timer_t *timer = lv_timer_create(wifi_macmenu_tick, 250, NULL);
    lv_obj_add_event_cb(scr, wifi_macmenu_deleted_cb, LV_EVENT_DELETE, timer);
    return scr;
}

/* ---- Set MAC address: type a specific MAC (keyboard) -------------------------------- */
/* Parse "aa:bb:cc:dd:ee:ff" (any non-hex separators ignored, so colons are optional) into 6
 * bytes. Returns false unless exactly 6 whole bytes were read. */
static bool wifi_parse_mac(const char *s, uint8_t out[6])
{
    int n = 0, nib = 0;
    uint8_t cur = 0;
    for (const char *p = s; *p; p++) {
        int v;
        char c = *p;
        if (c >= '0' && c <= '9')      v = c - '0';
        else if (c >= 'a' && c <= 'f') v = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') v = c - 'A' + 10;
        else continue;                    /* skip ':', '-', spaces */
        cur = (uint8_t)((cur << 4) | v);
        if (++nib == 2) {
            if (n >= 6) return false;     /* too many bytes */
            out[n++] = cur;
            cur = 0; nib = 0;
        }
    }
    return (n == 6 && nib == 0);
}

static lv_obj_t *s_me_hint;
static void wifi_macentry_apply(lv_obj_t *ta)
{
    uint8_t mac[6];
    const char *txt = ta ? lv_textarea_get_text(ta) : "";
    if (!wifi_parse_mac(txt, mac)) {
        if (s_me_hint) lv_label_set_text(s_me_hint, "need 6 hex bytes, e.g. a2:71:4c:8f:0b:19");
        return;
    }
    if (mac[0] & 0x01) {                   /* bit0 set = multicast; a station MAC must be unicast */
        if (s_me_hint) lv_label_set_text(s_me_hint, "first byte must be even (unicast)");
        return;
    }
    nocsif_wifi_request_set_mac(mac);
    nocsif_nav_back();
}
static void wifi_macentry_ready_cb(lv_event_t *e)  { wifi_macentry_apply(lv_keyboard_get_textarea(lv_event_get_target(e))); }
static void wifi_macentry_btn_cb(lv_event_t *e)    { wifi_macentry_apply((lv_obj_t *)lv_event_get_user_data(e)); }
static void wifi_macentry_cancel_cb(lv_event_t *e) { (void)e; nocsif_nav_back(); }

