/* ---- Saved Networks: the remembered profiles (tap -> that network's menu) ----------- */
static void wifi_saved_row_cb(lv_event_t *e)
{
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    if (!nocsif_wifi_saved_ssid_at(idx, s_netmenu_ssid, sizeof s_netmenu_ssid)) {
        return;
    }
    lv_obj_t *root = build_wifi_netmenu();
    if (root) {
        nocsif_nav_push(root);
    }
}

static lv_obj_t *build_wifi_saved(void)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Saved Networks", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    int n = nocsif_wifi_saved_count();
    if (n <= 0) {
        lv_obj_t *empty = lv_label_create(content);
        lv_label_set_text(empty, "no saved networks yet " NOCSIF_NDASH " join one to remember it");
        lv_label_set_long_mode(empty, LV_LABEL_LONG_WRAP);
        lv_obj_set_width(empty, lv_pct(100));
        lv_obj_add_style(empty, &nocsif_style_row_name, 0);
        lv_obj_set_style_text_color(empty, NOCSIF_STEEL, 0);
        return scr;
    }

    const char *cur = nocsif_wifi_saved_ssid();
    bool conn = nocsif_wifi_connected();
    for (int i = 0; i < n; i++) {
        char ssid[33];
        if (!nocsif_wifi_saved_ssid_at(i, ssid, sizeof ssid)) {
            continue;
        }
        bool is_cur = (cur[0] && strcmp(cur, ssid) == 0);
        const char *tag = (is_cur && conn) ? "connected" : (is_cur ? "current" : "saved");
        wifi_menu_row(content, ssid, NOCSIF_BONE, tag, NULL, wifi_saved_row_cb, (void *)(intptr_t)i);
    }
    return scr;
}

/* ============================ M5-P2: WiFi monitor (capture) ======================== *
 * Fills the wifi.monitor stub. A live readout of promiscuous 802.11 capture (frames/sec, total,
 * type breakdown, a per-channel activity spectrum) with Start/Stop, Hop/Lock and channel-select
 * controls. Every field READS published wifi.c state; controls only POST worker requests — no
 * radio I/O on the LVGL task. Capture keeps running when the screen is left (only Stop or WiFi-off
 * ends it), so the radio can be stressed while roaming the live UI. */

/* Live handles (single instance; nulled on delete so the poll tick can't touch freed objects). */
static lv_obj_t *s_mon_status, *s_mon_rate_lbl, *s_mon_total_lbl;
static lv_obj_t *s_mon_mgmt, *s_mon_ctrl, *s_mon_data, *s_mon_rssi;
static lv_obj_t *s_mon_bars[13];
static lv_obj_t *s_mon_start_lbl, *s_mon_mode_acc, *s_mon_chan_acc;
static uint8_t   s_mon_bar_h[13];       /* last applied bar height (skip no-op layout writes) */
static uint8_t   s_mon_bar_state[13];   /* last applied colour: 0 ash / 1 steel / 2 violet    */

static void wifi_mon_start_cb(lv_event_t *e)
{
    (void)e;
    nocsif_wifi_request_monitor(!nocsif_wifi_monitor_active());
}
static void wifi_mon_mode_cb(lv_event_t *e)
{
    (void)e;
    nocsif_wifi_request_monitor_hop(!nocsif_wifi_monitor_hopping());
}
static void wifi_mon_chan_cb(lv_event_t *e)
{
    (void)e;
    int ch = nocsif_wifi_monitor_channel();
    if (nocsif_wifi_monitor_hopping()) {
        nocsif_wifi_request_monitor_channel(ch);        /* first tap: lock to the current channel */
    } else {
        nocsif_wifi_request_monitor_channel(ch >= 13 ? 1 : ch + 1);   /* then step through 1..13 */
    }
}

static void wifi_monitor_tick(lv_timer_t *t)
{
    (void)t;
    if (s_mon_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_monitor_active();
    bool hop    = nocsif_wifi_monitor_hopping();
    int  ch     = nocsif_wifi_monitor_channel();
    char buf[64];

    if (active) {
        snprintf(buf, sizeof buf, "capturing \xC2\xB7 ch %d \xC2\xB7 %s", ch, hop ? "hop" : "lock");
    } else {
        snprintf(buf, sizeof buf, "stopped \xC2\xB7 tap Start");
    }
    wifi_set_label(s_mon_status, buf);
    lv_obj_set_style_text_color(s_mon_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    snprintf(buf, sizeof buf, "%u", (unsigned)nocsif_wifi_monitor_rate());
    wifi_set_label(s_mon_rate_lbl, buf);
    snprintf(buf, sizeof buf, "%u frames", (unsigned)nocsif_wifi_monitor_total());
    wifi_set_label(s_mon_total_lbl, buf);

    snprintf(buf, sizeof buf, "%u", (unsigned)nocsif_wifi_monitor_count(NOCSIF_WIFI_PKT_MGMT));
    wifi_set_label(s_mon_mgmt, buf);
    snprintf(buf, sizeof buf, "%u", (unsigned)nocsif_wifi_monitor_count(NOCSIF_WIFI_PKT_CTRL));
    wifi_set_label(s_mon_ctrl, buf);
    snprintf(buf, sizeof buf, "%u", (unsigned)nocsif_wifi_monitor_count(NOCSIF_WIFI_PKT_DATA));
    wifi_set_label(s_mon_data, buf);
    int8_t last = nocsif_wifi_monitor_rssi_last();
    if (last == 0) snprintf(buf, sizeof buf, "%s", NOCSIF_NDASH);
    else           snprintf(buf, sizeof buf, "%d dBm", last);
    wifi_set_label(s_mon_rssi, buf);

    /* Per-channel activity bars, scaled to the busiest channel. Guarded so an idle screen with
     * unchanged tallies performs no layout write (every write is a full-frame repaint). */
    uint32_t maxc = 1;
    for (int c = 1; c <= 13; c++) {
        uint32_t v = nocsif_wifi_monitor_ch_count(c);
        if (v > maxc) maxc = v;
    }
    for (int c = 1; c <= 13; c++) {
        lv_obj_t *b = s_mon_bars[c - 1];
        if (!b) continue;
        uint32_t v = nocsif_wifi_monitor_ch_count(c);
        int h = 4 + (int)((v * 30) / maxc);
        if (h > 34) h = 34;
        uint8_t st = (active && c == ch) ? 2 : (v ? 1 : 0);
        if ((uint8_t)h != s_mon_bar_h[c - 1]) {
            s_mon_bar_h[c - 1] = (uint8_t)h;
            lv_obj_set_height(b, h);
        }
        if (st != s_mon_bar_state[c - 1]) {
            s_mon_bar_state[c - 1] = st;
            lv_obj_set_style_bg_color(b, st == 2 ? NOCSIF_VIOLET : st == 1 ? NOCSIF_STEEL : NOCSIF_ASH, 0);
        }
    }

    wifi_set_label(s_mon_start_lbl, active ? "Stop capture" : "Start capture");
    wifi_set_label(s_mon_mode_acc,  hop ? "hop" : "lock");
    if (hop) {
        wifi_set_label(s_mon_chan_acc, "auto");
    } else {
        snprintf(buf, sizeof buf, "%d", ch);
        wifi_set_label(s_mon_chan_acc, buf);
    }
}

static void wifi_monitor_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_mon_status = s_mon_rate_lbl = s_mon_total_lbl = NULL;
    s_mon_mgmt = s_mon_ctrl = s_mon_data = s_mon_rssi = NULL;
    s_mon_start_lbl = s_mon_mode_acc = s_mon_chan_acc = NULL;
    for (int c = 0; c < 13; c++) s_mon_bars[c] = NULL;
}

static lv_obj_t *build_wifi_monitor(void)
{
    nocsif_wifi_init();   /* ensure the worker exists (idempotent; no-op in safe mode) */
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Monitor", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    /* Status line (accent while capturing). */
    s_mon_status = lv_label_create(content);
    lv_obj_add_style(s_mon_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_mon_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_mon_status, "stopped \xC2\xB7 tap Start");
    lv_obj_set_style_pad_bottom(s_mon_status, 10, 0);

    /* Hero rate: big frames/sec number + caption + running total. */
    lv_obj_t *hero = lv_obj_create(content);
    lv_obj_remove_style_all(hero);
    lv_obj_set_width(hero, lv_pct(100));
    lv_obj_set_height(hero, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(hero, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(hero, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_column(hero, 10, 0);
    lv_obj_clear_flag(hero, LV_OBJ_FLAG_SCROLLABLE);

    s_mon_rate_lbl = lv_label_create(hero);
    lv_label_set_text(s_mon_rate_lbl, "0");
    lv_obj_set_style_text_font(s_mon_rate_lbl, &nocsif_num_48, 0);
    lv_obj_set_style_text_color(s_mon_rate_lbl, NOCSIF_WHITE, 0);

    lv_obj_t *hcol = lv_obj_create(hero);
    lv_obj_remove_style_all(hcol);
    lv_obj_set_flex_flow(hcol, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_height(hcol, LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(hcol, 1);
    lv_obj_clear_flag(hcol, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_bottom(hcol, 6, 0);

    lv_obj_t *rcap = lv_label_create(hcol);
    lv_label_set_text(rcap, "frames/sec");
    lv_obj_add_style(rcap, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(rcap, NOCSIF_STEEL, 0);

    s_mon_total_lbl = lv_label_create(hcol);
    lv_label_set_text(s_mon_total_lbl, "0 frames");
    lv_obj_add_style(s_mon_total_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_mon_total_lbl, NOCSIF_ASH, 0);

    /* Type breakdown (reuses the netmenu key/value row; returns the value label for live update). */
    s_mon_mgmt = wifi_kv_row(content, "mgmt", "0");
    s_mon_ctrl = wifi_kv_row(content, "ctrl", "0");
    s_mon_data = wifi_kv_row(content, "data", "0");
    s_mon_rssi = wifi_kv_row(content, "RSSI", NOCSIF_NDASH);

    /* Per-channel activity spectrum (1..13). */
    lv_obj_t *chcap = lv_label_create(content);
    lv_label_set_text(chcap, "channel activity 1-13");
    lv_obj_add_style(chcap, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(chcap, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(chcap, 12, 0);

    lv_obj_t *chbox = lv_obj_create(content);
    lv_obj_remove_style_all(chbox);
    lv_obj_set_width(chbox, lv_pct(100));
    lv_obj_set_height(chbox, 40);
    lv_obj_set_flex_flow(chbox, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(chbox, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_clear_flag(chbox, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(chbox, 6, 0);
    for (int c = 0; c < 13; c++) {
        lv_obj_t *b = lv_obj_create(chbox);
        lv_obj_remove_style_all(b);
        lv_obj_set_size(b, 12, 4);
        lv_obj_set_style_radius(b, 1, 0);
        lv_obj_set_style_bg_opa(b, LV_OPA_COVER, 0);
        lv_obj_set_style_bg_color(b, NOCSIF_ASH, 0);
        s_mon_bars[c] = b;
        s_mon_bar_h[c] = 4;
        s_mon_bar_state[c] = 0;
    }

    lv_obj_t *gap = lv_obj_create(content);   /* spacer before the controls */
    lv_obj_remove_style_all(gap);
    lv_obj_set_size(gap, 1, 12);

    /* Controls: Start/Stop (name toggles), Mode hop/lock, Channel select. */
    lv_obj_t *srow = wifi_menu_row(content, "Start capture", NOCSIF_VIOLET, NULL, NULL, wifi_mon_start_cb, NULL);
    s_mon_start_lbl = lv_obj_get_child(srow, 0);   /* the name label (child 0) */
    wifi_menu_row(content, "Mode", NOCSIF_BONE, "hop", &s_mon_mode_acc, wifi_mon_mode_cb, NULL);
    wifi_menu_row(content, "Channel", NOCSIF_BONE, "auto", &s_mon_chan_acc, wifi_mon_chan_cb, NULL);

    lv_timer_t *timer = lv_timer_create(wifi_monitor_tick, 400, NULL);
    lv_obj_add_event_cb(scr, wifi_monitor_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_monitor_tick(timer);   /* seed immediately */
    return scr;
}

/* ============================ M5-P3: Live Networks (passive) ======================== *
 * The parsed view of monitor capture: a live, BSSID-keyed list of every AP in the air (incl.
 * hidden SSIDs), with channel / security / vendor / RSSI — nothing is transmitted. Enabling it
 * runs capture (which suspends any STA link).
 *
 * A FIXED pool of row widgets is created ONCE and updated in place each tick. The earlier
 * clean+recreate-on-timer version stalled the render task: LVGL's heap is only 96 KB, and
 * churning ~11 objects/row × up-to-32 rows every tick fragmented/exhausted it until one rebuild
 * took >5 s and tripped the task-WDT. Zero runtime allocation = no churn, no exhaustion. */
#define AP_ROWS 32   /* pooled rows; the content area SCROLLS, so the list is meant to be dragged
                      * through — not paged. Bumped 10 -> 32 so realistic scans show every network in
                      * one scroll (a "+N more" footer only appears past 32). Render-safe: under
                      * full_refresh only the ~7 rows actually ON SCREEN rasterize (off-screen rows are
                      * clipped), so a taller pool costs nothing per frame; rows still repaint only on a
                      * real change. The LVGL objects live in PSRAM (CONFIG_LV_USE_CUSTOM_MALLOC); only
                      * the small per-row STRUCT array is internal BSS, and 48 rows is a few KB — safe
                      * against the boot BLE-controller reservation (~98 KB contiguous free at boot). */
typedef struct {
    lv_obj_t *row;
    lv_obj_t *bar[4];
    lv_obj_t *name;
    lv_obj_t *meta;
    lv_obj_t *bssid;
    lv_obj_t *lock;
    int8_t    bars;      /* cached active-bar count (-1 = force the first paint) */
    /* Identity of the AP currently shown in this pooled row, captured on each fill so a tap can hand
     * it to Signal Hunt / Handshake capture without re-deriving it from the (paged) table. */
    uint8_t   ap_bssid[6];
    char      ap_ssid[33];
    uint8_t   ap_channel;
    uint8_t   ap_security;
    bool      ap_shown;  /* this row currently displays an AP (vs hidden/empty) */
} ap_row_t;
static ap_row_t  s_apr[AP_ROWS];
static lv_obj_t *s_ap_list, *s_ap_status, *s_ap_start_lbl, *s_ap_more, *s_ap_more_lbl;
static int       s_ap_page;   /* which page of AP_ROWS is shown (tap the footer to advance) */

/* Live-network tap → action hand-off (#3). Tapping an AP in Live Networks raises a small modal
 * offering "Signal Hunt" or "Capture Handshake", each pre-aimed at that one network. The chosen
 * target is stashed here and consumed by build_ble_hunt() / build_wifi_handshake() on entry — the
 * same pattern as the Band-Survey → Signal-Hunt LoRa hand-off. */
typedef struct { uint8_t bssid[6]; char name[33]; uint8_t channel; bool valid; } wifi_target_t;
static wifi_target_t s_hunt_wifi_pending;   /* Live Networks → Signal Hunt (WiFi AP)               */
static wifi_target_t s_hs_target;           /* Live Networks → Handshake capture (channel-locked)  */
static wifi_target_t s_apn_target;          /* the AP the open tap-modal is about                  */
static lv_obj_t     *s_apn_overlay;         /* the tap modal (lv_layer_top; closed on nav-away)    */

static void wifi_ap_popup_close(void)
{
    if (s_apn_overlay) { lv_obj_delete(s_apn_overlay); s_apn_overlay = NULL; }
}
static void wifi_ap_popup_dismiss_cb(lv_event_t *e) { (void)e; wifi_ap_popup_close(); }

static void wifi_ap_hunt_cb(lv_event_t *e)
{
    (void)e;
    s_hunt_wifi_pending = s_apn_target;          /* copy the pinned AP → Signal Hunt */
    s_hunt_wifi_pending.valid = true;
    wifi_ap_popup_close();
    nocsif_nav_push(build_ble_hunt());           /* enters straight onto the WiFi hunt meter */
}
static void wifi_ap_hs_cb(lv_event_t *e)
{
    (void)e;
    s_hs_target = s_apn_target;                  /* copy the pinned AP → Handshake capture */
    s_hs_target.valid = true;
    wifi_ap_popup_close();
    nocsif_nav_push(build_wifi_handshake());      /* channel-locked to this AP */
}

/* Raise the tap-modal for one AP (title = SSID, two action buttons). Mirrors phone_popup(). */
static void wifi_ap_popup(const nocsif_wifi_mon_ap_t *ap)
{
    if (!ap || s_apn_overlay) {
        return;
    }
    memcpy(s_apn_target.bssid, ap->bssid, 6);
    snprintf(s_apn_target.name, sizeof s_apn_target.name, "%s", ap->ssid[0] ? ap->ssid : "(hidden)");
    s_apn_target.channel = ap->channel;
    s_apn_target.valid   = false;

    lv_obj_t *ov = lv_obj_create(lv_layer_top());
    lv_obj_remove_style_all(ov);
    lv_obj_set_size(ov, lv_pct(100), lv_pct(100));
    lv_obj_set_style_bg_color(ov, NOCSIF_VOID, 0);
    lv_obj_set_style_bg_opa(ov, LV_OPA_70, 0);
    lv_obj_set_flex_flow(ov, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(ov, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_add_flag(ov, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(ov, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(ov, wifi_ap_popup_dismiss_cb, LV_EVENT_CLICKED, NULL);   /* tap scrim = dismiss */
    s_apn_overlay = ov;

    lv_obj_t *card = lv_obj_create(ov);
    lv_obj_remove_style_all(card);
    lv_obj_set_width(card, 250);
    lv_obj_set_height(card, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(card, lv_color_hex(0x161619), 0);
    lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(card, 14, 0);
    lv_obj_set_style_border_width(card, 1, 0);
    lv_obj_set_style_border_color(card, NOCSIF_EDGE2, 0);
    lv_obj_set_style_pad_all(card, 18, 0);
    lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(card, 10, 0);
    lv_obj_add_flag(card, LV_OBJ_FLAG_CLICKABLE);        /* swallow taps so they don't dismiss */
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *title = lv_label_create(card);
    lv_label_set_long_mode(title, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(title, lv_pct(100));
    lv_label_set_text(title, s_apn_target.name);
    lv_obj_set_style_text_font(title, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(title, NOCSIF_BONE, 0);
    lv_obj_set_style_text_align(title, LV_TEXT_ALIGN_CENTER, 0);

    char sub[48];
    snprintf(sub, sizeof sub, "ch %d " NOCSIF_DOT " %s", ap->channel, nocsif_wifi_sec_str(ap->security));
    lv_obj_t *sl = lv_label_create(card);
    lv_label_set_text(sl, sub);
    lv_obj_add_style(sl, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(sl, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_bottom(sl, 4, 0);

    (void) tools_btn(card, "Signal Hunt",       NOCSIF_VIOLET, wifi_ap_hunt_cb);
    (void) tools_btn(card, "Capture Handshake", NOCSIF_STEEL,  wifi_ap_hs_cb);
}

/* Tap a Live-Networks row → open the action modal for whatever AP that pooled row shows. */
static void wifi_aplist_row_cb(lv_event_t *e)
{
    int i = (int)(intptr_t)lv_event_get_user_data(e);
    if (i < 0 || i >= AP_ROWS || !s_apr[i].ap_shown) {
        return;
    }
    nocsif_wifi_mon_ap_t ap;
    memset(&ap, 0, sizeof ap);
    memcpy(ap.bssid, s_apr[i].ap_bssid, 6);
    snprintf(ap.ssid, sizeof ap.ssid, "%s", s_apr[i].ap_ssid);
    ap.channel  = s_apr[i].ap_channel;
    ap.security = s_apr[i].ap_security;
    wifi_ap_popup(&ap);
}

/* Build one reusable pooled row (created hidden; the tick fills it). Keeps handles to every
 * mutable widget so nothing is ever re-created at runtime. */
static void wifi_ap_pool_row(lv_obj_t *parent, ap_row_t *r)
{
    static const int barh[4] = { 5, 8, 11, 14 };
    r->row = lv_obj_create(parent);
    lv_obj_remove_style_all(r->row);
    lv_obj_set_width(r->row, lv_pct(100));
    lv_obj_set_height(r->row, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(r->row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(r->row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(r->row, 14, 0);
    lv_obj_set_style_pad_ver(r->row, 12, 0);
    lv_obj_set_style_min_height(r->row, 54, 0);
    lv_obj_set_style_border_side(r->row, LV_BORDER_SIDE_BOTTOM, 0);
    lv_obj_set_style_border_color(r->row, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_width(r->row, 1, 0);
    lv_obj_set_style_border_opa(r->row, LV_OPA_COVER, 0);
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(r->row, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_flag(r->row, LV_OBJ_FLAG_CLICKABLE);        /* tap → Signal Hunt / Handshake popup */
    lv_obj_add_style(r->row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(r->row, wifi_aplist_row_cb, LV_EVENT_CLICKED, (void *)(intptr_t)(r - s_apr));
    r->ap_shown = false;
    lv_obj_add_flag(r->row, LV_OBJ_FLAG_HIDDEN);           /* shown once an AP fills it */

    lv_obj_t *box = lv_obj_create(r->row);                 /* four rising signal bars */
    lv_obj_remove_style_all(box);
    lv_obj_set_size(box, 20, 14);
    lv_obj_set_flex_flow(box, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(box, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_column(box, 2, 0);
    lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
    for (int i = 0; i < 4; i++) {
        r->bar[i] = lv_obj_create(box);
        lv_obj_remove_style_all(r->bar[i]);
        lv_obj_set_size(r->bar[i], 3, barh[i]);
        lv_obj_set_style_radius(r->bar[i], 1, 0);
        lv_obj_set_style_bg_opa(r->bar[i], LV_OPA_COVER, 0);
        lv_obj_set_style_bg_color(r->bar[i], NOCSIF_ASH, 0);
    }

    lv_obj_t *col = lv_obj_create(r->row);
    lv_obj_remove_style_all(col);
    lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_grow(col, 1);
    lv_obj_set_height(col, LV_SIZE_CONTENT);
    lv_obj_clear_flag(col, LV_OBJ_FLAG_SCROLLABLE);

    r->name = lv_label_create(col);
    lv_obj_add_style(r->name, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(r->name, NOCSIF_BONE, 0);
    lv_obj_set_width(r->name, lv_pct(100));
    lv_label_set_long_mode(r->name, LV_LABEL_LONG_DOT);
    lv_label_set_text(r->name, "");

    r->meta = lv_label_create(col);
    lv_obj_add_style(r->meta, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(r->meta, NOCSIF_ASH, 0);
    lv_label_set_text(r->meta, "");

    r->bssid = lv_label_create(col);
    lv_obj_add_style(r->bssid, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(r->bssid, NOCSIF_STEEL, 0);
    lv_label_set_text(r->bssid, "");

    r->lock = lv_label_create(r->row);
    lv_label_set_text(r->lock, NOCSIF_ICON_LOCK);
    lv_obj_add_style(r->lock, &nocsif_style_row_icon, 0);
    lv_obj_set_style_text_color(r->lock, NOCSIF_ASH, 0);
    lv_obj_add_flag(r->lock, LV_OBJ_FLAG_HIDDEN);

    r->bars = -1;
}

/* Update one pooled row in place from an AP snapshot (writes are update-on-change guarded). */
static void wifi_ap_row_fill(ap_row_t *r, const nocsif_wifi_mon_ap_t *ap)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);

    /* Remember what this pooled row is showing, so a tap can target it (#3). Cheap, done every fill. */
    memcpy(r->ap_bssid, ap->bssid, 6);
    snprintf(r->ap_ssid, sizeof r->ap_ssid, "%s", ap->ssid);
    r->ap_channel  = ap->channel;
    r->ap_security = ap->security;
    r->ap_shown    = true;

    wifi_set_label(r->name, ap->ssid[0] ? ap->ssid : "(hidden)");
    lv_obj_set_style_text_color(r->name, ap->ssid[0] ? NOCSIF_BONE : NOCSIF_ASH, 0);

    char buf[64];
    if (ap->vendor[0]) {
        snprintf(buf, sizeof buf, "ch %d " NOCSIF_DOT " %s " NOCSIF_DOT " %s",
                 ap->channel, nocsif_wifi_sec_str(ap->security), ap->vendor);
    } else {
        snprintf(buf, sizeof buf, "ch %d " NOCSIF_DOT " %s",
                 ap->channel, nocsif_wifi_sec_str(ap->security));
    }
    wifi_set_label(r->meta, buf);

    /* BSSID only — NO live dBm. dBm jitters every frame, and under full_refresh that churned a
     * whole-frame repaint every tick (the render-WDT wedge). Signal is shown by the bucketed bars
     * below (cached, repaint only on a level change); this text changes only on slot eviction. */
    snprintf(buf, sizeof buf, "%02x:%02x:%02x:%02x:%02x:%02x",
             ap->bssid[0], ap->bssid[1], ap->bssid[2],
             ap->bssid[3], ap->bssid[4], ap->bssid[5]);
    wifi_set_label(r->bssid, buf);

    int active = wifi_bars(ap->rssi);
    if ((int8_t)active != r->bars) {
        r->bars = (int8_t)active;
        for (int i = 0; i < 4; i++) {
            lv_obj_set_style_bg_color(r->bar[i], i < active ? NOCSIF_STEEL : NOCSIF_ASH, 0);
        }
    }

    if (ap->security != NOCSIF_WIFI_SEC_OPEN) lv_obj_clear_flag(r->lock, LV_OBJ_FLAG_HIDDEN);
    else                                      lv_obj_add_flag(r->lock, LV_OBJ_FLAG_HIDDEN);
}

static void wifi_aplist_start_cb(lv_event_t *e)
{
    (void)e;
    if (nocsif_wifi_parse_active()) {
        nocsif_wifi_request_monitor(false);   /* full stop: parse + capture off, STA link restored */
    } else {
        nocsif_wifi_request_parse(true);      /* start capture + parse (suspends any STA link) */
    }
}

static void wifi_aplist_tick(lv_timer_t *t)
{
    (void)t;
    if (s_ap_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_parse_active();
    int  n      = nocsif_wifi_mon_ap_count();

    char buf[72];
    const char *msg;
    if (!active) {
        msg = "stopped " NOCSIF_DOT " tap Start (suspends the WiFi link)";
    } else if (n <= 0) {
        snprintf(buf, sizeof buf, "listening " NOCSIF_DOT " %s " NOCSIF_DOT " no APs yet",
                 nocsif_wifi_monitor_hopping() ? "hopping 1-13" : "locked");
        msg = buf;
    } else {
        snprintf(buf, sizeof buf, "%d network%s " NOCSIF_DOT " passive " NOCSIF_DOT " %s",
                 n, n == 1 ? "" : "s", nocsif_wifi_monitor_hopping() ? "hop" : "lock");
        msg = buf;
    }
    wifi_set_label(s_ap_status, msg);
    lv_obj_set_style_text_color(s_ap_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    /* Fill the fixed pool in place from the current page — no allocation, so no LVGL-heap churn /
     * render stall. Paging (tap the footer) reuses the same rows to reach APs beyond AP_ROWS. */
    int pages = (n + AP_ROWS - 1) / AP_ROWS;
    if (pages < 1)          pages = 1;
    if (s_ap_page >= pages) s_ap_page = 0;      /* clamp when the set shrank */
    int base = s_ap_page * AP_ROWS;

    for (int i = 0; i < AP_ROWS; i++) {
        nocsif_wifi_mon_ap_t ap;
        int idx = base + i;
        if (idx < n && nocsif_wifi_mon_ap_get(idx, &ap)) {
            wifi_ap_row_fill(&s_apr[i], &ap);
        } else if (s_apr[i].row) {
            lv_obj_add_flag(s_apr[i].row, LV_OBJ_FLAG_HIDDEN);
            s_apr[i].bars = -1;
            s_apr[i].ap_shown = false;
        }
    }

    if (s_ap_more && s_ap_more_lbl) {
        if (n > AP_ROWS) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_ap_page + 1, pages, AP_ROWS);
            wifi_set_label(s_ap_more_lbl, buf);
            lv_obj_clear_flag(s_ap_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_ap_more, LV_OBJ_FLAG_HIDDEN);
        }
    }

    if (s_ap_start_lbl) {
        wifi_set_label(s_ap_start_lbl, active ? "Stop" : "Start passive discovery");
    }
}

/* Tap the footer to advance to the next page of AP_ROWS (wraps). Refills immediately so the tap
 * feels instant rather than waiting for the ~1 s poll. */
static void wifi_aplist_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_wifi_mon_ap_count();
    int pages = (n + AP_ROWS - 1) / AP_ROWS;
    if (pages < 1) pages = 1;
    s_ap_page = (s_ap_page + 1) % pages;
    wifi_aplist_tick(NULL);
}

static void wifi_aplist_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    wifi_ap_popup_close();   /* never leave the tap modal on lv_layer_top after nav-away */
    /* Capture keeps running in the background (like Monitor) — only nulling the screen widgets. */
    s_ap_list = s_ap_status = s_ap_start_lbl = s_ap_more = s_ap_more_lbl = NULL;
    for (int i = 0; i < AP_ROWS; i++) {
        s_apr[i].row = s_apr[i].name = s_apr[i].meta = s_apr[i].bssid = s_apr[i].lock = NULL;
        s_apr[i].ap_shown = false;
    }
}

static lv_obj_t *build_wifi_aplist(void)
{
    nocsif_wifi_init();   /* ensure the worker exists (idempotent; no-op in safe mode) */
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Live Networks", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_ap_status = lv_label_create(content);
    lv_label_set_long_mode(s_ap_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_ap_status, lv_pct(100));
    lv_obj_add_style(s_ap_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_ap_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_ap_status, "passive discovery");
    lv_obj_set_style_pad_bottom(s_ap_status, 8, 0);

    lv_obj_t *srow = wifi_menu_row(content, "Start passive discovery", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_aplist_start_cb, NULL);
    s_ap_start_lbl = lv_obj_get_child(srow, 0);   /* the name label (child 0) */

    s_ap_list = lv_obj_create(content);
    lv_obj_remove_style_all(s_ap_list);
    lv_obj_set_width(s_ap_list, lv_pct(100));
    lv_obj_set_height(s_ap_list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_ap_list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(s_ap_list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(s_ap_list, 6, 0);

    for (int i = 0; i < AP_ROWS; i++) {           /* pool created ONCE — reused, never re-created */
        wifi_ap_pool_row(s_ap_list, &s_apr[i]);
    }

    /* Tappable page footer — a CONTAINER with SCROLLABLE cleared, exactly like wifi_menu_row / the
     * scan rescan-header. A bare clickable LABEL keeps the base object's default SCROLLABLE flag, so
     * its own scroll-gesture arbitration ate the first tap (the two-tap bug from the scan list).
     * The CHILD label is CENTERED so the full-width line's ends stay out of the bottom rounded
     * corners ([[rounded-corner-safe-zone]]); the bottom-middle is a straight, safe edge. */
    s_ap_page = 0;
    s_ap_more = lv_obj_create(content);
    lv_obj_remove_style_all(s_ap_more);
    lv_obj_set_width(s_ap_more, lv_pct(100));
    lv_obj_set_height(s_ap_more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(s_ap_more, 12, 0);   /* generous tap target */
    lv_obj_clear_flag(s_ap_more, LV_OBJ_FLAG_SCROLLABLE);          /* <- the fix: first-tap select */
    lv_obj_add_flag(s_ap_more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_ap_more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_ap_more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_ap_more, wifi_aplist_page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(s_ap_more, LV_OBJ_FLAG_HIDDEN);

    s_ap_more_lbl = lv_label_create(s_ap_more);
    lv_obj_add_style(s_ap_more_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_ap_more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(s_ap_more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(s_ap_more_lbl, LV_TEXT_ALIGN_CENTER, 0);   /* ends clear of corners */
    lv_label_set_text(s_ap_more_lbl, "");

    /* Coming from Monitor (capture already up)? Enable the parser at once so the list populates
     * without a tap. From cold, do NOT auto-start — Start is explicit (it suspends the link). */
    if (nocsif_wifi_monitor_active() && !nocsif_wifi_parse_active()) {
        nocsif_wifi_request_parse(true);
    }

    lv_timer_t *timer = lv_timer_create(wifi_aplist_tick, 1000, NULL);   /* gentle: rows are static */
    lv_obj_add_event_cb(scr, wifi_aplist_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_aplist_tick(timer);   /* seed immediately */
    return scr;
}

/* ---- shared live-list row (Stations + Probe Requests, M5-P3·2) --------------------- *
 * The SAME crash lessons as Live Networks apply: a pool of rows created once and updated in place
 * (never clean+recreate on a timer → LVGL-heap churn → render-WDT), and STATIC rows (no per-frame
 * text churn under full_refresh while the equal-priority WiFi worker runs). Both screens reuse this
 * two-line-plus-bars row shell; only the fill logic differs.
 * Pool size bumped 10 -> 32 so these lists SCROLL through every hit in one drag instead of paging;
 * see the AP_ROWS note above for why a taller scrollable pool stays render- and RAM-safe. Shared by
 * Stations, Probe Requests, Handshake, BLE Scan, GATT Explore, Nearby Trackers and the mgmt-frame
 * target picker. */
#define LIVE_ROWS 32
typedef struct {
    lv_obj_t *row;
    lv_obj_t *bar[4];
    lv_obj_t *name;   /* hero line (mono 16) */
    lv_obj_t *meta;   /* detail line (mono 12) */
    int8_t    bars;   /* cached active-bar count (-1 = force the first paint) */
} live_row_t;

/* Build one reusable pooled row shell (created hidden; a tick fills it). */
static void wifi_live_pool_row(lv_obj_t *parent, live_row_t *r)
{
    static const int barh[4] = { 5, 8, 11, 14 };
    r->row = lv_obj_create(parent);
    lv_obj_remove_style_all(r->row);
    lv_obj_set_width(r->row, lv_pct(100));
    lv_obj_set_height(r->row, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(r->row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(r->row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(r->row, 14, 0);
    lv_obj_set_style_pad_ver(r->row, 12, 0);
    lv_obj_set_style_min_height(r->row, 54, 0);
    lv_obj_set_style_border_side(r->row, LV_BORDER_SIDE_BOTTOM, 0);
    lv_obj_set_style_border_color(r->row, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_width(r->row, 1, 0);
    lv_obj_set_style_border_opa(r->row, LV_OPA_COVER, 0);
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(r->row, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_flag(r->row, LV_OBJ_FLAG_HIDDEN);

    lv_obj_t *box = lv_obj_create(r->row);                 /* four rising signal bars */
    lv_obj_remove_style_all(box);
    lv_obj_set_size(box, 20, 14);
    lv_obj_set_flex_flow(box, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(box, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_column(box, 2, 0);
    lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
    for (int i = 0; i < 4; i++) {
        r->bar[i] = lv_obj_create(box);
        lv_obj_remove_style_all(r->bar[i]);
        lv_obj_set_size(r->bar[i], 3, barh[i]);
        lv_obj_set_style_radius(r->bar[i], 1, 0);
        lv_obj_set_style_bg_opa(r->bar[i], LV_OPA_COVER, 0);
        lv_obj_set_style_bg_color(r->bar[i], NOCSIF_ASH, 0);
    }

    lv_obj_t *col = lv_obj_create(r->row);
    lv_obj_remove_style_all(col);
    lv_obj_set_flex_flow(col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_grow(col, 1);
    lv_obj_set_height(col, LV_SIZE_CONTENT);
    lv_obj_clear_flag(col, LV_OBJ_FLAG_SCROLLABLE);

    r->name = lv_label_create(col);
    lv_obj_add_style(r->name, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(r->name, NOCSIF_BONE, 0);
    lv_obj_set_width(r->name, lv_pct(100));
    lv_label_set_long_mode(r->name, LV_LABEL_LONG_DOT);
    lv_label_set_text(r->name, "");

    r->meta = lv_label_create(col);
    lv_obj_add_style(r->meta, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(r->meta, NOCSIF_ASH, 0);
    lv_obj_set_width(r->meta, lv_pct(100));
    lv_label_set_long_mode(r->meta, LV_LABEL_LONG_DOT);
    lv_label_set_text(r->meta, "");

    /* Children default to CLICKABLE (LVGL base flag) and cover the row surface, so a tap on the text/bars
     * gets swallowed instead of reaching the row's own click handler — the "hard to tap" pooled row. Clear
     * it on every descendant so taps fall through to the clickable row. (No pooled-row child ever carries
     * its own handler — the callback is always on r->row — so this is safe for all live-list screens.) */
    lv_obj_clear_flag(box, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(col, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(r->name, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(r->meta, LV_OBJ_FLAG_CLICKABLE);
    for (int i = 0; i < 4; i++) lv_obj_clear_flag(r->bar[i], LV_OBJ_FLAG_CLICKABLE);

    r->bars = -1;
}

/* Cached signal-bar update (repaint only on a level change — the render-WDT lesson). */
static void wifi_live_set_bars(live_row_t *r, int8_t rssi)
{
    int active = wifi_bars(rssi);
    if ((int8_t)active != r->bars) {
        r->bars = (int8_t)active;
        for (int i = 0; i < 4; i++) {
            lv_obj_set_style_bg_color(r->bar[i], i < active ? NOCSIF_STEEL : NOCSIF_ASH, 0);
        }
    }
}

/* Build the common scaffold for a live list: status label, Start/Stop row, the fixed row pool,
 * and a tappable page footer (container with SCROLLABLE cleared — first-tap select). The caller
 * passes the built pool array + receives the shared widget handles by pointer. */
static lv_obj_t *wifi_livelist_scaffold(const char *title, live_row_t *pool,
                                        lv_event_cb_t start_cb, lv_event_cb_t page_cb,
                                        lv_obj_t **out_status, lv_obj_t **out_start_lbl,
                                        lv_obj_t **out_more, lv_obj_t **out_more_lbl,
                                        lv_obj_t **out_content)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold(title, NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *status = lv_label_create(content);
    lv_label_set_long_mode(status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(status, lv_pct(100));
    lv_obj_add_style(status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(status, NOCSIF_STEEL, 0);
    lv_label_set_text(status, "passive discovery");
    lv_obj_set_style_pad_bottom(status, 8, 0);

    lv_obj_t *srow = wifi_menu_row(content, "Start passive discovery", NOCSIF_VIOLET,
                                   NULL, NULL, start_cb, NULL);
    lv_obj_t *start_lbl = lv_obj_get_child(srow, 0);

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);

    for (int i = 0; i < LIVE_ROWS; i++) {     /* pool created ONCE — reused, never re-created */
        wifi_live_pool_row(list, &pool[i]);
    }

    lv_obj_t *more = lv_obj_create(content);
    lv_obj_remove_style_all(more);
    lv_obj_set_width(more, lv_pct(100));
    lv_obj_set_height(more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(more, 12, 0);
    lv_obj_clear_flag(more, LV_OBJ_FLAG_SCROLLABLE);   /* first-tap select, not scroll-arbitration */
    lv_obj_add_flag(more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(more, page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(more, LV_OBJ_FLAG_HIDDEN);

    lv_obj_t *more_lbl = lv_label_create(more);
    lv_obj_add_style(more_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(more_lbl, LV_TEXT_ALIGN_CENTER, 0);   /* ends clear of corners */
    lv_label_set_text(more_lbl, "");

    *out_status = status;
    *out_start_lbl = start_lbl;
    *out_more = more;
    *out_more_lbl = more_lbl;
    if (out_content) *out_content = content;
    return scr;
}

/* The Start/Stop toggle + auto-start-when-arriving-from-Monitor are identical for every live
 * list (all three ride the one parser); shared here. */
static void wifi_livelist_toggle(void)
{
    if (nocsif_wifi_parse_active()) {
        nocsif_wifi_request_monitor(false);   /* full stop: parse + capture off, STA link restored */
    } else {
        nocsif_wifi_request_parse(true);      /* start capture + parse (suspends any STA link) */
    }
}

/* ---- Stations screen: passive client/station list (fills wifi.stations, M5-P3·2) ----- */
static live_row_t s_str[LIVE_ROWS];
static lv_obj_t  *s_st_status, *s_st_start_lbl, *s_st_more, *s_st_more_lbl;
static int        s_st_page;

static void wifi_sta_row_fill(live_row_t *r, const nocsif_wifi_mon_sta_t *st)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);

    char buf[80];
    snprintf(buf, sizeof buf, "%02x:%02x:%02x:%02x:%02x:%02x",
             st->mac[0], st->mac[1], st->mac[2], st->mac[3], st->mac[4], st->mac[5]);
    wifi_set_label(r->name, buf);

    /* the AP it is talking to: SSID if known, else its BSSID, else unknown */
    char ap[40];
    bool anyb = false;
    for (int i = 0; i < 6; i++) { if (st->bssid[i]) { anyb = true; break; } }
    if (st->ssid[0]) {
        snprintf(ap, sizeof ap, "%s", st->ssid);
    } else if (anyb) {
        snprintf(ap, sizeof ap, "%02x:%02x:%02x:%02x:%02x:%02x",
                 st->bssid[0], st->bssid[1], st->bssid[2], st->bssid[3], st->bssid[4], st->bssid[5]);
    } else {
        snprintf(ap, sizeof ap, "unknown AP");
    }
    if (st->vendor[0]) {
        snprintf(buf, sizeof buf, "%s " NOCSIF_DOT " ch %d " NOCSIF_DOT " %s", ap, st->channel, st->vendor);
    } else {
        snprintf(buf, sizeof buf, "%s " NOCSIF_DOT " ch %d", ap, st->channel);
    }
    wifi_set_label(r->meta, buf);

    wifi_live_set_bars(r, st->rssi);
}

static void wifi_stations_start_cb(lv_event_t *e) { (void)e; wifi_livelist_toggle(); }

static void wifi_stations_tick(lv_timer_t *t)
{
    (void)t;
    if (s_st_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_parse_active();
    int  n      = nocsif_wifi_mon_sta_count();

    char buf[72];
    const char *msg;
    if (!active) {
        msg = "stopped " NOCSIF_DOT " tap Start (suspends the WiFi link)";
    } else if (n <= 0) {
        snprintf(buf, sizeof buf, "listening " NOCSIF_DOT " %s " NOCSIF_DOT " no clients yet",
                 nocsif_wifi_monitor_hopping() ? "hopping 1-13" : "locked");
        msg = buf;
    } else {
        snprintf(buf, sizeof buf, "%d client%s " NOCSIF_DOT " passive " NOCSIF_DOT " %s",
                 n, n == 1 ? "" : "s", nocsif_wifi_monitor_hopping() ? "hop" : "lock");
        msg = buf;
    }
    wifi_set_label(s_st_status, msg);
    lv_obj_set_style_text_color(s_st_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1)          pages = 1;
    if (s_st_page >= pages) s_st_page = 0;
    int base = s_st_page * LIVE_ROWS;

    for (int i = 0; i < LIVE_ROWS; i++) {
        nocsif_wifi_mon_sta_t st;
        int idx = base + i;
        if (idx < n && nocsif_wifi_mon_sta_get(idx, &st)) {
            wifi_sta_row_fill(&s_str[i], &st);
        } else if (s_str[i].row) {
            lv_obj_add_flag(s_str[i].row, LV_OBJ_FLAG_HIDDEN);
            s_str[i].bars = -1;
        }
    }

    if (s_st_more && s_st_more_lbl) {
        if (n > LIVE_ROWS) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_st_page + 1, pages, LIVE_ROWS);
            wifi_set_label(s_st_more_lbl, buf);
            lv_obj_clear_flag(s_st_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_st_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (s_st_start_lbl) {
        wifi_set_label(s_st_start_lbl, active ? "Stop" : "Start passive discovery");
    }
}

static void wifi_stations_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_wifi_mon_sta_count();
    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1) pages = 1;
    s_st_page = (s_st_page + 1) % pages;
    wifi_stations_tick(NULL);
}

static void wifi_stations_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_st_status = s_st_start_lbl = s_st_more = s_st_more_lbl = NULL;
    for (int i = 0; i < LIVE_ROWS; i++) {
        s_str[i].row = s_str[i].name = s_str[i].meta = NULL;
    }
}

static lv_obj_t *build_wifi_stations(void)
{
    s_st_page = 0;
    lv_obj_t *scr = wifi_livelist_scaffold("Clients", s_str,
                                           wifi_stations_start_cb, wifi_stations_page_cb,
                                           &s_st_status, &s_st_start_lbl,
                                           &s_st_more, &s_st_more_lbl, NULL);
    if (nocsif_wifi_monitor_active() && !nocsif_wifi_parse_active()) {
        nocsif_wifi_request_parse(true);
    }
    lv_timer_t *timer = lv_timer_create(wifi_stations_tick, 1000, NULL);
    lv_obj_add_event_cb(scr, wifi_stations_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_stations_tick(timer);
    return scr;
}

/* ---- Probe Requests screen: SSID harvest (fills wifi.probes, M5-P3·2) --------------- */
static live_row_t s_pbr[LIVE_ROWS];
