    lv_obj_add_style(s_pcap_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_pcap_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_pcap_status, "records every frame to SD (.pcap)");
