/* ============================ M5-P5·4: Captive Portal (active) ========================= *
 * A captive-portal presentation on the open software AP: a UDP:53 DNS redirector + an HTTP landing
 * page (from /sd, else built-in), with a live client-interaction log. Start brings the AP up if it is
 * not already. The interaction rows are plain text lines updated in place (fixed label POOL / static
 * rows — the same render-WDT discipline as the other live lists). Authorized testing only. */
#define PT_ROWS 8   /* pooled interaction-log rows (newest first) */
static lv_obj_t *s_pt_status, *s_pt_start_lbl, *s_pt_info, *s_pt_page_acc, *s_pt_rows[PT_ROWS];

static lv_obj_t *build_wifi_portal_pick(void);   /* landing-page chooser (/sd/nocsif/wifi/portals) */

static void wifi_portal_start_cb(lv_event_t *e) { (void)e; nocsif_wifi_request_portal(!nocsif_wifi_portal_active()); }
static void wifi_portal_pick_cb(lv_event_t *e)  { (void)e; lv_obj_t *r = build_wifi_portal_pick(); if (r) nocsif_nav_push(r); }

static void wifi_portal_tick(lv_timer_t *t)
{
    (void)t;
    if (s_pt_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_portal_active();
    unsigned hits = (unsigned)nocsif_wifi_portal_hits();

    char buf[96];
    if (active) {
        const char *src = nocsif_wifi_portal_page_src();
        snprintf(buf, sizeof buf, "portal up " NOCSIF_DOT " %u hit%s " NOCSIF_DOT " page: %s",
                 hits, hits == 1 ? "" : "s", src[0] ? src : "loading");
    } else {
        snprintf(buf, sizeof buf, "stopped " NOCSIF_DOT " tap Start (brings up the AP)");
    }
    wifi_set_label(s_pt_status, buf);
    lv_obj_set_style_text_color(s_pt_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);
    wifi_set_label(s_pt_start_lbl, active ? "Stop" : "Start");
    if (s_pt_page_acc) {
        const char *sel = nocsif_wifi_portal_selected_page();
        wifi_set_label(s_pt_page_acc, sel[0] ? sel : "built-in");
    }

    if (active) {
        snprintf(buf, sizeof buf, "http://%s " NOCSIF_DOT " DNS " NOCSIF_DOT " log \xE2\x86\x92 /sd/nocsif/wifi/portal-NNN.log",
                 nocsif_wifi_ap_ip_str()[0] ? nocsif_wifi_ap_ip_str() : "192.168.4.1");
    } else {
        snprintf(buf, sizeof buf, "serves /sd/nocsif/wifi/portal.html \xC2\xB7 fallback built-in notice");
    }
    wifi_set_label(s_pt_info, buf);

    int n = nocsif_wifi_portal_log_count();
    for (int i = 0; i < PT_ROWS; i++) {
        char line[96];
        if (i < n && nocsif_wifi_portal_log_get(i, line, sizeof line)) {
            wifi_set_label(s_pt_rows[i], line);
            lv_obj_clear_flag(s_pt_rows[i], LV_OBJ_FLAG_HIDDEN);
        } else if (s_pt_rows[i]) {
            lv_obj_add_flag(s_pt_rows[i], LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void wifi_portal_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_pt_status = s_pt_start_lbl = s_pt_info = s_pt_page_acc = NULL;
    for (int i = 0; i < PT_ROWS; i++) {
        s_pt_rows[i] = NULL;
    }
}

static lv_obj_t *build_wifi_portal(void)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Captive Portal", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_label_set_text(note, "active \xC2\xB7 captive portal on the software AP \xC2\xB7 authorized testing only");
    lv_obj_set_style_pad_bottom(note, 6, 0);

    s_pt_status = lv_label_create(content);
    lv_label_set_long_mode(s_pt_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_pt_status, lv_pct(100));
    lv_obj_add_style(s_pt_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_pt_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_pt_status, "stopped");
    lv_obj_set_style_pad_bottom(s_pt_status, 8, 0);

    lv_obj_t *xrow = wifi_menu_row(content, "Start", NOCSIF_VIOLET, NULL, NULL, wifi_portal_start_cb, NULL);
    s_pt_start_lbl = lv_obj_get_child(xrow, 0);

    wifi_menu_row(content, "Landing page", NOCSIF_BONE, "built-in", &s_pt_page_acc, wifi_portal_pick_cb, NULL);

    s_pt_info = lv_label_create(content);
    lv_label_set_long_mode(s_pt_info, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_pt_info, lv_pct(100));
    lv_obj_add_style(s_pt_info, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_pt_info, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(s_pt_info, 6, 0);
    lv_label_set_text(s_pt_info, "serves /sd/nocsif/wifi/portal.html \xC2\xB7 fallback built-in notice");

    lv_obj_t *lhdr = lv_label_create(content);
    lv_obj_add_style(lhdr, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(lhdr, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(lhdr, 14, 0);
    lv_label_set_text(lhdr, "client interactions");

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);
    lv_obj_set_style_pad_row(list, 6, 0);
    for (int i = 0; i < PT_ROWS; i++) {          /* plain-text row pool created ONCE, updated in place */
        lv_obj_t *l = lv_label_create(list);
        lv_obj_set_width(l, lv_pct(100));
        lv_label_set_long_mode(l, LV_LABEL_LONG_DOT);
        lv_obj_add_style(l, &nocsif_style_font_caption, 0);
        lv_obj_set_style_text_color(l, NOCSIF_BONE, 0);
        lv_label_set_text(l, "");
        lv_obj_add_flag(l, LV_OBJ_FLAG_HIDDEN);
        s_pt_rows[i] = l;
    }

    lv_timer_t *timer = lv_timer_create(wifi_portal_tick, 500, NULL);
    lv_obj_add_event_cb(scr, wifi_portal_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_portal_tick(timer);   /* seed immediately */
    return scr;
}

/* Landing-page chooser: the .html files under /sd/nocsif/wifi/portals plus a built-in option. Tapping
 * one selects it (persisted; a running portal re-serves at once). Enumerated on the LVGL task under the
 * SD lock (mirrors the /sd/ducky macro picker); /sd is app-mounted at boot, so it works offline. */
#define UI_PORTAL_DIR   "/sd/nocsif/wifi/portals"
#define PT_PICK_MAX     24
#define PT_PICK_NAMEL   64

static void wifi_portal_pick_row_cb(lv_event_t *e)
{
    const char *name = (const char *)lv_event_get_user_data(e);   /* "" = built-in */
    nocsif_wifi_portal_set_page(name ? name : "");
    nocsif_nav_back();
}
static void wifi_portal_pick_row_del_cb(lv_event_t *e) { free(lv_event_get_user_data(e)); }

static void wifi_portal_pick_add_row(lv_obj_t *parent, const char *name, const char *label, bool current)
{
    char *ud = (char *)malloc(strlen(name) + 1);
    if (ud == NULL) {
        return;
    }
    strcpy(ud, name);
    lv_obj_t *row = wifi_menu_row(parent, label, current ? NOCSIF_VIOLET : NOCSIF_BONE,
                                  current ? "current" : NULL, NULL, wifi_portal_pick_row_cb, ud);
    lv_obj_add_event_cb(row, wifi_portal_pick_row_del_cb, LV_EVENT_DELETE, ud);
}

/* True if `name` ends in .html / .htm (case-insensitive). */
static bool ui_name_is_html(const char *name)
{
    size_t n = strlen(name);
    if (n >= 5 && strcasecmp(name + n - 5, ".html") == 0) return true;
    if (n >= 4 && strcasecmp(name + n - 4, ".htm")  == 0) return true;
    return false;
}

static lv_obj_t *build_wifi_portal_pick(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Landing Page", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_label_set_text(hint, "drop .html files in " UI_PORTAL_DIR " " NOCSIF_DOT " tap to select");
    lv_obj_set_style_pad_bottom(hint, 8, 0);

    const char *cur = nocsif_wifi_portal_selected_page();
    wifi_portal_pick_add_row(content, "", "Built-in notice", cur[0] == '\0');

    /* Snapshot names under the SD lock, then release before building rows (d_name is only valid until
     * the next readdir/closedir — copy it). */
    static char names[PT_PICK_MAX][PT_PICK_NAMEL];
    int  n = 0;
    bool truncated = false;
    if (nocsif_sdcard_lock(1000)) {
        DIR *d = opendir(UI_PORTAL_DIR);
        if (d != NULL) {
            struct dirent *ent;
            while ((ent = readdir(d)) != NULL) {
                if (ent->d_type == DT_DIR)   continue;
                if (ent->d_name[0] == '.')   continue;
                if (!ui_name_is_html(ent->d_name)) continue;
                if (n >= PT_PICK_MAX) { truncated = true; break; }
                strncpy(names[n], ent->d_name, PT_PICK_NAMEL - 1);
                names[n][PT_PICK_NAMEL - 1] = '\0';
                n++;
            }
            closedir(d);
        }
        nocsif_sdcard_unlock();
    }

    for (int i = 0; i < n; i++) {
        wifi_portal_pick_add_row(content, names[i], names[i], strcmp(names[i], cur) == 0);
    }
    if (n == 0) {
        lv_obj_t *note = lv_label_create(content);
        lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
        lv_obj_set_width(note, lv_pct(100));
        lv_obj_add_style(note, &nocsif_style_font_caption, 0);
        lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
        lv_obj_set_style_pad_top(note, 10, 0);
        lv_label_set_text(note, "no .html files found\nadd them via USB File Share, then reopen");
    }
    if (truncated) {
        ESP_LOGW(TAG, "portal picker: %s holds more than %d pages; showing first %d",
                 UI_PORTAL_DIR, PT_PICK_MAX, PT_PICK_MAX);
    }
    return scr;
}

