/* ==== M8-P1 Live Fix (gnss.fix) ==================================================== *
 * The GNSS worker streams + parses NMEA (GGA/RMC/GSA/GSV/TXT) into a spinlock-guarded snapshot;
 * this screen reads it on a 500 ms tick and paints fix state / sats / position / detail. No UART
 * I/O on the LVGL task — the getter is a pure struct copy. Auto-starts live on enter (powers BLDO1),
 * stops it on exit (drops the rail). Position stays "—" until the receiver solves a fix (needs sky
 * view); the sentence counter + antenna status prove the module is live indoors with no fix. */
static lv_obj_t *s_gf_status, *s_gf_sats, *s_gf_lat, *s_gf_lon, *s_gf_det, *s_gf_utc, *s_gf_live;

static void gf_set(lv_obj_t *l, const char *txt)
{
    if (l && strcmp(lv_label_get_text(l), txt) != 0) lv_label_set_text(l, txt);
}

static void gnss_fix_tick(lv_timer_t *t)
{
    (void)t;
    if (s_gf_status == NULL) return;

    nocsif_gnss_fix_t f;
    bool have = nocsif_gnss_fix_snapshot(&f);
    bool live = nocsif_gnss_live();
    bool fresh = have && f.stream_age_ms < 5000;
    bool fixed = have && (f.quality > 0 || f.valid);
    char buf[96];

    /* Hero: fix quality with the monochrome accent scale (violet = locked/3D, bone = 2D). */
    const char *hero; lv_color_t hc;
    if (fixed && f.fix_type >= 3)      { hero = "3D FIX";     hc = NOCSIF_VIOLET; }
    else if (fixed && f.fix_type == 2) { hero = "2D FIX";     hc = NOCSIF_BONE;   }
    else if (fixed)                    { hero = "FIX";        hc = NOCSIF_BONE;   }
    else if (fresh)                    { hero = "ACQUIRING";  hc = NOCSIF_STEEL;  }
    else if (live)                     { hero = "WARMING UP"; hc = NOCSIF_STEEL;  }
    else                               { hero = "NO SIGNAL";  hc = NOCSIF_ASH;    }
    gf_set(s_gf_status, hero);
    lv_obj_set_style_text_color(s_gf_status, hc, 0);

    if (have) snprintf(buf, sizeof buf, "%u used " NOCSIF_DOT " %u in view", f.sats_used, f.sats_in_view);
    else      snprintf(buf, sizeof buf, NOCSIF_NDASH " sats");
    gf_set(s_gf_sats, buf);

    if (fixed) {
        double la = f.lat_deg, lo = f.lon_deg;
        snprintf(buf, sizeof buf, "lat  %.6f %c", la < 0 ? -la : la, la < 0 ? 'S' : 'N');
        gf_set(s_gf_lat, buf);
        snprintf(buf, sizeof buf, "lon %.6f %c", lo < 0 ? -lo : lo, lo < 0 ? 'W' : 'E');
        gf_set(s_gf_lon, buf);
        lv_obj_set_style_text_color(s_gf_lat, NOCSIF_WHITE, 0);
        lv_obj_set_style_text_color(s_gf_lon, NOCSIF_WHITE, 0);
    } else {
        gf_set(s_gf_lat, "lat  " NOCSIF_NDASH);
        gf_set(s_gf_lon, "lon  " NOCSIF_NDASH);
        lv_obj_set_style_text_color(s_gf_lat, NOCSIF_ASH, 0);
        lv_obj_set_style_text_color(s_gf_lon, NOCSIF_ASH, 0);
    }

    if (fixed) snprintf(buf, sizeof buf, "alt %.0f m " NOCSIF_DOT " HDOP %.1f " NOCSIF_DOT " %.0f km/h",
                        (double)f.alt_m, (double)f.hdop, (double)f.speed_kmh);
    else if (have && f.hdop > 0) snprintf(buf, sizeof buf, "HDOP %.1f " NOCSIF_DOT " no position yet", (double)f.hdop);
    else snprintf(buf, sizeof buf, "no position yet");
    gf_set(s_gf_det, buf);

    if (have && f.year) snprintf(buf, sizeof buf, "UTC %04u-%02u-%02u %02u:%02u:%02u",
                                 f.year, f.mon, f.day, f.hh, f.mm, f.ss);
    else if (have && (f.hh || f.mm || f.ss)) snprintf(buf, sizeof buf, "UTC %02u:%02u:%02u", f.hh, f.mm, f.ss);
    else snprintf(buf, sizeof buf, "UTC " NOCSIF_NDASH);
    gf_set(s_gf_utc, buf);

    if (fresh) {
        if (f.antenna[0]) snprintf(buf, sizeof buf, "NMEA " NOCSIF_DOT " %lu sentences " NOCSIF_DOT " ant %s",
                                   (unsigned long)f.sentences, f.antenna);
        else snprintf(buf, sizeof buf, "NMEA " NOCSIF_DOT " %lu sentences", (unsigned long)f.sentences);
        lv_obj_set_style_text_color(s_gf_live, NOCSIF_STEEL, 0);
    } else {
        snprintf(buf, sizeof buf, live ? "waiting for data\xE2\x80\xA6" : "receiver off");
        lv_obj_set_style_text_color(s_gf_live, NOCSIF_ASH, 0);
    }
    gf_set(s_gf_live, buf);
}

static void gnss_fix_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    nocsif_gnss_set_live(false);   /* stop streaming + drop the rail on exit */
    s_gf_status = s_gf_sats = s_gf_lat = s_gf_lon = s_gf_det = s_gf_utc = s_gf_live = NULL;
}

/* Small labelled readout line for the fix screen (mono, colour set by the caller/tick). */
static lv_obj_t *gf_line(lv_obj_t *parent, const lv_font_t *font, lv_color_t col, const char *seed, int pad_top)
{
    lv_obj_t *l = lv_label_create(parent);
    nocsif_label_font_scaled(l, font);                   /* §4.13: mono 11/12/13 follow the type scale */
    lv_obj_set_style_text_color(l, col, 0);
    lv_label_set_text(l, seed);
    lv_obj_set_style_pad_top(l, pad_top, 0);
    return l;
}

static lv_obj_t *build_gnss_fix(void)
{
    nocsif_gnss_init();   /* lazy: create the worker on first entry */

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Live Fix", "u-blox M10 " NOCSIF_DOT " NMEA", &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_gf_status = gf_line(content, &nocsif_mono_18, NOCSIF_STEEL, "WARMING UP", 4);
    s_gf_sats   = gf_line(content, &nocsif_mono_16, NOCSIF_BONE,  NOCSIF_NDASH " sats", 2);
    lv_obj_set_style_pad_bottom(s_gf_sats, 12, 0);
    s_gf_lat    = gf_line(content, &nocsif_mono_16, NOCSIF_ASH,   "lat  " NOCSIF_NDASH, 0);
    s_gf_lon    = gf_line(content, &nocsif_mono_16, NOCSIF_ASH,   "lon  " NOCSIF_NDASH, 2);
    s_gf_det    = gf_line(content, &nocsif_mono_12, NOCSIF_STEEL, "no position yet", 12);
    s_gf_utc    = gf_line(content, &nocsif_mono_12, NOCSIF_STEEL, "UTC " NOCSIF_NDASH, 4);
    s_gf_live   = gf_line(content, &nocsif_mono_12, NOCSIF_ASH,   "waiting for data\xE2\x80\xA6", 12);

    nocsif_gnss_set_live(true);   /* auto-start; stopped on exit */

    lv_timer_t *timer = lv_timer_create(gnss_fix_tick, 500, NULL);
    lv_obj_add_event_cb(scr, gnss_fix_deleted_cb, LV_EVENT_DELETE, timer);
    gnss_fix_tick(timer);
    return scr;
}

/* ==== M8-P2 GPX Log (gnss.gpx) ===================================================== *
 * Records the live fix to a GPX track on microSD (`nocsif_gnss_gpx_*`). The engine owns the file +
 * cadence; this screen just drives Start/Stop and reads the stats snapshot on a tick. Logging runs
 * in the ENGINE, so a track keeps recording after you leave this screen (the Location row still
 * shows nothing special — the red-dot convention is a future polish). Live streaming is turned on
 * for the screen so you see fix health before starting; leaving drops only the screen's live vote,
 * never an in-progress track. */
static lv_obj_t *s_gx_state, *s_gx_stats, *s_gx_dur, *s_gx_fix, *s_gx_path, *s_gx_btn;

/* A violet outline pill (returns the LABEL so the tick can retext Start↔Stop). */
static lv_obj_t *gnss_pill(lv_obj_t *parent, const char *text, lv_event_cb_t cb)
{
    lv_obj_t *b = lv_obj_create(parent);
    lv_obj_remove_style_all(b);
    lv_obj_set_size(b, 200, 46);
    lv_obj_set_style_radius(b, 8, 0);
    lv_obj_set_style_bg_opa(b, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(b, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_border_width(b, 1, 0);
    lv_obj_set_style_border_color(b, NOCSIF_VIOLET, 0);
    lv_obj_set_flex_flow(b, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(b, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_add_flag(b, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(b, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_style(b, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_set_style_margin_top(b, 16, 0);
    lv_obj_add_event_cb(b, cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *l = lv_label_create(b);
    lv_label_set_text(l, text);
    lv_obj_add_style(l, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(l, NOCSIF_WHITE, 0);
    return l;
}

static void gnss_gpx_toggle_cb(lv_event_t *e)
{
    (void)e;
    nocsif_gnss_gpx_set(!nocsif_gnss_gpx_logging());
}

static void gnss_gpx_tick(lv_timer_t *t)
{
    (void)t;
    if (s_gx_state == NULL) return;

    nocsif_gnss_gpx_t g;
    nocsif_gnss_gpx_snapshot(&g);
    nocsif_gnss_fix_t f;
    bool have = nocsif_gnss_fix_snapshot(&f);
    char buf[96];

    const char *hero; lv_color_t hc;
    switch (g.state) {
        case NOCSIF_GPX_REC:  hero = "RECORDING";    hc = NOCSIF_VIOLET; break;
        case NOCSIF_GPX_WAIT: hero = "WAITING FIX";  hc = NOCSIF_STEEL;  break;
        case NOCSIF_GPX_NOSD: hero = "NO SD / BUSY"; hc = NOCSIF_ASH;    break;
        case NOCSIF_GPX_ERR:  hero = "SD ERROR";     hc = NOCSIF_ASH;    break;
        default:              hero = "STOPPED";      hc = NOCSIF_ASH;    break;
    }
    gf_set(s_gx_state, hero);
    lv_obj_set_style_text_color(s_gx_state, hc, 0);

    if (g.dist_m >= 1000.0f) snprintf(buf, sizeof buf, "%lu pts " NOCSIF_DOT " %.2f km",
                                      (unsigned long)g.points, (double)(g.dist_m / 1000.0f));
    else                     snprintf(buf, sizeof buf, "%lu pts " NOCSIF_DOT " %.0f m",
                                      (unsigned long)g.points, (double)g.dist_m);
    gf_set(s_gx_stats, buf);

    uint32_t s = g.dur_s;
    snprintf(buf, sizeof buf, "%02u:%02u:%02u", (unsigned)(s / 3600), (unsigned)((s % 3600) / 60), (unsigned)(s % 60));
    gf_set(s_gx_dur, buf);

    if (have && (f.quality > 0 || f.valid))
        snprintf(buf, sizeof buf, "%s " NOCSIF_DOT " %u sats " NOCSIF_DOT " HDOP %.1f",
                 f.fix_type >= 3 ? "3D" : f.fix_type == 2 ? "2D" : "fix", f.sats_used, (double)f.hdop);
    else if (have) snprintf(buf, sizeof buf, "acquiring " NOCSIF_DOT " %u in view", f.sats_in_view);
    else           snprintf(buf, sizeof buf, "warming up\xE2\x80\xA6");
    gf_set(s_gx_fix, buf);

    if (g.path[0]) { const char *b = strrchr(g.path, '/'); gf_set(s_gx_path, b ? b + 1 : g.path); }
    else           gf_set(s_gx_path, NOCSIF_NDASH);

    gf_set(s_gx_btn, nocsif_gnss_gpx_logging() ? "Stop logging" : "Start logging");
}

static void gnss_gpx_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    /* Drop only the screen's live vote — an in-progress track keeps the receiver live via gpx_want. */
    nocsif_gnss_set_live(false);
    s_gx_state = s_gx_stats = s_gx_dur = s_gx_fix = s_gx_path = s_gx_btn = NULL;
}

static lv_obj_t *build_gnss_gpx(void)
{
    nocsif_gnss_init();

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("GPX Log", "track \xE2\x86\x92 microSD", &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_gx_state = gf_line(content, &nocsif_mono_18, NOCSIF_ASH,   "STOPPED", 4);
    s_gx_stats = gf_line(content, &nocsif_mono_16, NOCSIF_BONE,  "0 pts " NOCSIF_DOT " 0 m", 6);
    s_gx_dur   = gf_line(content, &nocsif_mono_16, NOCSIF_WHITE, "00:00:00", 2);
    s_gx_fix   = gf_line(content, &nocsif_mono_12, NOCSIF_STEEL, "warming up\xE2\x80\xA6", 10);
    s_gx_path  = gf_line(content, &nocsif_mono_12, NOCSIF_ASH,   NOCSIF_NDASH, 2);

    s_gx_btn = gnss_pill(content, "Start logging", gnss_gpx_toggle_cb);

    nocsif_gnss_set_live(true);   /* show live fix health; logging is explicit via the pill */

    lv_timer_t *timer = lv_timer_create(gnss_gpx_tick, 500, NULL);
    lv_obj_add_event_cb(scr, gnss_gpx_deleted_cb, LV_EVENT_DELETE, timer);
    gnss_gpx_tick(timer);
    return scr;
}

/* ==== M8 Wardrive (gnss.wardrive) ================================================== *
 * Geotagged WiFi survey → a WiGLE-1.4 CSV on microSD. The engine owns the session: Start forces
 * GNSS live + the passive WiFi monitor (channel-hopping) on and logs each new AP at the live fix;
 * it keeps running in the background after you leave the screen (pocket it and drive). This screen
 * just drives Start/Stop and reads the stats snapshot. Passive recon of your own airspace. */
static lv_obj_t *s_wd_hero, *s_wd_stats, *s_wd_info, *s_wd_path_lbl, *s_wd_btn;

static void gnss_wd_toggle_cb(lv_event_t *e)
{
    (void)e;
    nocsif_gnss_wardrive_set(!nocsif_gnss_wardrive_logging());
}

static void gnss_wd_tick(lv_timer_t *t)
{
    (void)t;
    if (s_wd_hero == NULL) return;

    nocsif_gnss_wardrive_t w;
    nocsif_gnss_wardrive_snapshot(&w);
    nocsif_gnss_fix_t f;
    bool have = nocsif_gnss_fix_snapshot(&f);
    char buf[96];

    const char *hero; lv_color_t hc;
    switch (w.state) {
        case NOCSIF_WD_REC:  hero = "RECORDING";    hc = NOCSIF_VIOLET; break;
        case NOCSIF_WD_WAIT: hero = "WAITING FIX";  hc = NOCSIF_STEEL;  break;
        case NOCSIF_WD_NOSD: hero = "NO SD / BUSY"; hc = NOCSIF_ASH;    break;
        case NOCSIF_WD_ERR:  hero = "SD ERROR";     hc = NOCSIF_ASH;    break;
        default:             hero = "STOPPED";      hc = NOCSIF_ASH;    break;
    }
    gf_set(s_wd_hero, hero);
    lv_obj_set_style_text_color(s_wd_hero, hc, 0);

    uint32_t s = w.dur_s;
    snprintf(buf, sizeof buf, "%lu nets " NOCSIF_DOT " %02u:%02u:%02u",
             (unsigned long)w.networks, (unsigned)(s / 3600), (unsigned)((s % 3600) / 60), (unsigned)(s % 60));
    gf_set(s_wd_stats, buf);

    if (have && (f.quality > 0 || f.valid))
        snprintf(buf, sizeof buf, "%u APs " NOCSIF_DOT " %s " NOCSIF_DOT " %u sats",
                 w.aps_visible, f.fix_type >= 3 ? "3D" : f.fix_type == 2 ? "2D" : "fix", f.sats_used);
    else
        snprintf(buf, sizeof buf, "%u APs visible " NOCSIF_DOT " no fix", w.aps_visible);
    gf_set(s_wd_info, buf);

    if (w.path[0]) { const char *b = strrchr(w.path, '/'); gf_set(s_wd_path_lbl, b ? b + 1 : w.path); }
    else           gf_set(s_wd_path_lbl, NOCSIF_NDASH);

    gf_set(s_wd_btn, nocsif_gnss_wardrive_logging() ? "Stop wardrive" : "Start wardrive");
}

static void gnss_wd_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    /* Drop only the screen's live vote — a running wardrive keeps GNSS + WiFi up via the engine. */
    nocsif_gnss_set_live(false);
    s_wd_hero = s_wd_stats = s_wd_info = s_wd_path_lbl = s_wd_btn = NULL;
}

static lv_obj_t *build_gnss_wardrive(void)
{
    nocsif_gnss_init();

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Wardrive", "WiFi + GPS \xE2\x86\x92 WiGLE", &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_wd_hero     = gf_line(content, &nocsif_mono_18, NOCSIF_ASH,   "STOPPED", 4);
    s_wd_stats    = gf_line(content, &nocsif_mono_16, NOCSIF_BONE,  "0 nets " NOCSIF_DOT " 00:00:00", 6);
    s_wd_info     = gf_line(content, &nocsif_mono_12, NOCSIF_STEEL, "0 APs visible", 2);
    s_wd_path_lbl = gf_line(content, &nocsif_mono_12, NOCSIF_ASH,   NOCSIF_NDASH, 12);

    s_wd_btn = gnss_pill(content, "Start wardrive", gnss_wd_toggle_cb);

    nocsif_gnss_set_live(true);   /* show fix health; the WiFi monitor starts with logging */

    lv_timer_t *timer = lv_timer_create(gnss_wd_tick, 500, NULL);
    lv_obj_add_event_cb(scr, gnss_wd_deleted_cb, LV_EVENT_DELETE, timer);
    gnss_wd_tick(timer);
    return scr;
}

