/* Live date/time readout at the top of the Time screen (P4.2). A large mono clock over a
 * date caption, both seeded from the RTC's cached strings and registered so the one header
 * tick keeps them current (update-on-change). Freed with the screen on nav-back — the live
 * labels auto-unregister on delete, so nothing dangles. */
static void build_time_readout(lv_obj_t *content)
{
    lv_obj_t *box = lv_obj_create(content);
    lv_obj_remove_style_all(box);
    lv_obj_set_width(box, NOCSIF_DISP_W);
    lv_obj_set_height(box, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(box, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_left(box, UI_LIST_INSET, 0);
    lv_obj_set_style_pad_top(box, 6, 0);
    lv_obj_set_style_pad_bottom(box, 14, 0);
    lv_obj_set_style_pad_row(box, 2, 0);
    lv_obj_remove_flag(box, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(box, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *clk = lv_label_create(box);
    lv_label_set_text(clk, nocsif_rtc_clock_str());
    lv_obj_set_style_text_font(clk, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(clk, NOCSIF_BONE, 0);
    nocsif_nav_register_live_label(clk, nocsif_rtc_clock_str);

    lv_obj_t *date = lv_label_create(box);
    lv_label_set_text(date, nocsif_rtc_date_str());
    lv_obj_add_style(date, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(date, NOCSIF_STEEL, 0);
    nocsif_nav_register_live_label(date, nocsif_rtc_date_str);
}

static const rowspec_t k_timers_rows[] = {
        { "timers.alarms",    "Alarms",      NOCSIF_ICON_BELL,  NULL,    NOCSIF_TAG_NONE },
        { "timers.timer",     "Timer",       NOCSIF_ICON_CLOCK, NULL,    NOCSIF_TAG_NONE },
        { "timers.stopwatch", "Stopwatch",   NOCSIF_ICON_CLOCK, NULL,    NOCSIF_TAG_NONE },
        { "timers.world",     "World Clock", NOCSIF_ICON_GLOBE, NULL,    NOCSIF_TAG_NONE },
};
