/* Capitalised wallpaper name + row icon (style_name is lowercase, for tags). */
static const char *wp_title(int s)
{
    switch (s) {
        case NOCSIF_WP_SUN:      return "Engraved Sun";
        case NOCSIF_WP_GRIMOIRE: return "Grimoire";
        default:                 return "Orrery";
    }
}
static const char *wp_icon(int s)
{
    switch (s) {
        case NOCSIF_WP_SUN:      return NOCSIF_ICON_SUN;
        case NOCSIF_WP_GRIMOIRE: return NOCSIF_ICON_MOON;
        default:                 return NOCSIF_ICON_PLANET;
    }
}
/* The single accent-colour row's label, per wallpaper: it tints the sun / the stars (Grimoire sigil stays gray). */
static const char *wp_color_label(int s) { return s == NOCSIF_WP_SUN ? "Sun color" : "Star color"; }

/* ---- per-wallpaper settings: layer + comets toggles operate on the ACTIVE wallpaper (its settings
 * screen is only reached by selecting it, so the active style is always the one being edited). ------ */
static const char *wp_l0_tag(void) { int s = nocsif_ui_background_style(); return nocsif_wp_layer(s, 0) ? "on" : "off"; }
static const char *wp_l1_tag(void) { int s = nocsif_ui_background_style(); return nocsif_wp_layer(s, 1) ? "on" : "off"; }
static const char *wp_l2_tag(void) { int s = nocsif_ui_background_style(); return nocsif_wp_layer(s, 2) ? "on" : "off"; }
static void wp_l0_cb(lv_event_t *e) { (void)e; int s = nocsif_ui_background_style(); nocsif_wp_set_layer(s, 0, !nocsif_wp_layer(s, 0)); nocsif_nav_header_tick(); }
static void wp_l1_cb(lv_event_t *e) { (void)e; int s = nocsif_ui_background_style(); nocsif_wp_set_layer(s, 1, !nocsif_wp_layer(s, 1)); nocsif_nav_header_tick(); }
static void wp_l2_cb(lv_event_t *e) { (void)e; int s = nocsif_ui_background_style(); nocsif_wp_set_layer(s, 2, !nocsif_wp_layer(s, 2)); nocsif_nav_header_tick(); }
static const char *wp_com_tag(void) { int s = nocsif_ui_background_style(); return nocsif_wp_comets(s) ? "on" : "off"; }
static void wp_com_cb(lv_event_t *e) { (void)e; int s = nocsif_ui_background_style(); nocsif_wp_set_comets(s, !nocsif_wp_comets(s)); nocsif_nav_header_tick(); }

/* One wallpaper's settings: its own star colour, its own layer toggles, its own comets. */
static lv_obj_t *build_wallpaper_settings(void)
{
    int s = nocsif_ui_background_style();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold(wp_title(s), "colour " NOCSIF_DOT " layers", &content);
    lv_obj_t *list = nocsif_menu_list(content);

    theme_color_row(list, NOCSIF_ICON_STAR, wp_color_label(s), s, nocsif_wp_star_color(s));

    static const char *(*const lyr_tag[NOCSIF_WP_MAX_LAYERS])(void) = { wp_l0_tag, wp_l1_tag, wp_l2_tag };
    static void (*const lyr_cb[NOCSIF_WP_MAX_LAYERS])(lv_event_t *) = { wp_l0_cb, wp_l1_cb, wp_l2_cb };
    for (int i = 0; i < nocsif_wp_layer_count(s); i++)
        add_config_row(list, NOCSIF_ICON_RADIO, nocsif_wp_layer_name(s, i), lyr_tag[i], lyr_cb[i]);

    add_config_row(list, NOCSIF_ICON_HUNT, "Comets", wp_com_tag, wp_com_cb);

    lv_obj_t *note = lv_label_create(list);
    lv_label_set_text(note, "Star colour and these layers apply only to this wallpaper.");
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(note, 12, 0);
    return scr;
}

/* Wallpaper picker: tap a wallpaper to make it active + open its settings. */
static void wp_menu_row_cb(lv_event_t *e)
{
    int style = (int)(intptr_t)lv_event_get_user_data(e);
    nocsif_ui_background_set_style(style);          /* select it — the background changes now */
    nocsif_nav_push(build_wallpaper_settings());
    nocsif_nav_header_tick();
}

static void wp_menu_add_row(lv_obj_t *list, int style, int active)
{
    lv_obj_t *row = lv_obj_create(list);
    lv_obj_remove_style_all(row);
    lv_obj_add_style(row, &nocsif_style_row, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_set_scrollbar_mode(row, LV_SCROLLBAR_MODE_OFF);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *ic = lv_label_create(row);
    lv_label_set_text(ic, wp_icon(style));
    lv_obj_add_style(ic, &nocsif_style_row_icon, 0);
    lv_obj_set_width(ic, 24);
    lv_obj_set_style_text_align(ic, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_t *nm = lv_label_create(row);
    lv_label_set_text(nm, wp_title(style));
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_flex_grow(nm, 1);

    if (style == active) {
        lv_obj_t *tg = lv_label_create(row);
        lv_label_set_text(tg, "active");
        lv_obj_add_style(tg, &nocsif_style_row_tag, 0);
        lv_obj_set_style_text_color(tg, NOCSIF_VIOLET, 0);   /* accent */
    }

    lv_obj_t *dot = lv_obj_create(row);            /* swatch of this wallpaper's star colour */
    lv_obj_remove_style_all(dot);
    lv_obj_set_size(dot, 20, 20);
    lv_obj_set_style_radius(dot, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_color(dot, lv_color_hex(nocsif_wp_star_color(style)), 0);
    lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(dot, NOCSIF_EDGE2, 0);
    lv_obj_set_style_border_width(dot, 1, 0);
    lv_obj_remove_flag(dot, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(dot, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *chev = lv_label_create(row);
    lv_label_set_text(chev, NOCSIF_ICON_CHEV);
    lv_obj_add_style(chev, &nocsif_style_chevron, 0);

    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, wp_menu_row_cb, LV_EVENT_CLICKED, (void *)(intptr_t)style);
}

