/* ==== M11 — Settings > Power (screen sleep + power saver) ==================== *
 * The watch's power controls, split from Display. Slice P1: a configurable SCREEN TIMEOUT (the biggest
 * everyday battery lever on this emissive AMOLED) that replaces the old hardcoded 2-min idle-sleep.
 * Later slices add dim-before-sleep, sleep-when-still (F1), CPU DFS, and a Battery Saver master. */
static const struct { const char *name; int secs; } k_scr_timeout[] = {
    { "15 sec", 15 }, { "30 sec", 30 }, { "1 min", 60 }, { "2 min", 120 }, { "5 min", 300 }, { "never", 0 },
};
#define SCR_TIMEOUT_N     ((int)(sizeof(k_scr_timeout) / sizeof(k_scr_timeout[0])))
#define SCR_TIMEOUT_DFLT  120   /* seconds — matches the old hardcoded 2-min idle */

#define SAVER_TIMEOUT_S   15   /* Battery Saver forces at most this screen timeout */
static int scr_timeout_secs(void)
{
    int s = nocsif_settings_get_i32("scr_timeout", SCR_TIMEOUT_DFLT);
    if (s < 0) s = SCR_TIMEOUT_DFLT;
    if (s_saver_active && (s == 0 || s > SAVER_TIMEOUT_S)) return SAVER_TIMEOUT_S;   /* saver caps it short */
    return s;
}
static int scr_timeout_ix(void)
{
    int s = scr_timeout_secs();
    for (int i = 0; i < SCR_TIMEOUT_N; i++) if (k_scr_timeout[i].secs == s) return i;
    return 3;   /* fall back to "2 min" if a stored value matches no preset */
}
static const char *scr_timeout_tag(void) { return k_scr_timeout[scr_timeout_ix()].name; }
static void scr_timeout_click_cb(lv_event_t *e)
{
    (void)e;
    int ix = (scr_timeout_ix() + 1) % SCR_TIMEOUT_N;
    nocsif_settings_set_i32("scr_timeout", k_scr_timeout[ix].secs);
    lock_idle_reset();          /* restart the inactivity clock so the new timeout counts from now */
    nocsif_nav_header_tick();   /* refresh the row tag immediately */
}

static const char *dim_presleep_tag(void) { return nocsif_settings_get_i32("dim_presleep", 1) ? "on" : "off"; }
static void dim_presleep_click_cb(lv_event_t *e)
{
    (void)e;
    int v = nocsif_settings_get_i32("dim_presleep", 1) ? 0 : 1;
    nocsif_settings_set_i32("dim_presleep", v);
    if (!v) ui_predim_cancel();          /* turning it off restores full brightness now */
    nocsif_nav_header_tick();
}
static const char *sleep_still_tag(void) { return nocsif_settings_get_i32("sleep_still", 1) ? "on" : "off"; }
static void sleep_still_click_cb(lv_event_t *e)
{
    (void)e;
    nocsif_settings_set_i32("sleep_still", nocsif_settings_get_i32("sleep_still", 1) ? 0 : 1);
    nocsif_nav_header_tick();
}
static const char *power_saver_tag(void) { return nocsif_settings_get_i32("dfs_en", 0) ? "on" : "off"; }
static void power_saver_click_cb(lv_event_t *e)
{
    (void)e;
    int v = nocsif_settings_get_i32("dfs_en", 0) ? 0 : 1;
    nocsif_settings_set_i32("dfs_en", v);
    nocsif_pm_set_dfs(v || s_saver_active);   /* apply live; Battery Saver keeps DFS on regardless */
    nocsif_nav_header_tick();
}
static const char *shake_resleep_tag(void) { return nocsif_settings_get_i32("shake_resleep", 1) ? "on" : "off"; }
static void shake_resleep_click_cb(lv_event_t *e)
{
    (void)e;
    nocsif_settings_set_i32("shake_resleep", nocsif_settings_get_i32("shake_resleep", 1) ? 0 : 1);
    nocsif_nav_header_tick();
}
static const char *batt_saver_tag(void)
{
    if (nocsif_settings_get_i32("batt_saver", 0)) return "on";
    return s_saver_active ? "auto" : "off";       /* "auto" = auto-triggered by low battery right now */
}
static void batt_saver_click_cb(lv_event_t *e)
{
    (void)e;
    nocsif_settings_set_i32("batt_saver", nocsif_settings_get_i32("batt_saver", 0) ? 0 : 1);
    batt_saver_refresh();                          /* apply/lift the overlay now */
    nocsif_nav_header_tick();
}
static const char *batt_saver_auto_tag(void) { return nocsif_settings_get_i32("batt_saver_auto", 1) ? "< 20%" : "off"; }
static void batt_saver_auto_click_cb(lv_event_t *e)
{
    (void)e;
    nocsif_settings_set_i32("batt_saver_auto", nocsif_settings_get_i32("batt_saver_auto", 1) ? 0 : 1);
    batt_saver_refresh();
    nocsif_nav_header_tick();
}

static lv_obj_t *build_settings_power(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Power", "sleep " NOCSIF_DOT " battery", &content);
    lv_obj_t *list = nocsif_menu_list(content);
    add_config_row(list, NOCSIF_ICON_SUN, "Screen timeout",  scr_timeout_tag,  scr_timeout_click_cb);
    add_config_row(list, NOCSIF_ICON_SUN, "Dim before sleep", dim_presleep_tag, dim_presleep_click_cb);
    add_config_row(list, NOCSIF_ICON_ACT, "Sleep when still", sleep_still_tag,  sleep_still_click_cb);
    add_config_row(list, NOCSIF_ICON_SUN, "Re-sleep after shake", shake_resleep_tag, shake_resleep_click_cb);
    add_config_row(list, NOCSIF_ICON_BATT, "Power saver",     power_saver_tag,  power_saver_click_cb);
    add_config_row(list, NOCSIF_ICON_BATT, "Battery Saver",   batt_saver_tag,   batt_saver_click_cb);
    add_config_row(list, NOCSIF_ICON_BATT, "  auto",          batt_saver_auto_tag, batt_saver_auto_click_cb);

    lv_obj_t *note = lv_label_create(list);
    lv_label_set_text(note, "Screen timeout: how long the screen stays on after the last touch/button "
                            "before it sleeps (\"never\" = manual only). Dim before sleep: fades the panel "
                            "low a few seconds before it sleeps. Sleep when still: blanks early once the "
                            "watch is set down flat and motionless. Re-sleep after shake: if a shake wakes "
                            "the screen and you don't touch it within 2s, it sleeps again. Power saver: lets "
                            "the CPU down-clock (240 to 80 MHz) when idle.\n\nBattery Saver bundles it all at "
                            "once (CPU down-clock + short timeout + dimmer screen + reduced motion); \"auto\" "
                            "turns it on by itself below 20% while unplugged. Any tap/PWR/shake wakes the screen.");
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(note, 10, 0);
    return scr;
}

/* -- Reliability A2: System > Diagnostics (reset reason + last crash + persistent log tail) -- */
static lv_obj_t *s_diag_log_label;   /* valid only while the Diagnostics screen is alive */

static void diag_clear_cb(lv_event_t *e)
{
    (void)e;
    nocsif_logbook_clear();   /* deferred to the flush task; re-open Diagnostics to see it empty */
    if (s_diag_log_label) lv_label_set_text(s_diag_log_label, "(clearing...)");
}

/* M11-E1 — play an audible test tone so the MAX98357A speaker path can be verified on demand. Uses
 * the raw tone (not a cue), so it sounds even when the Sounds cue layer is muted — it is the
 * hardware test. A clear 1 kHz beep for 250 ms at near-full volume. */
static void diag_tone_cb(lv_event_t *e)
{
    (void)e;
    nocsif_audio_tone(1000, 250, 90);
}

static lv_obj_t *build_diag(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Diagnostics", "reliability", &content);

    /* Reset reason for THIS boot + the most recent crash record (task / PC / backtrace / ELF-sha).
     * Both come straight from the reliability module (NVS-backed, survives clean reboots). */
    const char *crash = nocsif_reliability_last_crash_str();
    char head[320];
    snprintf(head, sizeof(head), "Reset: %s\nLast crash: %s",
             nocsif_reliability_reset_reason_str(), crash[0] ? crash : "none recorded");
    nocsif_content_line(content, head, &nocsif_mono_12, NOCSIF_BONE, 0);

    nocsif_content_line(content, NOCSIF_NDASH " log " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);

    /* The most recent persisted log bytes (newest flushed sector + the un-committed RAM tail). */
    char *tail = malloc(2048);
    const char *lt_text;
    if (tail) {
        nocsif_logbook_read_tail(tail, 2048);
        lt_text = tail[0] ? tail : "(empty)";
    } else {
        lt_text = "(out of memory)";
    }
    s_diag_log_label = nocsif_content_line(content, lt_text, &nocsif_mono_11, NOCSIF_ASH, 0);
    if (tail) free(tail);   /* the helper's lv_label_set_text copied the string */

    lv_obj_t *list = nocsif_menu_list(content);
    lv_obj_t *tone = nocsif_menu_add_row(list, NOCSIF_ICON_PLAY, "Test tone",
                                         NULL, NULL, NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(tone, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(tone, diag_tone_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *row = nocsif_menu_add_row(list, NOCSIF_ICON_REFRESH, "Clear log",
                                        NULL, NULL, NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, diag_clear_cb, LV_EVENT_CLICKED, NULL);
    return scr;
}

/* ==== §4.1 Weather (Life > Weather) ================================================= *
 * The `weather` stub row made real. A worker (weather.{c,h}) fetches Open-Meteo over WiFi for
 * a home location the operator captures once from a GNSS fix, and caches a record this screen +
 * the watchface peek chip read. Two screens: the home screen (current + 3-day forecast + refresh
 * + units) and a pushed "Set Location" GNSS-capture screen (mirrors Live Fix). All bare labels
 * ride content padded at 26 (clears the rounded-corner clip). */

/* --- Set Location (GNSS capture) --- */
static lv_obj_t *s_wl_hero, *s_wl_sats, *s_wl_pos, *s_wl_save;

static void wl_tick(lv_timer_t *t)
{
    (void)t;
    if (s_wl_hero == NULL) return;

    nocsif_gnss_fix_t f;
    bool have  = nocsif_gnss_fix_snapshot(&f);
    bool live  = nocsif_gnss_live();
    bool fresh = have && f.stream_age_ms < 5000;
    bool fixed = have && (f.quality > 0 || f.valid) && (f.lat_deg != 0.0 || f.lon_deg != 0.0);
    char buf[96];

    const char *hero; lv_color_t hc;
    if (fixed && f.fix_type >= 3) { hero = "3D FIX";     hc = NOCSIF_VIOLET; }
    else if (fixed)               { hero = "FIX";        hc = NOCSIF_BONE;   }
    else if (fresh)               { hero = "ACQUIRING";  hc = NOCSIF_STEEL;  }
    else if (live)                { hero = "WARMING UP"; hc = NOCSIF_STEEL;  }
    else                          { hero = "NO SIGNAL";  hc = NOCSIF_ASH;    }
    gf_set(s_wl_hero, hero);
    lv_obj_set_style_text_color(s_wl_hero, hc, 0);

    if (have) snprintf(buf, sizeof buf, "%u used " NOCSIF_DOT " %u in view", f.sats_used, f.sats_in_view);
    else      snprintf(buf, sizeof buf, NOCSIF_NDASH " sats");
    gf_set(s_wl_sats, buf);

    if (fixed) {
        snprintf(buf, sizeof buf, "%.5f, %.5f", f.lat_deg, f.lon_deg);
        gf_set(s_wl_pos, buf);
        lv_obj_set_style_text_color(s_wl_pos, NOCSIF_WHITE, 0);
    } else {
        gf_set(s_wl_pos, "waiting for position...");
        lv_obj_set_style_text_color(s_wl_pos, NOCSIF_ASH, 0);
    }

    gf_set(s_wl_save, fixed ? "Save location" : "Waiting for fix...");
    lv_obj_set_style_text_color(s_wl_save, fixed ? NOCSIF_WHITE : NOCSIF_ASH, 0);
}

static void wl_save_cb(lv_event_t *e)
{
    (void)e;
    nocsif_gnss_fix_t f;
    if (nocsif_gnss_fix_snapshot(&f) && (f.quality > 0 || f.valid) &&
        (f.lat_deg != 0.0 || f.lon_deg != 0.0)) {
        nocsif_weather_set_location(f.lat_deg, f.lon_deg);   /* stores + kicks a fetch */
        nocsif_nav_back();   /* pop to the Weather screen; its tick picks up the new location */
    }
}

static void wl_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    nocsif_gnss_set_live(false);   /* drop the screen's live vote (a bg GPX track keeps its own) */
    s_wl_hero = s_wl_sats = s_wl_pos = s_wl_save = NULL;
}

static lv_obj_t *build_weather_setloc(void)
{
    nocsif_gnss_init();

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Set Location", "GNSS " NOCSIF_DOT " capture location", &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_wl_hero = gf_line(content, &nocsif_mono_18, NOCSIF_STEEL, "WARMING UP", 4);
    s_wl_sats = gf_line(content, &nocsif_mono_16, NOCSIF_BONE,  NOCSIF_NDASH " sats", 2);
    lv_obj_set_style_pad_bottom(s_wl_sats, 12, 0);
    s_wl_pos  = gf_line(content, &nocsif_mono_16, NOCSIF_ASH,   "waiting for position\xE2\x80\xA6", 0);

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_label_set_text(hint, "Step outside for a clear sky view " NOCSIF_NDASH " a cold fix can take ~30 s.");
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(hint, 12, 0);

    s_wl_save = gnss_pill(content, "Waiting for fix...", wl_save_cb);

    nocsif_gnss_set_live(true);   /* auto-start; stopped on exit */

    lv_timer_t *timer = lv_timer_create(wl_tick, 500, NULL);
    lv_obj_add_event_cb(scr, wl_deleted_cb, LV_EVENT_DELETE, timer);
    wl_tick(timer);
    return scr;
}

/* --- Weather home screen --- */
static lv_obj_t *s_wx_banner, *s_wx_data;
static lv_obj_t *s_wx_sign, *s_wx_num, *s_wx_deg, *s_wx_cond, *s_wx_meta;
static lv_obj_t *s_wx_glyph;               /* §4.14: the per-condition glyph beside the hero number */
static lv_obj_t *s_wx_fc_row[3], *s_wx_fc_ic[3], *s_wx_fc[3];   /* forecast rows: container, glyph, text */
static lv_obj_t *s_wx_foot, *s_wx_wifi;   /* footer text + a live WiFi connected/not glyph */
static int       s_wx_wifi_state = -1;    /* guard so the icon only repaints on a link change */
static lv_obj_t *s_wx_refresh, *s_wx_units, *s_wx_units_lbl;

/* short forecast-condition label (≤7 chars, fits a mono forecast row). */
static const char *wx_short(int c)
{
    switch (c) {
        case 0: case 1:                                  return "Clear";
        case 2:                                          return "P.Cloud";
        case 3:                                          return "Cloudy";
        case 45: case 48:                                return "Fog";
        case 51: case 53: case 55: case 56: case 57:     return "Drizzle";
        case 61: case 63: case 65: case 66: case 67:     return "Rain";
        case 71: case 73: case 75: case 77: case 85: case 86: return "Snow";
        case 80: case 81: case 82:                       return "Showers";
        case 95: case 96: case 99:                       return "Storm";
        default:                                         return NOCSIF_NDASH;
    }
}

/* §4.14 — WMO code -> icon-font glyph, shared by the peek chip, the Weather hero and the forecast rows
 * (the one cloud used to stand for every condition). Night: a clear sky shows the moon (Open-Meteo's
 * is_day); every other condition keeps its glyph. snow / storm / fog are the §4.14 additions to the font. */
static const char *wx_glyph_for_code(int c, bool is_day)
{
    switch (c) {
        case 0: case 1:                                      return is_day ? NOCSIF_ICON_SUN : NOCSIF_ICON_MOON;
        case 2: case 3:                                      return NOCSIF_ICON_WX;
        case 45: case 48:                                    return NOCSIF_ICON_FOG;
        case 51: case 53: case 55: case 56: case 57:
        case 61: case 63: case 65: case 66: case 67:
        case 80: case 81: case 82:                           return NOCSIF_ICON_RAIN;
        case 71: case 73: case 75: case 77: case 85: case 86: return NOCSIF_ICON_SNOW;
        case 95: case 96: case 99:                           return NOCSIF_ICON_STORM;
        default:                                             return NOCSIF_ICON_WX;
    }
}

static void wx_show(lv_obj_t *o, bool show)
{
    if (!o) return;
    if (show) lv_obj_clear_flag(o, LV_OBJ_FLAG_HIDDEN);
    else      lv_obj_add_flag(o, LV_OBJ_FLAG_HIDDEN);
}

static void wx_tick(lv_timer_t *t)
{
    (void)t;
    if (s_wx_data == NULL) return;

    bool has = nocsif_weather_has_location();
    nocsif_weather_t w;
    bool have  = nocsif_weather_snapshot(&w);
    bool valid = have && w.valid;

    wx_show(s_wx_banner, !has);
    wx_show(s_wx_data, has);
    wx_show(s_wx_refresh, has);
    wx_show(s_wx_units, has);
    /* the units button always reflects the CURRENT preference (data may be stale) */
    gf_set(s_wx_units_lbl, nocsif_weather_metric() ? "Show \xC2\xB0""F" : "Show \xC2\xB0""C");

    if (!has) return;

    /* Hero + conditions only once a fetch has populated the record. */
    wx_show(s_wx_num, valid);
    wx_show(s_wx_deg, valid);
    wx_show(s_wx_glyph, valid);
    wx_show(s_wx_cond, valid);
    wx_show(s_wx_meta, valid);
    for (int i = 0; i < 3; i++) wx_show(s_wx_fc_row[i], valid);

    char buf[96];
    if (valid) {
        int tt = (int)lroundf(w.temp);
        bool neg = tt < 0;
        wx_show(s_wx_sign, neg);
        snprintf(buf, sizeof buf, "%d", neg ? -tt : tt);
        gf_set(s_wx_num, buf);
        gf_set(s_wx_deg, w.metric ? "\xC2\xB0""C" : "\xC2\xB0""F");
        gf_set(s_wx_glyph, wx_glyph_for_code(w.code, w.is_day));

        gf_set(s_wx_cond, nocsif_weather_code_text(w.code));

        snprintf(buf, sizeof buf, "feels %d\xC2\xB0 " NOCSIF_DOT " %d%% " NOCSIF_DOT " wind %d %s",
                 (int)lroundf(w.feels), w.humidity, (int)lroundf(w.wind), w.metric ? "km/h" : "mph");
        gf_set(s_wx_meta, buf);

        for (int i = 0; i < 3; i++) {
            snprintf(buf, sizeof buf, "%-5s  %2d\xC2\xB0/%2d\xC2\xB0  %s",
                     w.d_day[i][0] ? w.d_day[i] : NOCSIF_NDASH,
                     (int)lroundf(w.d_hi[i]), (int)lroundf(w.d_lo[i]), wx_short(w.d_code[i]));
            gf_set(s_wx_fc[i], buf);
            gf_set(s_wx_fc_ic[i], wx_glyph_for_code(w.d_code[i], true));   /* a day's outlook: day form */
        }
    }

    /* Footer status line. */
    nocsif_weather_state_t st = have ? w.state : nocsif_weather_state();
    if (st == NOCSIF_WX_FETCHING) {
        snprintf(buf, sizeof buf, "updating...");
    } else if (st == NOCSIF_WX_NOWIFI) {
        snprintf(buf, sizeof buf, "no WiFi " NOCSIF_DOT " tap Refresh");
    } else if (st == NOCSIF_WX_ERR) {
        snprintf(buf, sizeof buf, valid ? "update failed " NOCSIF_DOT " showing last" : "update failed");
    } else if (valid) {
        uint32_t a = w.age_s;
        if (a < 60)        snprintf(buf, sizeof buf, "updated just now");
        else if (a < 3600) snprintf(buf, sizeof buf, "updated %u min ago", (unsigned)(a / 60));
        else               snprintf(buf, sizeof buf, "updated %u h ago", (unsigned)(a / 3600));
    } else {
        snprintf(buf, sizeof buf, "tap Refresh to fetch");
    }
    gf_set(s_wx_foot, buf);

    /* Live WiFi indicator: the glyph lights (accent) when the station has a link, dims when not —
     * a connected / not-connected symbol beside the footer text. */
    int wc = nocsif_wifi_connected() ? 1 : 0;
    if (wc != s_wx_wifi_state) {
        s_wx_wifi_state = wc;
        lv_obj_set_style_text_color(s_wx_wifi, wc ? NOCSIF_VIOLET : NOCSIF_ASH, 0);
    }
}

static void wx_refresh_cb(lv_event_t *e) { (void)e; nocsif_weather_request_refresh(true); }
static void wx_units_cb(lv_event_t *e)   { (void)e; nocsif_weather_set_metric(!nocsif_weather_metric()); }

static void wx_setloc_cb(lv_event_t *e)
{
    (void)e;
    lv_obj_t *root = build_weather_setloc();
    if (root) { lv_obj_update_layout(root); nocsif_nav_push(root); }
}

static void wx_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    s_wx_banner = s_wx_data = s_wx_sign = s_wx_num = s_wx_deg = s_wx_glyph = NULL;
    s_wx_cond = s_wx_meta = s_wx_foot = s_wx_wifi = NULL;
    s_wx_wifi_state = -1;
    for (int i = 0; i < 3; i++) s_wx_fc_row[i] = s_wx_fc_ic[i] = s_wx_fc[i] = NULL;
    s_wx_refresh = s_wx_units = s_wx_units_lbl = NULL;
}

static lv_obj_t *build_weather(void)
{
    nocsif_weather_init();

    char cap[40];
    double la, lo;
    if (nocsif_weather_get_location(&la, &lo)) snprintf(cap, sizeof cap, "%.3f, %.3f", la, lo);
    else                                       snprintf(cap, sizeof cap, "location not set");

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Weather", cap, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);

    /* No-location banner (shown until a home fix is captured). */
    s_wx_banner = lv_label_create(content);
    lv_label_set_long_mode(s_wx_banner, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_wx_banner, lv_pct(100));
    lv_label_set_text(s_wx_banner,
                      "No location yet.\nCapture from GPS below (or open any Location screen outside) "
                      "\xE2\x80\x93 Weather remembers your last fix and fetches over WiFi.");
    lv_obj_set_style_text_font(s_wx_banner, &nocsif_mono_14, 0);
    lv_obj_set_style_text_color(s_wx_banner, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(s_wx_banner, 6, 0);

    /* Data column (current conditions + forecast). */
    s_wx_data = lv_obj_create(content);
    lv_obj_remove_style_all(s_wx_data);
    lv_obj_set_width(s_wx_data, lv_pct(100));
    lv_obj_set_height(s_wx_data, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_wx_data, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(s_wx_data, LV_OBJ_FLAG_SCROLLABLE);

    /* Hero: big temperature (num_48 digits) + a small mono unit; a mono minus for sub-zero. */
    lv_obj_t *hero = lv_obj_create(s_wx_data);
    lv_obj_remove_style_all(hero);
    lv_obj_set_size(hero, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(hero, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(hero, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_column(hero, 2, 0);
    lv_obj_set_style_pad_top(hero, 2, 0);
    lv_obj_clear_flag(hero, LV_OBJ_FLAG_SCROLLABLE);

    s_wx_sign = lv_label_create(hero);
    lv_label_set_text(s_wx_sign, "-");
    lv_obj_set_style_text_font(s_wx_sign, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(s_wx_sign, NOCSIF_WHITE, 0);
    lv_obj_set_style_pad_top(s_wx_sign, 10, 0);
    lv_obj_add_flag(s_wx_sign, LV_OBJ_FLAG_HIDDEN);

    s_wx_num = lv_label_create(hero);
    lv_label_set_text(s_wx_num, "--");
    lv_obj_set_style_text_font(s_wx_num, &nocsif_num_48, 0);
    lv_obj_set_style_text_color(s_wx_num, NOCSIF_WHITE, 0);

    s_wx_deg = lv_label_create(hero);
    lv_label_set_text(s_wx_deg, "\xC2\xB0""F");
    lv_obj_set_style_text_font(s_wx_deg, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(s_wx_deg, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(s_wx_deg, 8, 0);

    /* §4.14 — the condition glyph beside the number (the thin XL cut sits well against num_48); hidden
     * until a fetch lands, then follows the WMO code (moon at night for a clear sky). */
    s_wx_glyph = lv_label_create(hero);
    lv_label_set_text(s_wx_glyph, NOCSIF_ICON_WX);
    lv_obj_set_style_text_font(s_wx_glyph, &nocsif_icons_xl, 0);
    lv_obj_set_style_text_color(s_wx_glyph, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_left(s_wx_glyph, 12, 0);
    lv_obj_set_style_pad_top(s_wx_glyph, 4, 0);

    s_wx_cond = lv_label_create(s_wx_data);
    lv_label_set_text(s_wx_cond, "");
    lv_obj_set_style_text_font(s_wx_cond, &nocsif_serif_20i, 0);
    lv_obj_set_style_text_color(s_wx_cond, NOCSIF_BONE, 0);

    s_wx_meta = lv_label_create(s_wx_data);
    lv_label_set_text(s_wx_meta, "");
    lv_obj_add_style(s_wx_meta, &nocsif_style_font_tag, 0);
    lv_obj_set_style_text_color(s_wx_meta, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(s_wx_meta, 6, 0);

    /* 3-day forecast rows: a per-condition glyph (§4.14) + mono text (mono for column alignment). */
    for (int i = 0; i < 3; i++) {
        s_wx_fc_row[i] = lv_obj_create(s_wx_data);
        lv_obj_remove_style_all(s_wx_fc_row[i]);
        lv_obj_set_size(s_wx_fc_row[i], LV_SIZE_CONTENT, LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(s_wx_fc_row[i], LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(s_wx_fc_row[i], LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_column(s_wx_fc_row[i], 8, 0);
        lv_obj_set_style_pad_top(s_wx_fc_row[i], i == 0 ? 14 : 4, 0);
        lv_obj_clear_flag(s_wx_fc_row[i], LV_OBJ_FLAG_SCROLLABLE);

        s_wx_fc_ic[i] = lv_label_create(s_wx_fc_row[i]);
        lv_label_set_text(s_wx_fc_ic[i], NOCSIF_ICON_WX);
        lv_obj_set_style_text_font(s_wx_fc_ic[i], &nocsif_icons, 0);
        lv_obj_set_style_text_color(s_wx_fc_ic[i], NOCSIF_STEEL, 0);

        s_wx_fc[i] = lv_label_create(s_wx_fc_row[i]);
        lv_label_set_text(s_wx_fc[i], "");
        lv_obj_add_style(s_wx_fc[i], &nocsif_style_font_tag, 0);
        lv_obj_set_style_text_color(s_wx_fc[i], NOCSIF_BONE, 0);
    }

    /* Footer row: a live WiFi glyph (connected = accent, else dim) + the status text. */
    lv_obj_t *foot_row = lv_obj_create(s_wx_data);
    lv_obj_remove_style_all(foot_row);
    lv_obj_set_size(foot_row, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(foot_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(foot_row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(foot_row, 6, 0);
    lv_obj_set_style_pad_top(foot_row, 14, 0);
    lv_obj_clear_flag(foot_row, LV_OBJ_FLAG_SCROLLABLE);

    s_wx_wifi = lv_label_create(foot_row);
    lv_label_set_text(s_wx_wifi, NOCSIF_ICON_WIFI);
    lv_obj_set_style_text_font(s_wx_wifi, &nocsif_icons, 0);
    lv_obj_set_style_text_color(s_wx_wifi, NOCSIF_ASH, 0);
    s_wx_wifi_state = -1;   /* force the first tick to colour it from the real link state */

    s_wx_foot = lv_label_create(foot_row);
    lv_label_set_text(s_wx_foot, "tap Refresh to fetch");
    lv_obj_add_style(s_wx_foot, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_wx_foot, NOCSIF_ASH, 0);

    /* Actions: Set location (always), Refresh + units toggle (once a location exists). */
    gnss_pill(content, "Set location", wx_setloc_cb);
    s_wx_refresh   = lv_obj_get_parent(gnss_pill(content, "Refresh", wx_refresh_cb));
    s_wx_units_lbl = gnss_pill(content, "Show \xC2\xB0""C", wx_units_cb);
    s_wx_units     = lv_obj_get_parent(s_wx_units_lbl);

    lv_timer_t *timer = lv_timer_create(wx_tick, 1000, NULL);
    lv_obj_add_event_cb(scr, wx_deleted_cb, LV_EVENT_DELETE, timer);
    wx_tick(timer);

    /* Opportunistic refresh on open (fetch only if already linked; never forces the radio up). */
    nocsif_weather_request_refresh(false);
    return scr;
}

/* ---- System > About (§4.1) — real device info ------------------------------------- *
 * A read-only info screen (Diagnostics' key/value-in-a-mono-label style): firmware +
 * hardware are snapshotted once at build; the runtime block (uptime / battery / free
 * heap) ticks each second via one label rewrite. */
static void about_fmt_uptime(char *out, size_t n)
{
    int64_t s = esp_timer_get_time() / 1000000;
    int d = (int)(s / 86400); s %= 86400;
    int h = (int)(s / 3600);  s %= 3600;
    int m = (int)(s / 60);    int sec = (int)(s % 60);
    if (d) snprintf(out, n, "%dd %02d:%02d:%02d", d, h, m, sec);
    else   snprintf(out, n, "%02d:%02d:%02d", h, m, sec);
}

static void about_runtime_fill(lv_obj_t *lbl)
{
    char up[32];
    about_fmt_uptime(up, sizeof(up));
    size_t ram_free   = heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
    size_t psram_free = heap_caps_get_free_size(MALLOC_CAP_SPIRAM);
    char buf[192];
    snprintf(buf, sizeof(buf),
             "Uptime: %s\nBattery: %s\nReset: %s\nFree RAM: %u KB\nFree PSRAM: %u KB",
             up, nocsif_power_batt_str(), nocsif_reliability_reset_reason_str(),
             (unsigned)(ram_free / 1024), (unsigned)(psram_free / 1024));
    lv_label_set_text(lbl, buf);
}

static void about_tick_cb(lv_timer_t *t)
{
    about_runtime_fill((lv_obj_t *)lv_timer_get_user_data(t));
}

/* Shared content-text helper (§4.1). A wrapped, left-aligned label added straight to a
 * scaffold content column sits at x=0, where the physical rounded-corner edge clips it.
 * MEASURED on-device with the interactive bounds calibrator: the visible screen is a
 * rounded rectangle — technically-perfect fit inset 5 / corner radius 125; the preferred
 * (slightly conservative) working bound is inset 7 / radius 115. Straight edges are usable
 * from ~7px; a SHARP corner needs ~41px to clear. Content here rides the straight edge
 * below the header, so UI_LIST_INSET (26) clears it with margin and lines up with the menu
 * column. Applied to About + Diagnostics now; route every direct-to-content label through
 * this later. Full numbers: docs/LESSONS.md (rounded-corner safe zone). */
static lv_obj_t *nocsif_content_line(lv_obj_t *content, const char *text,
                                     const lv_font_t *font, lv_color_t color, int pad_top)
{
    lv_obj_t *l = lv_label_create(content);
    lv_label_set_text(l, text);
    lv_label_set_long_mode(l, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(l, lv_pct(100));
    nocsif_label_font_scaled(l, font);                   /* §4.13: mono 11/12/13 follow the type scale */
    lv_obj_set_style_text_color(l, color, 0);
    lv_obj_set_style_pad_left(l, UI_LIST_INSET, 0);
    lv_obj_set_style_pad_right(l, UI_LIST_INSET, 0);
    if (pad_top) lv_obj_set_style_pad_top(l, pad_top, 0);
    return l;
}

static lv_obj_t *build_about(void)
{
    lv_obj_t *content;
    const char *dn = nocsif_settings_device_name();
    lv_obj_t *scr = nocsif_screen_scaffold("About", (dn && dn[0]) ? dn : NULL, &content);

    /* firmware — from the app image header (version / build stamp / elf sha / IDF). */
    const esp_app_desc_t *app = esp_app_get_description();
    char fw[224];
    if (app) {
        snprintf(fw, sizeof(fw), "Version: %s\nBuild: %s %s\nBuild id: %02x%02x%02x%02x\nIDF: %s",
                 app->version, app->date, app->time,
                 app->app_elf_sha256[0], app->app_elf_sha256[1],
                 app->app_elf_sha256[2], app->app_elf_sha256[3], app->idf_ver);
    } else {
        snprintf(fw, sizeof(fw), "(app description unavailable)");
    }

    /* hardware — chip / memory / MAC. */
    esp_chip_info_t chip;
    esp_chip_info(&chip);
    uint32_t flash_bytes = 0;
    esp_flash_get_size(NULL, &flash_bytes);
    size_t psram_bytes = esp_psram_get_size();
    uint8_t mac[6] = {0};
    esp_read_mac(mac, ESP_MAC_WIFI_STA);
    char hw[224];
    snprintf(hw, sizeof(hw),
             "Chip: ESP32-S3 rev v%d.%d\nCores: %d\nFlash: %.0f MB\nPSRAM: %.1f MB\n"
             "MAC: %02X:%02X:%02X:%02X:%02X:%02X",
             chip.revision / 100, chip.revision % 100, chip.cores,
             (double)flash_bytes / (1024.0 * 1024.0), (double)psram_bytes / (1024.0 * 1024.0),
             mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);

    nocsif_content_line(content, NOCSIF_NDASH " firmware " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 0);
    nocsif_content_line(content, fw, &nocsif_mono_12, NOCSIF_BONE, 0);
    nocsif_content_line(content, NOCSIF_NDASH " hardware " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);
    nocsif_content_line(content, hw, &nocsif_mono_12, NOCSIF_BONE, 0);
    nocsif_content_line(content, NOCSIF_NDASH " runtime " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);

    lv_obj_t *rt = nocsif_content_line(content, "", &nocsif_mono_12, NOCSIF_BONE, 0);
    about_runtime_fill(rt);
    lv_timer_t *t = lv_timer_create(about_tick_cb, 1000, rt);
    lv_obj_add_event_cb(rt, control_timer_deleted_cb, LV_EVENT_DELETE, t);
    return scr;
}

/* ==== M-OTA — System > Update (OTA) ============================================================ *
 * A/B firmware install from a microSD firmware.bin, with automatic rollback. The heavy work runs on
 * nocsif_ota's worker; this screen only posts scan/install requests and polls status. A fixed set of
 * labels + a manual progress bar are updated IN PLACE by a 400 ms tick and freed with the screen.
 * "Install & Reboot" is a two-tap confirm so a stray tap can never reflash the watch. */
static lv_obj_t *s_ota_run;       /* running slot + version + rollback posture */
static lv_obj_t *s_ota_card;      /* the card-image line                       */
static lv_obj_t *s_ota_btn_lbl;   /* Install button label (flips per state)    */
static lv_obj_t *s_ota_track;     /* progress track (hidden until a job runs)  */
static lv_obj_t *s_ota_fill;      /* progress fill                             */
static lv_obj_t *s_ota_stat;      /* status / progress caption                 */
static bool      s_ota_arm;       /* Install confirm armed (next tap commits)  */
static int64_t   s_ota_arm_t0;    /* when it was armed (auto-disarms)          */
/* §4.10 — the GitHub section: a live status line, the source line (tap → editor), Check + Download. */
static lv_obj_t *s_ota_web;       /* "v… available · 2.5 MB" / "up to date" / why it failed */
static lv_obj_t *s_ota_repo;      /* "source: owner/repo · tap to change"                     */
static lv_obj_t *s_ota_chk_lbl;   /* Check button label                                       */
static lv_obj_t *s_ota_dl_lbl;    /* Download button label                                    */

#define OTA_ARM_WINDOW_US  4000000   /* 4 s to tap Install again to confirm */

static void ota_fmt_size(uint32_t b, char *out, size_t n)
{
    if (b >= 1024u * 1024u)  snprintf(out, n, "%.2f MB", (double)b / (1024.0 * 1024.0));
    else if (b >= 1024u)     snprintf(out, n, "%.0f KB", (double)b / 1024.0);
    else                     snprintf(out, n, "%u B", (unsigned)b);
}

static void ota_refresh(void)
{
    nocsif_ota_state_t st = nocsif_ota_state();
    bool present = nocsif_ota_sd_present();

    if (s_ota_arm && esp_timer_get_time() - s_ota_arm_t0 > OTA_ARM_WINDOW_US) {
        s_ota_arm = false;   /* confirm window lapsed */
    }

    if (s_ota_run) {
        const esp_app_desc_t *app = esp_app_get_description();
        char b[128];
        snprintf(b, sizeof b, "%s  " NOCSIF_DOT "  v%s\n%s",
                 nocsif_ota_running_label(), app ? app->version : "?",
                 nocsif_ota_pending_verify() ? "pending verify " NOCSIF_DOT " rollback armed"
                                             : "confirmed");
        lv_label_set_text(s_ota_run, b);
    }

    if (s_ota_card) {
        char b[160];
        if (st == NOCSIF_OTA_SCANNING) {
            snprintf(b, sizeof b, "scanning card...");
        } else if (present) {
            char sz[24];
            ota_fmt_size(nocsif_ota_sd_size(), sz, sizeof sz);
            const char *v = nocsif_ota_sd_version();
            if (v && v[0]) snprintf(b, sizeof b, "firmware.bin  " NOCSIF_DOT "  %s  " NOCSIF_DOT "  v%s", sz, v);
            else           snprintf(b, sizeof b, "firmware.bin  " NOCSIF_DOT "  %s", sz);
        } else {
            snprintf(b, sizeof b, "%s", nocsif_ota_status_str());
        }
        lv_label_set_text(s_ota_card, b);
        lv_obj_set_style_text_color(s_ota_card, present ? NOCSIF_BONE : NOCSIF_STEEL, 0);
    }

    if (s_ota_btn_lbl) {
        const char *txt;
        lv_color_t col;
        if (st == NOCSIF_OTA_RUNNING)      { txt = "Installing...";        col = NOCSIF_STEEL; }
        else if (st == NOCSIF_OTA_SUCCESS) { txt = "Rebooting...";         col = NOCSIF_STEEL; }
        else if (!present)                 { txt = "Install & Reboot";     col = NOCSIF_EDGE2; }  /* dim = disabled */
        else if (s_ota_arm)                { txt = "Tap again to confirm"; col = NOCSIF_VIOLET; }
        else                               { txt = "Install & Reboot";     col = NOCSIF_BONE; }
        lv_label_set_text(s_ota_btn_lbl, txt);
        lv_obj_set_style_text_color(s_ota_btn_lbl, col, 0);
    }

    /* §4.10 — GitHub section. */
    nocsif_ota_web_state_t ws = nocsif_ota_web_state();
    if (s_ota_web) {
        char b[128], sz[24];
        lv_color_t col = NOCSIF_BONE;
        switch (ws) {
        case NOCSIF_OTA_WEB_CHECKING:    snprintf(b, sizeof b, "checking\xE2\x80\xA6"); col = NOCSIF_STEEL; break;
        case NOCSIF_OTA_WEB_UPTODATE:    snprintf(b, sizeof b, "up to date  " NOCSIF_DOT "  v%s", nocsif_ota_web_version()); break;
        case NOCSIF_OTA_WEB_AVAILABLE:
            ota_fmt_size(nocsif_ota_web_size(), sz, sizeof sz);
            snprintf(b, sizeof b, "v%s available  " NOCSIF_DOT "  %s", nocsif_ota_web_version(), sz);
            col = NOCSIF_VIOLET;
            break;
        case NOCSIF_OTA_WEB_DOWNLOADING: snprintf(b, sizeof b, "downloading v%s  %d%%", nocsif_ota_web_version(), nocsif_ota_web_progress()); col = NOCSIF_VIOLET; break;
        case NOCSIF_OTA_WEB_DOWNLOADED:  snprintf(b, sizeof b, "v%s on the card  " NOCSIF_DOT "  verified  " NOCSIF_DOT "  install below", nocsif_ota_web_version()); col = NOCSIF_VIOLET; break;
        case NOCSIF_OTA_WEB_FAILED:      snprintf(b, sizeof b, "%s", nocsif_ota_web_status_str()); col = NOCSIF_STEEL; break;
        default:                         snprintf(b, sizeof b, "tap Check for update"); col = NOCSIF_ASH; break;
        }
        lv_label_set_text(s_ota_web, b);
        lv_obj_set_style_text_color(s_ota_web, col, 0);
    }
    if (s_ota_repo) {
        char b[96];
        snprintf(b, sizeof b, "source: %s  " NOCSIF_DOT "  tap to change", nocsif_ota_repo());
        lv_label_set_text(s_ota_repo, b);
    }
    if (s_ota_chk_lbl) {
        bool busy = nocsif_ota_web_busy() || st == NOCSIF_OTA_RUNNING;
        lv_label_set_text(s_ota_chk_lbl, ws == NOCSIF_OTA_WEB_CHECKING ? "Checking\xE2\x80\xA6" : "Check for update");
        lv_obj_set_style_text_color(s_ota_chk_lbl, busy ? NOCSIF_EDGE2 : NOCSIF_STEEL, 0);
    }
    if (s_ota_dl_lbl) {
        const char *txt; lv_color_t col;
        if (ws == NOCSIF_OTA_WEB_DOWNLOADING)     { txt = "Downloading\xE2\x80\xA6"; col = NOCSIF_STEEL; }
        else if (ws == NOCSIF_OTA_WEB_AVAILABLE)  { txt = "Download to card";      col = NOCSIF_BONE;  }
        else if (ws == NOCSIF_OTA_WEB_DOWNLOADED) { txt = "Download again";        col = NOCSIF_STEEL; }
        else                                      { txt = "Download to card";      col = NOCSIF_EDGE2; }   /* dim = needs a Check */
        lv_label_set_text(s_ota_dl_lbl, txt);
        lv_obj_set_style_text_color(s_ota_dl_lbl, col, 0);
    }

    if (s_ota_track && s_ota_fill && s_ota_stat) {
        bool dl   = (ws == NOCSIF_OTA_WEB_DOWNLOADING);
        bool show = dl || (st == NOCSIF_OTA_RUNNING || st == NOCSIF_OTA_SUCCESS || st == NOCSIF_OTA_FAILED);
        if (show) lv_obj_remove_flag(s_ota_track, LV_OBJ_FLAG_HIDDEN);
        else      lv_obj_add_flag(s_ota_track, LV_OBJ_FLAG_HIDDEN);
        int p = dl ? nocsif_ota_web_progress() : nocsif_ota_progress();
        lv_obj_set_width(s_ota_fill, lv_pct(p));
        lv_obj_set_style_bg_color(s_ota_fill, (!dl && st == NOCSIF_OTA_FAILED) ? NOCSIF_STEEL : NOCSIF_VIOLET, 0);
        char b[96];
        if (dl)                            snprintf(b, sizeof b, "%s  %d%%", nocsif_ota_web_status_str(), p);
        else if (st == NOCSIF_OTA_RUNNING) snprintf(b, sizeof b, "%s  %d%%", nocsif_ota_status_str(), p);
        else                               snprintf(b, sizeof b, "%s", nocsif_ota_status_str());
        lv_label_set_text(s_ota_stat, show ? b : "");
        lv_obj_set_style_text_color(s_ota_stat, (!dl && st == NOCSIF_OTA_FAILED) ? NOCSIF_STEEL : NOCSIF_ASH, 0);
    }
}

/* §4.10 — GitHub section callbacks. */
static void ota_check_cb(lv_event_t *e)    { (void)e; s_ota_arm = false; nocsif_ota_request_web_check();    ota_refresh(); }
static void ota_download_cb(lv_event_t *e) { (void)e; s_ota_arm = false; nocsif_ota_request_web_download(); ota_refresh(); }
static void ota_repo_cb(lv_event_t *e)     { (void)e; app_drill("system.ota.repo"); }

static void ota_tick_cb(lv_timer_t *t) { (void)t; ota_refresh(); }

static void ota_rescan_cb(lv_event_t *e)
{
    (void)e;
    s_ota_arm = false;
    nocsif_ota_request_sd_scan();
    ota_refresh();
}

static void ota_install_cb(lv_event_t *e)
{
    (void)e;
    nocsif_ota_state_t st = nocsif_ota_state();
    if (st == NOCSIF_OTA_RUNNING || st == NOCSIF_OTA_SUCCESS || st == NOCSIF_OTA_SCANNING) return;
    if (!nocsif_ota_sd_present()) return;
    if (!s_ota_arm) {                     /* first tap: arm the confirm */
        s_ota_arm = true;
        s_ota_arm_t0 = esp_timer_get_time();
        ota_refresh();
        return;
    }
    s_ota_arm = false;                    /* second tap within the window: commit */
    nocsif_ota_request_install_sd();
    ota_refresh();
}

static void ota_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    s_ota_run = s_ota_card = s_ota_btn_lbl = NULL;
    s_ota_track = s_ota_fill = s_ota_stat = NULL;
    s_ota_web = s_ota_repo = s_ota_chk_lbl = s_ota_dl_lbl = NULL;
    s_ota_arm = false;
}

/* A full-width, bordered tap-target button (bigger + easier to hit than a bare text row): a faint
 * outline so it reads as a button, generous vertical padding for a tall touch area, and a large label.
 * gap_top spaces it below the previous element. Returns the label (the caller sets its text/colour and
 * the tick may re-colour it). */
static lv_obj_t *ota_button(lv_obj_t *content, lv_event_cb_t cb, int gap_top)
{
    lv_obj_t *b = lv_button_create(content);
    lv_obj_remove_style_all(b);
    lv_obj_add_flag(b, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_width(b, lv_pct(100));                       /* full-width tap target */
    lv_obj_set_style_bg_color(b, NOCSIF_PIT, LV_STATE_PRESSED);
    lv_obj_set_style_bg_opa(b, LV_OPA_COVER, LV_STATE_PRESSED);
    lv_obj_set_style_radius(b, 8, 0);
    lv_obj_set_style_border_width(b, 1, 0);                 /* faint outline so it reads as a button */
    lv_obj_set_style_border_color(b, NOCSIF_EDGE2, 0);
    lv_obj_set_style_margin_top(b, gap_top, 0);
    lv_obj_set_style_pad_left(b, UI_LIST_INSET, 0);
    lv_obj_set_style_pad_top(b, 15, 0);                     /* tall inside → easy to hit */
    lv_obj_set_style_pad_bottom(b, 15, 0);
    lv_obj_add_event_cb(b, cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *l = lv_label_create(b);
    lv_obj_set_style_text_font(l, &nocsif_mono_18, 0);      /* bigger label */
    return l;
}

static lv_obj_t *build_ota(void)
{
    nocsif_ota_init();   /* the PSRAM scan/check/download worker (idempotent). The 8 KB INTERNAL install
                          * worker is spawned only when Install is tapped (§4.10) — that internal RAM is
                          * what WiFi's RX buffers need during a GitHub download */

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Update", "A/B firmware " NOCSIF_DOT " GitHub " NOCSIF_DOT " microSD", &content);

    nocsif_content_line(content, NOCSIF_NDASH " running " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 0);
    s_ota_run = nocsif_content_line(content, "", &nocsif_mono_12, NOCSIF_BONE, 0);

    /* §4.10 — GitHub: Check (manifest) → Download (to the card, verified) → the Install path below. */
    nocsif_content_line(content, NOCSIF_NDASH " GitHub " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);
    s_ota_web  = nocsif_content_line(content, "", &nocsif_mono_12, NOCSIF_BONE, 0);
    s_ota_repo = nocsif_content_line(content, "", &nocsif_mono_11, NOCSIF_ASH, 2);
    lv_obj_add_flag(s_ota_repo, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(s_ota_repo, ota_repo_cb, LV_EVENT_CLICKED, NULL);
    s_ota_chk_lbl = ota_button(content, ota_check_cb, 8);
    lv_label_set_text(s_ota_chk_lbl, "Check for update");
    lv_obj_set_style_text_color(s_ota_chk_lbl, NOCSIF_STEEL, 0);
    s_ota_dl_lbl = ota_button(content, ota_download_cb, 8);
    lv_label_set_text(s_ota_dl_lbl, "Download to card");
    lv_obj_set_style_text_color(s_ota_dl_lbl, NOCSIF_EDGE2, 0);

    nocsif_content_line(content, NOCSIF_NDASH " microSD image " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);
    s_ota_card = nocsif_content_line(content, "", &nocsif_mono_12, NOCSIF_BONE, 0);
    nocsif_content_line(content,
        "Download above, or drop firmware.bin in /sd/nocsif/firmware/ over File Share (Settings "
        NOCSIF_NDASH " USB), then Rescan.",
        &nocsif_mono_11, NOCSIF_ASH, 4);

    lv_obj_t *rescan = ota_button(content, ota_rescan_cb, 10);
    lv_label_set_text(rescan, "Rescan card");
    lv_obj_set_style_text_color(rescan, NOCSIF_STEEL, 0);

    s_ota_btn_lbl = ota_button(content, ota_install_cb, 8);
    lv_label_set_text(s_ota_btn_lbl, "Install & Reboot");
    lv_obj_set_style_text_color(s_ota_btn_lbl, NOCSIF_EDGE2, 0);

    /* Progress bar (hidden until a job runs) — dark track + accent fill, width updated in place. */
    lv_obj_t *track = lv_obj_create(content);
    lv_obj_remove_style_all(track);
    lv_obj_set_width(track, lv_pct(100));
    lv_obj_set_height(track, 20);
    lv_obj_set_style_radius(track, 6, 0);
    lv_obj_set_style_bg_opa(track, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(track, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_width(track, 1, 0);
    lv_obj_set_style_border_color(track, NOCSIF_EDGE2, 0);
    lv_obj_set_style_margin_top(track, 8, 0);
    lv_obj_clear_flag(track, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(track, LV_OBJ_FLAG_HIDDEN);
    s_ota_track = track;

    s_ota_fill = lv_obj_create(track);
    lv_obj_remove_style_all(s_ota_fill);
    lv_obj_set_height(s_ota_fill, lv_pct(100));
    lv_obj_set_width(s_ota_fill, lv_pct(0));
    lv_obj_align(s_ota_fill, LV_ALIGN_LEFT_MID, 0, 0);
    lv_obj_set_style_radius(s_ota_fill, 6, 0);
    lv_obj_set_style_bg_opa(s_ota_fill, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(s_ota_fill, NOCSIF_VIOLET, 0);
    lv_obj_clear_flag(s_ota_fill, LV_OBJ_FLAG_SCROLLABLE);

    s_ota_stat = nocsif_content_line(content, "", &nocsif_mono_12, NOCSIF_ASH, 6);

    nocsif_content_line(content,
        "The image installs to the other slot and boots on reboot. It becomes permanent once it comes "
        "back up " NOCSIF_NDASH " otherwise the watch rolls back automatically. Settings and passcode "
        "are kept.",
        &nocsif_mono_11, NOCSIF_ASH, 14);

    s_ota_arm = false;
    nocsif_ota_request_sd_scan();   /* probe the card on open; result lands via the tick */
    ota_refresh();
    lv_timer_t *tm = lv_timer_create(ota_tick_cb, 400, NULL);
    lv_obj_add_event_cb(scr, ota_deleted_cb, LV_EVENT_DELETE, tm);
    return scr;
}

/* ---- §4.10 Update > source: the GitHub owner/repo the watch pulls from ------------------------ *
 * Same one-line field + keyboard as Watch Name. Save persists it (ota.c validates the owner/repo shape
 * and falls back to the default) and drops the stale check result. */
static void ota_repo_save(lv_obj_t *ta)
{
    nocsif_ota_set_repo(ta ? lv_textarea_get_text(ta) : "");
    nocsif_nav_back();
}
static void ota_repo_ready_cb(lv_event_t *e)  { ota_repo_save(lv_keyboard_get_textarea(lv_event_get_target(e))); }
static void ota_repo_btn_cb(lv_event_t *e)    { ota_repo_save((lv_obj_t *)lv_event_get_user_data(e)); }
static void ota_repo_cancel_cb(lv_event_t *e) { (void)e; nocsif_nav_back(); }

static lv_obj_t *build_ota_repo(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Update source", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, "GitHub owner/repo holding nocsif/firmware/firmware.bin (public)");
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 8, 0);

    lv_obj_t *ta = lv_textarea_create(content);
    lv_textarea_set_one_line(ta, true);
    lv_textarea_set_text(ta, nocsif_ota_repo());
    lv_obj_set_width(ta, lv_pct(100));
    lv_obj_set_style_bg_color(ta, NOCSIF_PIT, 0);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(ta, NOCSIF_BONE, 0);
    lv_obj_add_style(ta, &nocsif_style_row_name, 0);
    lv_obj_set_style_border_color(ta, NOCSIF_EDGE2, 0);
    lv_obj_set_style_border_width(ta, 1, 0);
    lv_obj_set_style_radius(ta, 6, 0);
    lv_obj_set_style_bg_color(ta, NOCSIF_VIOLET, LV_PART_CURSOR);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, LV_PART_CURSOR);

    lv_obj_t *save = lv_obj_create(content);
    lv_obj_remove_style_all(save);
    lv_obj_set_width(save, lv_pct(100));
    lv_obj_set_height(save, LV_SIZE_CONTENT);
    lv_obj_set_style_margin_top(save, 8, 0);
    lv_obj_set_style_bg_color(save, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_bg_opa(save, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(save, NOCSIF_VIOLET, 0);
    lv_obj_set_style_border_width(save, 1, 0);
    lv_obj_set_style_radius(save, 8, 0);
    lv_obj_set_style_pad_ver(save, 11, 0);
    lv_obj_clear_flag(save, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(save, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(save, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(save, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_t *sl = lv_label_create(save);
    lv_label_set_text(sl, "Save");
    lv_obj_center(sl);
    lv_obj_add_style(sl, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(sl, NOCSIF_WHITE, 0);
    lv_obj_add_event_cb(save, ota_repo_btn_cb, LV_EVENT_CLICKED, ta);

    lv_obj_t *kb = lv_keyboard_create(scr);
    lv_obj_add_flag(kb, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_keyboard_set_textarea(kb, ta);
    nocsif_companion_track_ta(ta);
    lv_keyboard_set_mode(kb, LV_KEYBOARD_MODE_TEXT_LOWER);
    lv_obj_set_size(kb, lv_pct(100), 196);
    lv_obj_align(kb, LV_ALIGN_BOTTOM_MID, 0, -58);
    lv_obj_set_style_bg_color(kb, NOCSIF_VOID, 0);
    lv_obj_set_style_bg_opa(kb, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(kb, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_all(kb, 3, 0);
    lv_obj_add_event_cb(kb, ota_repo_ready_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(kb, ota_repo_cancel_cb, LV_EVENT_CANCEL, NULL);
    return scr;
}

/* ---- System > Connectivity — live radio-link status hub (§4.1) --------------------- *
 * Read-only, About-style: one live line per radio (Wi-Fi / Phone·BLE / Sub-GHz LoRa / GNSS), refreshed
 * each second from each module's LVGL-safe cached getter (no radio/hardware access here). Each line is
 * accent-coloured while that radio holds a live link and dim otherwise — a one-glance "what's connected".
 * The four labels are file-scope (only one Connectivity screen exists at a time); the poll timer frees
 * with the screen via control_timer_deleted_cb, so no stale tick touches a freed label. */
static lv_obj_t *s_conn_wifi, *s_conn_ble, *s_conn_lora, *s_conn_gnss;

static void conn_line_set(lv_obj_t *l, const char *text, bool live)
{
    if (!l) return;
    lv_label_set_text(l, (text && text[0]) ? text : "\xE2\x80\x94");   /* em dash when empty */
    lv_obj_set_style_text_color(l, live ? NOCSIF_VIOLET : NOCSIF_ASH, 0);
}
static void conn_fill(void)
{
    /* Wi-Fi — station link (SSID / IP live in the detail string). */
    conn_line_set(s_conn_wifi, nocsif_wifi_detail_str(), nocsif_wifi_connected());

    /* Phone — the bonded-phone ANCS link (foreground mirror; live while connected / mirroring). */
    nocsif_ble_ancs_state_t ast = nocsif_ble_ancs_state();
    conn_line_set(s_conn_ble, nocsif_ble_ancs_status_str(),
                  ast == NOCSIF_ANCS_CONNECTED || ast == NOCSIF_ANCS_READY);

    /* Sub-GHz LoRa — ready once the radio has been brought up. */
    conn_line_set(s_conn_lora, nocsif_lora_status_str(), nocsif_lora_available());

    /* GNSS — fix summary from the live snapshot, else the module status. */
    char g[56];
    nocsif_gnss_fix_t fx;
    bool have  = nocsif_gnss_fix_snapshot(&fx);
    bool live  = nocsif_gnss_live();
    bool fixed = live && have && fx.valid;
    if (fixed) {
        snprintf(g, sizeof g, "%dD fix " NOCSIF_DOT " %u sats", fx.fix_type >= 3 ? 3 : 2, (unsigned)fx.sats_used);
    } else if (live) {
        snprintf(g, sizeof g, "no fix " NOCSIF_DOT " %u sats seen", (unsigned)(have ? fx.sats_in_view : 0));
    } else {
        snprintf(g, sizeof g, "%s", nocsif_gnss_status_str());
    }
    conn_line_set(s_conn_gnss, g, fixed);
}
static void conn_tick_cb(lv_timer_t *t) { (void)t; conn_fill(); }

/* ---- §4.6 Connectivity Governor P1 — the settings rows + live policy line (System > Connectivity) --- *
 * The Governor parks an idle, unlinked STA after a while (the away-from-home scan burn), wakes it to look
 * for the saved network every so often (P2 swaps the timer for the GPS geofence), and puts a linked-but-
 * idle STA into modem-sleep MAX. Activity/power only — the driver stays resident (never deinit). */
static const char *gov_ao_tag(void)    { return nocsif_gov_auto_off() ? "on" : "off"; }
static void        gov_ao_cb(lv_event_t *e) { (void)e; nocsif_gov_set_auto_off(!nocsif_gov_auto_off()); nocsif_nav_header_tick(); }
static const uint32_t k_gov_idle[]  = { 1, 5, 15, 30 };
static const uint32_t k_gov_retry[] = { 0, 5, 15, 30 };
static const char *gov_idle_tag(void)
{
    static char b[12];
    snprintf(b, sizeof b, "%u min", (unsigned)nocsif_gov_idle_min());
    return b;
}
static void gov_idle_cb(lv_event_t *e)
{
    (void)e;
    uint32_t cur = nocsif_gov_idle_min(), nx = k_gov_idle[0];
    for (size_t i = 0; i < sizeof k_gov_idle / sizeof k_gov_idle[0]; i++) {
        if (k_gov_idle[i] == cur) { nx = k_gov_idle[(i + 1) % (sizeof k_gov_idle / sizeof k_gov_idle[0])]; break; }
    }
    nocsif_gov_set_idle_min(nx);
    nocsif_nav_header_tick();
}
static const char *gov_retry_tag(void)
{
    static char b[12];
    uint32_t m = nocsif_gov_retry_min();
    if (m == 0) return "never";
    snprintf(b, sizeof b, "%u min", (unsigned)m);
    return b;
}
static void gov_retry_cb(lv_event_t *e)
{
    (void)e;
    uint32_t cur = nocsif_gov_retry_min(), nx = k_gov_retry[0];
    for (size_t i = 0; i < sizeof k_gov_retry / sizeof k_gov_retry[0]; i++) {
        if (k_gov_retry[i] == cur) { nx = k_gov_retry[(i + 1) % (sizeof k_gov_retry / sizeof k_gov_retry[0])]; break; }
    }
    nocsif_gov_set_retry_min(nx);
    nocsif_nav_header_tick();
}
static const char *gov_ps_tag(void)    { return nocsif_gov_modem_sleep() ? "on" : "off"; }
static void        gov_ps_cb(lv_event_t *e) { (void)e; nocsif_gov_set_modem_sleep(!nocsif_gov_modem_sleep()); nocsif_nav_header_tick(); }
static void gov_status_tick(lv_timer_t *t)
{
    lv_obj_t *lbl = (lv_obj_t *)lv_timer_get_user_data(t);
    const char *s = nocsif_gov_wifi_status_str();
    if (strcmp(lv_label_get_text(lbl), s) != 0) lv_label_set_text(lbl, s);
}
/* §4.6 P2–P4 — location: cyclic GPS + places (fences around saved networks). */
static void gov_loc_tick(lv_timer_t *t)
{
    lv_obj_t *lbl = (lv_obj_t *)lv_timer_get_user_data(t);
    const char *s = nocsif_gov_loc_status_str();
    if (strcmp(lv_label_get_text(lbl), s) != 0) lv_label_set_text(lbl, s);
}
static const char *gov_geo_tag(void)   { return nocsif_gov_geo() ? "on" : "off"; }
static void        gov_geo_cb(lv_event_t *e) { (void)e; nocsif_gov_set_geo(!nocsif_gov_geo()); nocsif_nav_header_tick(); }
static const uint32_t k_gov_gps[]    = { 2, 5, 10, 30 };
static const uint32_t k_gov_radius[] = { 100, 200, 500 };
static const char *gov_gps_tag(void)
{
    static char b[12];
    snprintf(b, sizeof b, "%u min", (unsigned)nocsif_gov_gps_min());
    return b;
}
static void gov_gps_cb(lv_event_t *e)
{
    (void)e;
    uint32_t cur = nocsif_gov_gps_min(), nx = k_gov_gps[0];
    for (size_t i = 0; i < sizeof k_gov_gps / sizeof k_gov_gps[0]; i++) {
        if (k_gov_gps[i] == cur) { nx = k_gov_gps[(i + 1) % (sizeof k_gov_gps / sizeof k_gov_gps[0])]; break; }
    }
    nocsif_gov_set_gps_min(nx);
    nocsif_nav_header_tick();
}
static const char *gov_radius_tag(void)
{
    static char b[12];
    snprintf(b, sizeof b, "%u m", (unsigned)nocsif_gov_radius_m());
    return b;
}
static void gov_radius_cb(lv_event_t *e)
{
    (void)e;
    uint32_t cur = nocsif_gov_radius_m(), nx = k_gov_radius[0];
    for (size_t i = 0; i < sizeof k_gov_radius / sizeof k_gov_radius[0]; i++) {
        if (k_gov_radius[i] == cur) { nx = k_gov_radius[(i + 1) % (sizeof k_gov_radius / sizeof k_gov_radius[0])]; break; }
    }
    nocsif_gov_set_radius_m(nx);
    nocsif_nav_header_tick();
}

static lv_obj_t *build_conn(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Connectivity", "links " NOCSIF_DOT " live", &content);

    nocsif_content_line(content, NOCSIF_NDASH " Wi-Fi " NOCSIF_NDASH,   &nocsif_mono_11, NOCSIF_STEEL, 0);
    s_conn_wifi = nocsif_content_line(content, "", &nocsif_mono_14, NOCSIF_ASH, 0);
    nocsif_content_line(content, NOCSIF_NDASH " Phone " NOCSIF_NDASH,   &nocsif_mono_11, NOCSIF_STEEL, 12);
    s_conn_ble  = nocsif_content_line(content, "", &nocsif_mono_14, NOCSIF_ASH, 0);
    nocsif_content_line(content, NOCSIF_NDASH " Sub-GHz " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);
    s_conn_lora = nocsif_content_line(content, "", &nocsif_mono_14, NOCSIF_ASH, 0);
    nocsif_content_line(content, NOCSIF_NDASH " GNSS " NOCSIF_NDASH,    &nocsif_mono_11, NOCSIF_STEEL, 12);
    s_conn_gnss = nocsif_content_line(content, "", &nocsif_mono_14, NOCSIF_ASH, 0);

    conn_fill();
    lv_timer_t *tm = lv_timer_create(conn_tick_cb, 1000, NULL);
    lv_obj_add_event_cb(s_conn_wifi, control_timer_deleted_cb, LV_EVENT_DELETE, tm);

    /* §4.6 P1 — Wi-Fi power policy (the Governor). */
    nocsif_content_line(content, NOCSIF_NDASH " Wi-Fi power " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);
    lv_obj_t *gov = nocsif_content_line(content, nocsif_gov_wifi_status_str(), &nocsif_mono_14, NOCSIF_ASH, 0);
    lv_timer_t *gt = lv_timer_create(gov_status_tick, 1000, gov);
    lv_obj_add_event_cb(gov, control_timer_deleted_cb, LV_EVENT_DELETE, gt);
    lv_obj_t *list = nocsif_menu_list(content);
    add_config_row(list, NOCSIF_ICON_WIFI, "Auto-off when idle", gov_ao_tag,    gov_ao_cb);
    add_config_row(list, NOCSIF_ICON_WIFI, "  after",            gov_idle_tag,  gov_idle_cb);
    add_config_row(list, NOCSIF_ICON_WIFI, "  look again every", gov_retry_tag, gov_retry_cb);
    add_config_row(list, NOCSIF_ICON_WIFI, "Modem sleep when linked", gov_ps_tag, gov_ps_cb);
    /* §4.6 P2–P4 — Location: cyclic GPS + places. */
    nocsif_content_line(content, NOCSIF_NDASH " Location " NOCSIF_NDASH, &nocsif_mono_11, NOCSIF_STEEL, 12);
    lv_obj_t *loc = nocsif_content_line(content, nocsif_gov_loc_status_str(), &nocsif_mono_14, NOCSIF_ASH, 0);
    lv_timer_t *lt = lv_timer_create(gov_loc_tick, 1000, loc);
    lv_obj_add_event_cb(loc, control_timer_deleted_cb, LV_EVENT_DELETE, lt);
    lv_obj_t *llist = nocsif_menu_list(content);
    add_config_row(llist, NOCSIF_ICON_LOC, "Auto-connect by place", gov_geo_tag,    gov_geo_cb);
    add_config_row(llist, NOCSIF_ICON_LOC, "  GPS check every",     gov_gps_tag,    gov_gps_cb);
    add_config_row(llist, NOCSIF_ICON_LOC, "  place radius",        gov_radius_tag, gov_radius_cb);

    lv_obj_t *note = lv_label_create(llist);
    lv_label_set_text(note, "Auto-off: with Wi-Fi on but no network in reach and nothing using it, the radio "
                            "is parked after the idle time (the tile keeps reading on). It wakes by itself "
                            "to look for your saved network at the retry interval, and any feature that "
                            "needs Wi-Fi (weather refresh, a Wi-Fi screen, a tap on the tile) wakes it at "
                            "once. A linked Wi-Fi is never parked; modem sleep lets it idle at ~1-2 mA.\n\n"
                            "Places: the watch learns where each saved network is the first time a GPS fix "
                            "coincides with a link. Every GPS-check period it wakes the receiver for one fix "
                            "(skipped while the watch has been still for 5 min; a Live Fix / GPX session's "
                            "fixes are used for free): arriving at a known place wakes a parked Wi-Fi at "
                            "once and refreshes the weather; away from every known place an unlinked Wi-Fi "
                            "parks after a minute. Indoors a fix rarely lands, so the retry timer stays as "
                            "the fallback.");
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(note, 10, 0);
    return scr;
}

/* ===== §4.8a Companion control surface (L4) — P1: System > Companion =========================== *
 * Raises the on-network web remote (open SoftAP + mDNS nocsif.local + HTTP :80). Off by default. The
 * screen shows the join SSID + passphrase + URL so a phone connects app-free.
 *
 * Radio policy (P4 reconciliation, RAM Phase 2): the surface used to turn Bluetooth OFF on Start and
 * back on at Stop, from the pre-Phase-2 belief that the WiFi surface needed the BT controller's
 * contiguous internal-DMA. Since Phase 2 the controller is claimed at boot and held RESIDENT for the
 * session, so nocsif_ble_bt_set_enabled(false) is a purely LOGICAL off — it freed nothing and only
 * dropped the phone link (ANCS/AMS), and because it persisted bt_master=0 a reboot/crash while the
 * surface was up (or auto-start at boot) left Bluetooth off until the user noticed. Bluetooth is now
 * left alone: the companion coexists with the phone link, like every other WiFi feature. */
static lv_obj_t *s_comp_status, *s_comp_start_lbl, *s_comp_ssid_v, *s_comp_url_v;
static lv_obj_t *s_comp_auto_acc, *s_comp_pw_acc;   /* live tags: auto-start on/off · password set/none */

#define COMP_K_AUTO "comp_auto"    /* persisted: auto-raise the companion on boot (0/1)   */
#define COMP_K_PW   "comp_pw"      /* persisted: companion AP WPA2 password (mirrors wifi.c K_COMP_PW) */

/* Turn the companion surface on/off. Shared by the Start/Stop row AND the boot auto-start. The
 * single-radio exclusions (monitor / captive portal) are enforced in wifi.c at bring-up. */
static void companion_set_on(bool on)
{
    if (on == nocsif_wifi_companion_active()) return;
    nocsif_wifi_companion_set(on);
}

static void companion_start_cb(lv_event_t *e)
{
    (void)e;
    companion_set_on(!nocsif_wifi_companion_active());
}

/* Auto-start on boot: a persisted toggle. The boot one-shot (registered at UI init) raises the surface
 * a few seconds after boot if set (and not in safe mode). */
static const char *companion_auto_tag(void) { return nocsif_settings_get_i32(COMP_K_AUTO, 0) ? "on" : "off"; }
static void companion_auto_cb(lv_event_t *e)
{
    (void)e;
    int nx = nocsif_settings_get_i32(COMP_K_AUTO, 0) ? 0 : 1;
    nocsif_settings_set_i32(COMP_K_AUTO, nx);
    if (s_comp_auto_acc) wifi_set_label(s_comp_auto_acc, nx ? "on" : "off");
}
static void companion_autostart_cb(lv_timer_t *t)
{
    lv_timer_del(t);   /* one-shot */
    if (nocsif_reliability_safe_mode()) return;         /* companion takes the radio — never in safe mode */
    if (nocsif_settings_get_i32(COMP_K_AUTO, 0)) companion_set_on(true);
}

static void companion_tick(lv_timer_t *t)
{
    (void)t;
    if (s_comp_status == NULL) {
        return;
    }
    bool on = nocsif_wifi_companion_active();
    wifi_set_label(s_comp_status, nocsif_wifi_companion_status_str());
    lv_obj_set_style_text_color(s_comp_status, on ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);
    if (s_comp_start_lbl) {
        wifi_set_label(s_comp_start_lbl, on ? "Stop" : "Start");
    }
    /* Reveal the join details only while up. */
    if (s_comp_ssid_v) wifi_set_label(s_comp_ssid_v, on ? nocsif_wifi_companion_ssid() : NOCSIF_NDASH);
    if (s_comp_url_v)  wifi_set_label(s_comp_url_v,  on ? nocsif_wifi_companion_url()  : NOCSIF_NDASH);
}

static void companion_deleted_cb(lv_event_t *e)
{
    lv_timer_del((lv_timer_t *)lv_event_get_user_data(e));
    s_comp_status = s_comp_start_lbl = s_comp_ssid_v = s_comp_url_v = NULL;
    s_comp_auto_acc = s_comp_pw_acc = NULL;
}

/* ---- §4.8a Companion — AP password editor (set / change / delete) --------------------------------- *
 * A text field + keyboard (mirrors Watch Name). Save persists "comp_pw" (WPA2, ≥8 chars) or, if blank,
 * removes it (→ open AP). If the companion is currently up, it is cycled so the new authmode applies at
 * once. The row tag on the Companion screen (s_comp_pw_acc) is refreshed live. */
static void companion_pw_apply(const char *pw)
{
    char clean[64];
    snprintf(clean, sizeof clean, "%s", pw ? pw : "");
    /* WPA2 needs 8-63 chars; treat anything shorter as "remove" so a stray value can't brick the AP. */
    if (strlen(clean) > 0 && strlen(clean) < 8) {
        return;   /* invalid: ignore Save (the hint tells the user the 8-char minimum) */
    }
    nocsif_settings_set_str(COMP_K_PW, clean);
    if (s_comp_pw_acc) wifi_set_label(s_comp_pw_acc, clean[0] ? "set" : "none");
    if (nocsif_wifi_companion_active()) {
        /* Re-apply the authmode by cycling the surface. Post OFF then ON straight to the worker (which
         * processes them in order) — NOT companion_set_on, whose guard reads the async s_comp_active
         * and would skip the ON. */
        nocsif_wifi_companion_set(false);
        nocsif_wifi_companion_set(true);
    }
    nocsif_nav_back();
}
static void companion_pw_save_cb(lv_event_t *e)
{
    lv_obj_t *ta = (lv_obj_t *)lv_event_get_user_data(e);
    companion_pw_apply(ta ? lv_textarea_get_text(ta) : "");
}
static void companion_pw_ready_cb(lv_event_t *e) { companion_pw_apply(lv_textarea_get_text(lv_keyboard_get_textarea(lv_event_get_target(e)))); }
static void companion_pw_cancel_cb(lv_event_t *e) { (void)e; nocsif_nav_back(); }
static void companion_pw_remove_cb(lv_event_t *e) { (void)e; companion_pw_apply(""); }

static lv_obj_t *build_companion_pw(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("AP Password", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, "secure the companion AP with WPA2 " NOCSIF_DOT " 8-63 characters " NOCSIF_DOT
                            " leave blank + Save to remove (open AP)");
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 8, 0);

    char cur[64];
    nocsif_settings_get_str(COMP_K_PW, cur, sizeof cur, "");

    lv_obj_t *ta = lv_textarea_create(content);
    lv_textarea_set_one_line(ta, true);
    lv_textarea_set_text(ta, cur);          /* prefill with the current password (edit = change) */
    lv_obj_set_width(ta, lv_pct(100));
    lv_obj_set_style_bg_color(ta, NOCSIF_PIT, 0);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(ta, NOCSIF_BONE, 0);
    lv_obj_add_style(ta, &nocsif_style_row_name, 0);
    lv_obj_set_style_border_color(ta, NOCSIF_EDGE2, 0);
    lv_obj_set_style_border_width(ta, 1, 0);
    lv_obj_set_style_radius(ta, 6, 0);
    lv_obj_set_style_bg_color(ta, NOCSIF_VIOLET, LV_PART_CURSOR);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, LV_PART_CURSOR);

    lv_obj_t *save = wifi_menu_row(content, "Save", NOCSIF_VIOLET, NULL, NULL, companion_pw_save_cb, ta);
    (void)save;
    wifi_menu_row(content, "Remove password", NOCSIF_GOLD, NULL, NULL, companion_pw_remove_cb, NULL);

    lv_obj_t *kb = lv_keyboard_create(scr);
    lv_obj_add_flag(kb, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_keyboard_set_textarea(kb, ta);
    nocsif_companion_track_ta(ta);   /* §4.8a P2: remote /api/type targets this field */
    lv_keyboard_set_mode(kb, LV_KEYBOARD_MODE_TEXT_LOWER);
    lv_obj_set_size(kb, lv_pct(100), 196);
    lv_obj_align(kb, LV_ALIGN_BOTTOM_MID, 0, -58);
    lv_obj_set_style_bg_color(kb, NOCSIF_VOID, 0);
    lv_obj_set_style_bg_opa(kb, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(kb, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_all(kb, 3, 0);
    lv_obj_add_event_cb(kb, companion_pw_ready_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(kb, companion_pw_cancel_cb, LV_EVENT_CANCEL, NULL);
    return scr;
}
static void companion_pw_open_cb(lv_event_t *e) { (void)e; nocsif_nav_push(build_companion_pw()); }

/* ===== §4.8a P2 command channel (phone -> watch) ============================================== *
 * The companion HTTP handlers (wifi.c, httpd task) forward each POST as a nocsif_companion_cmd_t to
 * companion_cmd_from_http (still on the httpd task); it heap-copies the command and marshals it onto
 * the LVGL task via lvgl_port_lock + lv_async_call — LVGL is never touched off its own task. The
 * tracker s_companion_ta = the most recently opened on-screen text field, so remote typing lands there. */
static lv_obj_t *s_companion_ta;

static void companion_ta_del_cb(lv_event_t *e)
{
    if (s_companion_ta == lv_event_get_target(e)) {
        s_companion_ta = NULL;
    }
}

static void nocsif_companion_track_ta(lv_obj_t *ta)
{
    s_companion_ta = ta;
    lv_obj_add_event_cb(ta, companion_ta_del_cb, LV_EVENT_DELETE, NULL);
}

/* Control-Center levers driven from the companion sliders — defined with the CC module (they touch its
 * slider parts + persistence). Forward-declared here so companion_exec_async can call them. */
static void companion_apply_brightness(int v);
static void companion_apply_volume(int v);
static void companion_set_cast(bool on);   /* fwd (defined with the mirror module below) */

/* Runs on the LVGL task (via lv_async_call): execute one companion command, then free the copy. */
static void companion_exec_async(void *p)
{
    nocsif_companion_cmd_t *c = p;
    switch (c->type) {
        case NOCSIF_COMPANION_CMD_LAUNCH: nocsif_app_launch(c->arg);   break;
        case NOCSIF_COMPANION_CMD_BACK:   nocsif_nav_back();           break;
        case NOCSIF_COMPANION_CMD_HOME:   nocsif_app_launch("home");   break;
        case NOCSIF_COMPANION_CMD_TYPE:
            if (s_companion_ta) lv_textarea_add_text(s_companion_ta, c->arg);
            break;
        case NOCSIF_COMPANION_CMD_KEY:
            if (s_companion_ta) {
                if      (strcmp(c->arg, "backspace") == 0) lv_textarea_delete_char(s_companion_ta);
                else if (strcmp(c->arg, "enter")     == 0) lv_textarea_add_char(s_companion_ta, '\n');
            }
            break;
        case NOCSIF_COMPANION_CMD_BRIGHTNESS: companion_apply_brightness(atoi(c->arg)); break;
        case NOCSIF_COMPANION_CMD_VOLUME:     companion_apply_volume(atoi(c->arg));     break;
        case NOCSIF_COMPANION_CMD_BUTTON:
            /* the phone's two side buttons → the same actions the physical FN/PWR raise */
            if      (strcmp(c->arg, "fn.short")  == 0) act_fn_back(NULL);
            else if (strcmp(c->arg, "fn.long")   == 0) act_fn_launch(NULL);
            else if (strcmp(c->arg, "pwr.short") == 0) act_pwr_short(NULL);
            else if (strcmp(c->arg, "pwr.long")  == 0) act_pwr_long(NULL);
            break;
        case NOCSIF_COMPANION_CMD_CAST: companion_set_cast(c->arg[0] == '1'); break;
        default: break;
    }
    free(c);
}

/* Runs on the HTTP server's task (registered into wifi.c). Copy the command to the heap and hand it to
 * the LVGL task; the async callback frees it. Dropped if the UI isn't ready or the LVGL port is busy. */
static void companion_cmd_from_http(const nocsif_companion_cmd_t *cmd)
{
    if (!cmd || !s_ui_ready || s_booting) {
        return;
    }
    nocsif_companion_cmd_t *c = malloc(sizeof *c);
    if (!c) {
        return;
    }
    *c = *cmd;
    if (lvgl_port_lock(200)) {
        lv_async_call(companion_exec_async, c);
        lvgl_port_unlock();
    } else {
        free(c);
        ESP_LOGW(TAG, "companion cmd dropped: LVGL port busy");
    }
}

/* ===== §4.8a Companion — screen mirror + interactive control (watch → phone) =================== *
 * The mirror is captured from the DISPLAY FLUSH path (companion_capture_region, called by
 * nocsif_flush_cb below): it reuses the frames the watch already renders, so there is NO extra render
 * cost and the phone tracks the watch with low latency (far better than the old ~1 Hz lv_snapshot). The
 * flush tap downsamples each dirty region MIR_SCALE:1 into s_mirror_fb (RGB565, PSRAM) and sets
 * s_mirror_dirty; this ~12 Hz tick publishes the buffer to wifi.c when it changed and a /ws client is
 * connected. Casting (s_cast_blank): the watch panel emission is turned off and the flush skips the
 * panel draw entirely, so all the SPI time goes to streaming — the phone becomes the display. */
static void    lock_idle_reset(void);        /* fwd (defined with the lock module)  */
static int32_t ui_base_brightness(void);     /* fwd (defined with the CC module)     */
/* §4.15: the mirror buffer is now captured at the panel's OWN resolution (1:1, 410×502 RGB565 = 411,640 B
 * PSRAM) so the desktop live view / screenshot are pixel-exact; the WiFi phone page keeps its 2:1 thumbnail
 * (a 4× frame would swamp that link) — companion_mirror_tick downsamples into s_thumb2 before publishing. */
#define MIR_SCALE   1                             /* capture scale (was 2:1, then 3:1) */
#define MIR_W       (NOCSIF_DISP_W / MIR_SCALE)   /* 410 */
#define MIR_H       (NOCSIF_DISP_H / MIR_SCALE)   /* 502 */
#define WIFI_MIR_SCALE 2                          /* the phone page's frame: 205×251 */
#define WIFI_MIR_W  (NOCSIF_DISP_W / WIFI_MIR_SCALE)
#define WIFI_MIR_H  (NOCSIF_DISP_H / WIFI_MIR_SCALE)
static uint8_t       *s_thumb2;           /* PSRAM: the 2:1 copy published to the WiFi page */
static uint8_t       *s_mirror_fb;        /* PSRAM: MIR_W*MIR_H RGB565-LE, written by the flush tap */
static volatile bool  s_mirror_dirty;
static volatile bool  s_cast_active;      /* companion up AND a /ws client connected (gates the flush tap) */
static volatile bool  s_shot_capture;     /* §4.15: a one-frame capture is in progress (nocsif_ui_screenshot) */
/* §4.15 live view over USB: the flush tap stays on while the desktop polls keep arriving (each poll
 * re-arms this deadline), and the tap unions every flushed region into a dirty bounding box (mirror
 * coordinates) that the next poll copies out — so a static screen costs a "no change" reply and a
 * ticking clock costs its digits, not 103 KB. Written on the LVGL task, read under the port lock. */
static volatile int64_t s_usb_mirror_until_us;
static int              s_mir_dx0 = -1, s_mir_dy0, s_mir_dx1, s_mir_dy1;
static uint32_t         s_mir_seq;
static bool           s_cast_blank;       /* casting: panel emission off + flush skips the panel draw */

static void companion_mirror_tick(lv_timer_t *t)
{
    (void)t;
    static bool was_watching;
    bool watching = nocsif_wifi_companion_active() && nocsif_wifi_companion_ws_clients() > 0;
    s_cast_active = watching;
    if (watching && !was_watching) {
        /* A client just (re)connected. The flush tap carries DIRTY regions only, so a mostly static
         * screen — the watchface, where only the time / almanac line repaints — reached the phone as
         * those few regions on top of whatever s_mirror_fb held from before (the "live control doesn't
         * show the watchface properly" report). Force one full repaint so the first frame is complete;
         * s_cast_active is already true, so the resulting flush is captured. */
        if (lv_screen_active()) lv_obj_invalidate(lv_screen_active());
    }
    was_watching = watching;
    if (watching && (esp_timer_get_time() - s_remote_last_us) < 4000000) {
        lock_idle_reset();   /* being driven remotely → keep the watch awake */
    }
    if (!watching) {
        if (s_cast_blank) {  /* phone left while casting → un-blank so the watch isn't stuck dark */
            s_cast_blank = false;
            nocsif_display_set_brightness((uint8_t)ui_base_brightness());
            if (lv_screen_active()) lv_obj_invalidate(lv_screen_active());
        }
        return;
    }
    if (s_mirror_fb && s_mirror_dirty) {
        s_mirror_dirty = false;
        /* the phone page gets a 2:1 copy (every other pixel of every other row) — the full-resolution
         * buffer is for the USB live view; a 411 KB frame at 12 fps would swamp the WiFi link */
        if (!s_thumb2) s_thumb2 = heap_caps_malloc((size_t)WIFI_MIR_W * WIFI_MIR_H * 2, MALLOC_CAP_SPIRAM);
        if (s_thumb2) {
            for (int y = 0; y < WIFI_MIR_H; y++) {
                const uint16_t *src = (const uint16_t *)(s_mirror_fb + (size_t)(y * WIFI_MIR_SCALE) * MIR_W * 2);
                uint16_t *dst = (uint16_t *)(s_thumb2 + (size_t)y * WIFI_MIR_W * 2);
                for (int x = 0; x < WIFI_MIR_W; x++) dst[x] = src[x * WIFI_MIR_SCALE];
            }
            nocsif_wifi_companion_publish_thumb(s_thumb2, WIFI_MIR_W, WIFI_MIR_H);
        }
    }
}

/* Toggle casting (panel-off streaming). Runs on the LVGL task (companion_exec_async). */
static void companion_set_cast(bool on)
{
    if (on == s_cast_blank) return;
    s_cast_blank = on;
    if (on) {
        nocsif_display_set_brightness(0);          /* AMOLED emission off — the phone is the display */
    } else {
        nocsif_display_set_brightness((uint8_t)ui_base_brightness());
        if (lv_screen_active()) lv_obj_invalidate(lv_screen_active());   /* repaint the panel */
    }
}

static lv_obj_t *build_companion(void)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Companion", "phone control surface", &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_label_set_text(note, "drive the watch from a phone browser " NOCSIF_DOT " join the open AP, open the link " NOCSIF_DOT " no app");
    lv_obj_set_style_pad_bottom(note, 6, 0);

    s_comp_status = lv_label_create(content);
    lv_label_set_long_mode(s_comp_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_comp_status, lv_pct(100));
    lv_obj_add_style(s_comp_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_comp_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_comp_status, "off");
    lv_obj_set_style_pad_bottom(s_comp_status, 8, 0);

    lv_obj_t *xrow = wifi_menu_row(content, "Start", NOCSIF_VIOLET, NULL, NULL, companion_start_cb, NULL);
    s_comp_start_lbl = lv_obj_get_child(xrow, 0);   /* the name label toggles Start/Stop */

    /* Auto-start on boot + AP password (operator additions). */
    wifi_menu_row(content, "Auto-start on boot", NOCSIF_BONE, companion_auto_tag(), &s_comp_auto_acc,
                  companion_auto_cb, NULL);
    {
        char pw[64];
        nocsif_settings_get_str(COMP_K_PW, pw, sizeof pw, "");
        wifi_menu_row(content, "Password", NOCSIF_BONE, pw[0] ? "set" : "none", &s_comp_pw_acc,
                      companion_pw_open_cb, NULL);
    }

    /* Join details (read-only), filled by the tick while the surface is up. */
    s_comp_ssid_v = wifi_kv_row(content, "network", NOCSIF_NDASH);
    s_comp_url_v  = wifi_kv_row(content, "open",    NOCSIF_NDASH);

    lv_obj_t *sec = lv_label_create(content);
    lv_label_set_long_mode(sec, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(sec, lv_pct(100));
    lv_obj_add_style(sec, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(sec, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(sec, 12, 0);
    lv_label_set_text(sec, "set a Password for WPA2, or leave it open " NOCSIF_DOT
                           " an open AP lets anyone who joins control the watch " NOCSIF_DOT
                           " BLE pauses while on " NOCSIF_DOT " authorized use");

    lv_timer_t *timer = lv_timer_create(companion_tick, 500, NULL);
    lv_obj_add_event_cb(scr, companion_deleted_cb, LV_EVENT_DELETE, timer);
    companion_tick(timer);   /* seed immediately */
    return scr;
}

/* M11-E1·2 — mic sensitivity presets (the RMS->level gain). Persisted as an index in "mic_sens" and
 * applied to the mic worker via nocsif_mic_set_gain. Default "high" so a speaking voice registers. */
static const struct { const char *name; float gain; } k_mic_sens[] = {
    { "low", 40.0f }, { "med", 100.0f }, { "high", 200.0f }, { "max", 400.0f },
};
#define MIC_SENS_N    ((int)(sizeof(k_mic_sens) / sizeof(k_mic_sens[0])))
#define MIC_SENS_DFLT 2   /* "high" */

static int mic_sens_ix(void)
{
    int ix = nocsif_settings_get_i32("mic_sens", MIC_SENS_DFLT);
    if (ix < 0 || ix >= MIC_SENS_N) ix = MIC_SENS_DFLT;
    return ix;
}
static void mic_apply_saved_gain(void)
{
    nocsif_mic_set_gain(k_mic_sens[mic_sens_ix()].gain);
}
static const char *mic_sens_tag(void)
{
    if (!nocsif_mic_available()) return "n/a";
    return k_mic_sens[mic_sens_ix()].name;
}
static void mic_sens_click_cb(lv_event_t *e)
{
    (void)e;
    if (!nocsif_mic_available()) return;
    int ix = (mic_sens_ix() + 1) % MIC_SENS_N;
    nocsif_settings_set_i32("mic_sens", ix);
    nocsif_mic_set_gain(k_mic_sens[ix].gain);
    nocsif_nav_header_tick();
}

/* -- M11 E1·2: System > Microphone — PDM mic proof-of-life level meter -- *
 * A live input-level bar driven by the mic worker's cached level (nocsif_mic_level). The mic captures
 * only while this screen is alive: set_active(true) on build, set_active(false) on delete (which also
 * frees the PDM channel). The bar/number are a FIXED set of widgets updated IN PLACE each tick (never
 * recreated), and each write is guarded on a value change, so a silent screen performs no repaint. */
static lv_obj_t *s_mic_num;        /* big level % number (num_48)   */
static lv_obj_t *s_mic_peak_lbl;   /* "peak NN%" caption            */
static lv_obj_t *s_mic_fill;       /* violet fill rect on the track */
static int       s_mic_last_lvl  = -1;
static int       s_mic_last_peak = -1;

static void mic_tick(lv_timer_t *t)
{
    (void)t;
    int lvl = (int)nocsif_mic_level();
    int pk  = (int)nocsif_mic_peak();
    if (lvl != s_mic_last_lvl) {
        s_mic_last_lvl = lvl;
        if (s_mic_num) {
            char b[8];
            snprintf(b, sizeof b, "%d", lvl);
            lv_label_set_text(s_mic_num, b);
        }
        if (s_mic_fill) {
            lv_obj_set_width(s_mic_fill, lv_pct(lvl));
        }
    }
    if (pk != s_mic_last_peak) {
        s_mic_last_peak = pk;
        if (s_mic_peak_lbl) {
            char b[16];
            snprintf(b, sizeof b, "peak %d%%", pk);
            lv_label_set_text(s_mic_peak_lbl, b);
        }
    }
}

static void mic_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    nocsif_mic_set_active(false);   /* stop capture + free the PDM RX channel */
    s_mic_num = s_mic_peak_lbl = s_mic_fill = NULL;
    s_mic_last_lvl = s_mic_last_peak = -1;
}

static lv_obj_t *build_mic(void)
{
    nocsif_mic_init();   /* lazy worker create (idempotent); frees its 6 KB internal-DMA stack at boot */

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Microphone", "audio input " NOCSIF_DOT " level meter", &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    if (!nocsif_mic_available()) {
        lv_obj_t *na = lv_label_create(content);
        lv_label_set_text(na, "Microphone unavailable (safe mode, or the worker did not start).");
        lv_label_set_long_mode(na, LV_LABEL_LONG_WRAP);
        lv_obj_set_width(na, lv_pct(100));
        lv_obj_add_style(na, &nocsif_style_font_caption, 0);
        lv_obj_set_style_text_color(na, NOCSIF_STEEL, 0);
        return scr;
    }

    mic_apply_saved_gain();   /* honor the saved Sensitivity preset for this session's meter */

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, "Blow on the mic or speak " NOCSIF_NDASH " the bar tracks the input level.");
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 14, 0);

    /* Hero: big live level number + caption + decaying peak. */
    lv_obj_t *hero = lv_obj_create(content);
    lv_obj_remove_style_all(hero);
    lv_obj_set_width(hero, lv_pct(100));
    lv_obj_set_height(hero, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(hero, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(hero, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_column(hero, 10, 0);
    lv_obj_set_style_pad_bottom(hero, 8, 0);
    lv_obj_clear_flag(hero, LV_OBJ_FLAG_SCROLLABLE);

    s_mic_num = lv_label_create(hero);
    lv_label_set_text(s_mic_num, "0");
    lv_obj_set_style_text_font(s_mic_num, &nocsif_num_48, 0);
    lv_obj_set_style_text_color(s_mic_num, NOCSIF_WHITE, 0);

    lv_obj_t *hcol = lv_obj_create(hero);
    lv_obj_remove_style_all(hcol);
    lv_obj_set_flex_flow(hcol, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_height(hcol, LV_SIZE_CONTENT);
    lv_obj_set_flex_grow(hcol, 1);
    lv_obj_clear_flag(hcol, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_bottom(hcol, 6, 0);

    lv_obj_t *cap = lv_label_create(hcol);
    lv_label_set_text(cap, "input level %");
    lv_obj_add_style(cap, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(cap, NOCSIF_STEEL, 0);

    s_mic_peak_lbl = lv_label_create(hcol);
    lv_label_set_text(s_mic_peak_lbl, "peak 0%");
    lv_obj_add_style(s_mic_peak_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_mic_peak_lbl, NOCSIF_ASH, 0);

    /* Level bar: a dark track with a violet fill whose width tracks the level (updated in place). */
    lv_obj_t *track = lv_obj_create(content);
    lv_obj_remove_style_all(track);
    lv_obj_set_width(track, lv_pct(100));
    lv_obj_set_height(track, 26);
    lv_obj_set_style_radius(track, 6, 0);
    lv_obj_set_style_bg_opa(track, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(track, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_width(track, 1, 0);
    lv_obj_set_style_border_color(track, NOCSIF_EDGE2, 0);
    lv_obj_clear_flag(track, LV_OBJ_FLAG_SCROLLABLE);

    s_mic_fill = lv_obj_create(track);
    lv_obj_remove_style_all(s_mic_fill);
    lv_obj_set_height(s_mic_fill, lv_pct(100));
    lv_obj_set_width(s_mic_fill, lv_pct(0));
    lv_obj_align(s_mic_fill, LV_ALIGN_LEFT_MID, 0, 0);
    lv_obj_set_style_radius(s_mic_fill, 6, 0);
    lv_obj_set_style_bg_opa(s_mic_fill, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(s_mic_fill, NOCSIF_VIOLET, 0);
    lv_obj_clear_flag(s_mic_fill, LV_OBJ_FLAG_SCROLLABLE);

    /* Sensitivity control (tap to cycle Low/Med/High/Max — the bar reacts live). */
    lv_obj_t *slist = nocsif_menu_list(content);
    add_config_row(slist, NOCSIF_ICON_MIC, "Sensitivity", mic_sens_tag, mic_sens_click_cb);

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_text(note, "The mic captures only while this screen is open.");
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(note, 16, 0);

    s_mic_last_lvl = s_mic_last_peak = -1;
    nocsif_mic_set_active(true);   /* start capturing while this screen is alive */

    lv_timer_t *timer = lv_timer_create(mic_tick, 90, NULL);
    lv_obj_add_event_cb(scr, mic_deleted_cb, LV_EVENT_DELETE, timer);
    mic_tick(timer);   /* seed immediately */
    return scr;
}

/* -- M11 E1·3: Voice Memos — record to a WAV on /sd, play back through the E1·1 amp -- *
 * Recording rides the mic worker (PCM -> PSRAM -> WAV on stop, nocsif_mic_record_*); playback is
 * nocsif_audio_play_wav. The list snapshots /sd/nocsif/voice under the SD lock (the macro-picker idiom;
 * the app owns /sd outside File Share, so no claim_sd on the LVGL task); a memo drills into Play/Delete. */
#define UI_VOICE_DIR   "/sd/nocsif/voice"
#define UI_VOICE_MAX   32
#define UI_VOICE_NAMEL 40

static char      s_voice_sel[96];       /* memo path selected for the detail screen        */
static char      s_voice_rec_path[96];  /* path of the in-progress recording               */
static int       s_voice_next;          /* next memo index (computed on build)             */
static bool      s_voice_session;       /* a record session is in flight (add its row on DONE) */
static lv_obj_t *s_voice_btn_lbl;       /* Record/Stop button label                        */
static lv_obj_t *s_voice_stat;          /* status line                                     */
static lv_obj_t *s_voice_fill;          /* live input-level bar fill                        */
static lv_obj_t *s_voice_list;          /* the memo list (rows added on save)              */
static int       s_voice_last_lvl = -1; /* level-bar guard (skip redundant repaints)       */

static lv_obj_t *build_voice_item(void);
static lv_obj_t *build_voice_rename(void);
static void      voice_add_row(lv_obj_t *list, const char *name);

static void voice_rec_tick(lv_timer_t *t)
{
    (void)t;
    int lvl = (int)nocsif_mic_level();
    if (s_voice_fill && lvl != s_voice_last_lvl) {   /* guard: only repaint on a level change */
        s_voice_last_lvl = lvl;
        lv_obj_set_width(s_voice_fill, lv_pct(lvl));
    }
    const char *btn = "Record";
    char buf[56];
    switch (nocsif_mic_record_state()) {
    case NOCSIF_MIC_REC_RECORDING:
        btn = "Stop";
        snprintf(buf, sizeof buf, "recording %us / %ds", (unsigned)nocsif_mic_record_secs(),
                 NOCSIF_MIC_REC_MAX_SECS);
        break;
    case NOCSIF_MIC_REC_SAVING:
        btn = "Stop";
        strcpy(buf, "saving\xE2\x80\xA6");
        break;
    case NOCSIF_MIC_REC_DONE:
        if (s_voice_session) {                     /* our recording just landed -> add its row */
            s_voice_session = false;
            const char *nm = strrchr(s_voice_rec_path, '/');
            if (nm && s_voice_list) voice_add_row(s_voice_list, nm + 1);
        }
        snprintf(buf, sizeof buf, "saved (%us)", (unsigned)nocsif_mic_record_secs());
        break;
    case NOCSIF_MIC_REC_ERROR:
        s_voice_session = false;
        snprintf(buf, sizeof buf, "%s", nocsif_mic_rec_error_str());   /* §4.13: the real reason, not "check the card" */
        break;
    default:
        strcpy(buf, "tap Record to start");
        break;
    }
    if (s_voice_btn_lbl && strcmp(lv_label_get_text(s_voice_btn_lbl), btn) != 0) {
        lv_label_set_text(s_voice_btn_lbl, btn);
    }
    if (s_voice_stat && strcmp(lv_label_get_text(s_voice_stat), buf) != 0) {
        lv_label_set_text(s_voice_stat, buf);
    }
}

static void voice_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    /* Do NOT stop a recording on screen exit — it continues in the BACKGROUND (the red dot shows it,
     * and re-entering shows the live Stop). The mic worker is kept alive by the recording itself. */
    s_voice_btn_lbl = s_voice_stat = s_voice_fill = s_voice_list = NULL;
}

static void voice_rec_click_cb(lv_event_t *e)
{
    (void)e;
    if (!nocsif_mic_available()) return;
    if (nocsif_mic_recording()) {
        nocsif_mic_record_stop();
        return;
    }
    snprintf(s_voice_rec_path, sizeof s_voice_rec_path, "%s/memo-%03d.wav", UI_VOICE_DIR, s_voice_next);
    if (s_voice_next < 999) s_voice_next++;
    s_voice_session = true;
    nocsif_mic_record_start(s_voice_rec_path);
}

static void voice_row_click_cb(lv_event_t *e)
{
    const char *path = (const char *)lv_event_get_user_data(e);
    strncpy(s_voice_sel, path, sizeof s_voice_sel - 1);
    s_voice_sel[sizeof s_voice_sel - 1] = '\0';
    lv_obj_t *root = build_voice_item();
    if (root) nocsif_nav_push(root);
}
static void voice_row_deleted_cb(lv_event_t *e)
{
    free(lv_event_get_user_data(e));   /* the per-row heap path */
}
static void voice_add_row(lv_obj_t *list, const char *name)
{
    char *path = (char *)malloc(strlen(UI_VOICE_DIR) + 1 + strlen(name) + 1);
    if (path == NULL) return;
    strcpy(path, UI_VOICE_DIR "/");
    strcat(path, name);
    lv_obj_t *row = nocsif_menu_add_row(list, NOCSIF_ICON_PLAY, name, NULL, NULL,
                                        NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, voice_row_click_cb,   LV_EVENT_CLICKED, path);
    lv_obj_add_event_cb(row, voice_row_deleted_cb, LV_EVENT_DELETE,  path);
}

static lv_obj_t *build_voice(void)
{
    nocsif_mic_init();   /* lazy worker create (idempotent) — recording needs the mic worker */

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Voice Memos", "record " NOCSIF_DOT " play", &content);
    lv_obj_set_style_pad_hor(content, 20, 0);

    if (!nocsif_mic_available()) {
        lv_obj_t *na = lv_label_create(content);
        lv_label_set_text(na, "Microphone unavailable (safe mode, or the worker did not start).");
        lv_label_set_long_mode(na, LV_LABEL_LONG_WRAP);
        lv_obj_set_width(na, lv_pct(100));
        lv_obj_add_style(na, &nocsif_style_font_caption, 0);
        lv_obj_set_style_text_color(na, NOCSIF_STEEL, 0);
        return scr;
    }

    mic_apply_saved_gain();   /* the live level bar honors the saved Sensitivity preset */

    /* Record / Stop button. */
    lv_obj_t *btn = lv_obj_create(content);
    lv_obj_remove_style_all(btn);
    lv_obj_set_width(btn, lv_pct(100));
    lv_obj_set_height(btn, 50);
    lv_obj_set_style_radius(btn, 8, 0);
    lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(btn, NOCSIF_VIOLET, 0);
    lv_obj_set_flex_flow(btn, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(btn, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_add_flag(btn, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(btn, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(btn, voice_rec_click_cb, LV_EVENT_CLICKED, NULL);
    s_voice_btn_lbl = lv_label_create(btn);
    lv_label_set_text(s_voice_btn_lbl, "Record");
    lv_obj_add_style(s_voice_btn_lbl, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_voice_btn_lbl, NOCSIF_WHITE, 0);

    s_voice_stat = lv_label_create(content);
    lv_label_set_text(s_voice_stat, "tap Record to start");
    lv_obj_add_style(s_voice_stat, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_voice_stat, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(s_voice_stat, 10, 0);
    lv_obj_set_style_pad_bottom(s_voice_stat, 6, 0);

    /* Live input-level bar. */
    lv_obj_t *track = lv_obj_create(content);
    lv_obj_remove_style_all(track);
    lv_obj_set_width(track, lv_pct(100));
    lv_obj_set_height(track, 8);
    lv_obj_set_style_radius(track, 4, 0);
    lv_obj_set_style_bg_opa(track, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(track, NOCSIF_EDGE, 0);
    lv_obj_clear_flag(track, LV_OBJ_FLAG_SCROLLABLE);
    s_voice_fill = lv_obj_create(track);
    lv_obj_remove_style_all(s_voice_fill);
    lv_obj_set_height(s_voice_fill, lv_pct(100));
    lv_obj_set_width(s_voice_fill, lv_pct(0));
    lv_obj_align(s_voice_fill, LV_ALIGN_LEFT_MID, 0, 0);
    lv_obj_set_style_radius(s_voice_fill, 4, 0);
    lv_obj_set_style_bg_opa(s_voice_fill, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(s_voice_fill, NOCSIF_VIOLET, 0);
    lv_obj_clear_flag(s_voice_fill, LV_OBJ_FLAG_SCROLLABLE);

    /* Memo list: snapshot names under the SD lock, then build rows + compute the next index. */
    static char names[UI_VOICE_MAX][UI_VOICE_NAMEL];
    int n = 0, maxix = -1;
    if (nocsif_sdcard_lock(1000)) {
        DIR *d = opendir(UI_VOICE_DIR);
        if (d != NULL) {
            struct dirent *ent;
            while ((ent = readdir(d)) != NULL) {
                if (ent->d_type == DT_DIR) continue;
                if (ent->d_name[0] == '.')  continue;
                int ix;
                if (sscanf(ent->d_name, "memo-%d.wav", &ix) == 1 && ix > maxix) maxix = ix;
                if (n >= UI_VOICE_MAX) continue;
                strncpy(names[n], ent->d_name, UI_VOICE_NAMEL - 1);
                names[n][UI_VOICE_NAMEL - 1] = '\0';
                n++;
            }
            closedir(d);
        }
        nocsif_sdcard_unlock();
    }
    s_voice_next = maxix + 1;

    lv_obj_t *hdr = lv_label_create(content);
    lv_label_set_text(hdr, NOCSIF_NDASH " saved memos " NOCSIF_NDASH);
    lv_obj_add_style(hdr, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(hdr, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(hdr, 16, 0);

    s_voice_list = nocsif_menu_list(content);
    for (int i = 0; i < n; i++) voice_add_row(s_voice_list, names[i]);
    if (n == 0) {
        lv_obj_t *empty = lv_label_create(s_voice_list);
        lv_label_set_text(empty, "no memos yet");
        lv_obj_add_style(empty, &nocsif_style_font_tag_small, 0);
        lv_obj_set_style_text_color(empty, NOCSIF_ASH, 0);
        lv_obj_set_style_pad_all(empty, 8, 0);
    }

    /* Reflect a recording already running in the BACKGROUND (started here earlier, then left). No
     * always-on meter: the mic runs only while RECORDING now, so the level bar is live during a
     * recording and idle otherwise — and playback then has the amp to itself. */
    s_voice_session  = nocsif_mic_recording();
    s_voice_last_lvl = -1;

    lv_timer_t *timer = lv_timer_create(voice_rec_tick, 150, NULL);
    lv_obj_add_event_cb(scr, voice_deleted_cb, LV_EVENT_DELETE, timer);
    voice_rec_tick(timer);
    return scr;
}

static void voice_item_play_cb(lv_event_t *e)
{
    (void)e;
    nocsif_audio_play_wav(s_voice_sel);
}
static void voice_item_rename_cb(lv_event_t *e)
{
    (void)e;
    lv_obj_t *root = build_voice_rename();
    if (root) nocsif_nav_push(root);
}
static void voice_item_delete_cb(lv_event_t *e)
{
    (void)e;
    if (nocsif_sdcard_lock(2000)) {
        remove(s_voice_sel);
        nocsif_sdcard_unlock();
    }
    nocsif_app_launch("voice");   /* rebuild the list fresh (the deleted memo is gone) */
}
static lv_obj_t *build_voice_item(void)
{
    const char *nm = strrchr(s_voice_sel, '/');
    nm = nm ? nm + 1 : s_voice_sel;
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Memo", nm, &content);
    lv_obj_t *list = nocsif_menu_list(content);
    lv_obj_t *play = nocsif_menu_add_row(list, NOCSIF_ICON_PLAY, "Play", NULL, NULL,
                                         NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(play, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(play, voice_item_play_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *ren = nocsif_menu_add_row(list, NOCSIF_ICON_NOTE, "Rename", NULL, NULL,
                                        NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(ren, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(ren, voice_item_rename_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t *del = nocsif_menu_add_row(list, NOCSIF_ICON_REFRESH, "Delete", NULL, NULL,
                                        NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(del, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(del, voice_item_delete_cb, LV_EVENT_CLICKED, NULL);
    return scr;
}

/* Rename the selected memo: a one-line text field + keyboard (mirrors Watch Name). Saving renames the
 * WAV on /sd (sanitized, .wav kept) and rebuilds the list. */
static void voice_rename_save(lv_obj_t *ta)
{
    const char *in = ta ? lv_textarea_get_text(ta) : "";
    char clean[UI_VOICE_NAMEL];
    int j = 0;
    for (int i = 0; in[i] && j < (int)sizeof(clean) - 5; i++) {
        char c = in[i];
        if (c == '/' || c == '\\' || c == ':') continue;   /* no path separators */
        clean[j++] = c;
    }
    clean[j] = '\0';
    if (j == 0) { nocsif_nav_back(); return; }              /* empty -> cancel */
    char newpath[96];
    if (strstr(clean, ".wav")) snprintf(newpath, sizeof newpath, "%s/%s", UI_VOICE_DIR, clean);
    else                       snprintf(newpath, sizeof newpath, "%s/%s.wav", UI_VOICE_DIR, clean);
    if (strcmp(newpath, s_voice_sel) != 0 && nocsif_sdcard_lock(2000)) {
        rename(s_voice_sel, newpath);
        nocsif_sdcard_unlock();
    }
    nocsif_app_launch("voice");   /* back to the list, rebuilt */
}
static void voice_rename_ready_cb(lv_event_t *e)  { voice_rename_save(lv_keyboard_get_textarea(lv_event_get_target(e))); }
static void voice_rename_btn_cb(lv_event_t *e)    { voice_rename_save((lv_obj_t *)lv_event_get_user_data(e)); }
static void voice_rename_cancel_cb(lv_event_t *e) { (void)e; nocsif_nav_back(); }

static lv_obj_t *build_voice_rename(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Rename", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);

    /* Prefill with the current name minus the directory and the .wav extension. */
    const char *base = strrchr(s_voice_sel, '/');
    base = base ? base + 1 : s_voice_sel;
    char prefill[UI_VOICE_NAMEL];
    strncpy(prefill, base, sizeof prefill - 1);
    prefill[sizeof prefill - 1] = '\0';
    char *dot = strstr(prefill, ".wav");
    if (dot) *dot = '\0';

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, "name this memo");
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 8, 0);

    lv_obj_t *ta = lv_textarea_create(content);
    lv_textarea_set_one_line(ta, true);
    lv_textarea_set_text(ta, prefill);
    lv_obj_set_width(ta, lv_pct(100));
    lv_obj_set_style_bg_color(ta, NOCSIF_PIT, 0);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(ta, NOCSIF_BONE, 0);
    lv_obj_add_style(ta, &nocsif_style_row_name, 0);
    lv_obj_set_style_border_color(ta, NOCSIF_EDGE2, 0);
    lv_obj_set_style_border_width(ta, 1, 0);
    lv_obj_set_style_radius(ta, 6, 0);
    lv_obj_set_style_bg_color(ta, NOCSIF_VIOLET, LV_PART_CURSOR);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, LV_PART_CURSOR);

    lv_obj_t *save = lv_obj_create(content);
    lv_obj_remove_style_all(save);
    lv_obj_set_width(save, lv_pct(100));
    lv_obj_set_height(save, LV_SIZE_CONTENT);
    lv_obj_set_style_margin_top(save, 8, 0);
    lv_obj_set_style_bg_color(save, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_bg_opa(save, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(save, NOCSIF_VIOLET, 0);
    lv_obj_set_style_border_width(save, 1, 0);
    lv_obj_set_style_radius(save, 8, 0);
    lv_obj_set_style_pad_ver(save, 11, 0);
    lv_obj_clear_flag(save, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(save, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(save, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(save, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_t *sl = lv_label_create(save);
    lv_label_set_text(sl, "Save");
    lv_obj_center(sl);
    lv_obj_add_style(sl, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(sl, NOCSIF_WHITE, 0);
    lv_obj_add_event_cb(save, voice_rename_btn_cb, LV_EVENT_CLICKED, ta);

    lv_obj_t *kb = lv_keyboard_create(scr);
    lv_obj_add_flag(kb, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_keyboard_set_textarea(kb, ta);
    nocsif_companion_track_ta(ta);   /* §4.8a P2: remote /api/type targets this field */
    lv_keyboard_set_mode(kb, LV_KEYBOARD_MODE_TEXT_LOWER);
    lv_obj_set_size(kb, lv_pct(100), 196);
    lv_obj_align(kb, LV_ALIGN_BOTTOM_MID, 0, -58);
    lv_obj_set_style_bg_color(kb, NOCSIF_VOID, 0);
    lv_obj_set_style_bg_opa(kb, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(kb, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_all(kb, 3, 0);
    lv_obj_add_event_cb(kb, voice_rename_ready_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(kb, voice_rename_cancel_cb, LV_EVENT_CANCEL, NULL);
    return scr;
}

/* -- app picker: a folder tree you tap through; long-press (or tap a leaf) selects the shortcut target -- */
static void dial_pick_add(const char *id);   /* P8 v2.4b: picker -> add to the edited dial (defined below) */
static void ring_pick_add(const char *id);   /* P8 v2.6:  picker -> add to the Home ring   (defined below) */

/* §4.14 — the shortcut tree is DERIVED, not curated. A folder's children are the rows the watch's own menu
 * shows for it — the file-scope k_*_rows tables (k_menu_cats for the three categories, k_comp_submenus for
 * the hubs the companion mirror already maps) — supplemented by the app registry (any enabled screen
 * registered as "<folder>.<leaf>", e.g. usb.hid) and one tiny table for bespoke hubs that drill by hand
 * (Connect Phone). Add a screen to a menu or the registry and it is pickable — there is no list to
 * remember (the old curated tree had missed Audio > Carts, Connectivity, Companion, Media Remote). A node
 * with any child is a FOLDER (tap to open); every node is selectable (long-press, or tap a leaf) to
 * shortcut its screen. Labels + icons come from the registry (app_get); stubs / unregistered ids are
 * skipped; ".macros" ids need a macro sink and stay out. For the ring / dial pickers, leaves already on the
 * edited dial are hidden (pick_placed — defined with the ring module). Side-effect-free: walking this never
 * launches the real screen. */
static const struct { const char *id, *parent; } k_pick_extra[] = {
    { "notif", "phone" }, { "ble.media", "phone" }, { "phone.saved", "phone" },   /* Connect Phone hub */
};
#define PICK_EXTRA_N      ((int)(sizeof k_pick_extra / sizeof k_pick_extra[0]))
#define PICK_MAX_CHILDREN 32
#define PICK_MAX_DEPTH    6

static bool pick_placed(const char *id);   /* ring / dial pickers: already a planet on the edited dial */

static bool pick_ok(const char *id)
{
    app_t *a = app_get(id);
    if (!a || !a->enabled || !a->title) return false;              /* stubs / unregistered */
    size_t n = strlen(id);
    return !(n > 7 && strcmp(id + n - 7, ".macros") == 0);
}
static bool pick_listed(const char *const *ids, int n, const char *id)
{
    for (int i = 0; i < n; i++) if (strcmp(ids[i], id) == 0) return true;
    return false;
}
/* The pickable children of `folder` (NULL = root), in menu order. Returns the count (<= max). */
static int pick_children(const char *folder, const char *out[], int max)
{
    int n = 0;
    if (folder == NULL) {
        for (int c = 0; c < MENU_CATS_N && n < max; c++) out[n++] = k_menu_cats[c].id;
        return n;
    }
    const rowspec_t *rows = NULL;
    size_t rn = 0;
    for (int c = 0; c < MENU_CATS_N; c++) {
        if (strcmp(k_menu_cats[c].id, folder) == 0) { rows = k_menu_cats[c].rows; rn = k_menu_cats[c].n; }
    }
    if (rows == NULL) {
        const comp_submenu_t *sm = comp_find_submenu(folder);
        if (sm) { rows = sm->rows; rn = sm->n; }
    }
    for (size_t i = 0; rows && i < rn && n < max; i++) {           /* 1. the menu's own rows */
        if (pick_ok(rows[i].id) && !pick_listed(out, n, rows[i].id)) out[n++] = rows[i].id;
    }
    for (int i = 0; i < PICK_EXTRA_N && n < max; i++) {            /* 2. bespoke-hub drill targets */
        const char *id = k_pick_extra[i].id;
        if (strcmp(k_pick_extra[i].parent, folder) == 0 && pick_ok(id) && !pick_listed(out, n, id)) out[n++] = id;
    }
    const size_t fl = strlen(folder);
    for (int i = 0; i < s_app_n && n < max; i++) {                 /* 3. registry "<folder>.<leaf>" */
        const char *id = s_apps[i].id;
        if (strncmp(id, folder, fl) != 0 || id[fl] != '.' || strchr(id + fl + 1, '.') != NULL) continue;
        if (pick_ok(id) && !pick_listed(out, n, id)) out[n++] = id;
    }
    return n;
}
static bool pick_has_children(const char *id)
{
    const char *kids[PICK_MAX_CHILDREN];
    return pick_children(id, kids, PICK_MAX_CHILDREN) > 0;
}

/* Apply a selection: route the chosen id by s_pick_key (FN / PWR / dial / ring), as the old flat picker did.
 * "" clears a binding (PWR "(none)"). */
static void pick_apply(const char *id)
{
    if (strcmp(s_pick_key, "fn.target") == 0) {
        nocsif_settings_set_fn_target(id);
    } else if (strcmp(s_pick_key, "pwr.double") == 0) {
        nocsif_settings_set_pwr_double(id);
        nocsif_buttons_set_pwr_double_enabled(id[0] != '\0');
    } else if (strncmp(s_pick_key, "dial.", 5) == 0) {
        dial_pick_add(id);   return;   /* returns to the watchface */
    } else if (strcmp(s_pick_key, "ring") == 0) {
        ring_pick_add(id);   return;   /* returns to Home */
    }
    lv_async_call(nav_back_async, NULL);   /* pop AFTER this event finishes (no delete-in-cb) */
}

static lv_obj_t   *s_pick_list;                  /* the picker's row list (rebuilt in place on a folder change) */
static const char *s_pick_path[PICK_MAX_DEPTH];  /* folders opened from the root (a screen can sit under several) */
static int         s_pick_depth;                 /* 0 = root */
static void pick_populate(const char *folder);
static const char *pick_folder(void) { return s_pick_depth ? s_pick_path[s_pick_depth - 1] : NULL; }

static void pick_row_click_cb(lv_event_t *e)
{
    const char *id = (const char *)lv_event_get_user_data(e);
    if (pick_has_children(id)) {                                            /* folder -> open */
        if (s_pick_depth < PICK_MAX_DEPTH) s_pick_path[s_pick_depth++] = id;
        pick_populate(pick_folder());
    } else {
        pick_apply(id);                                                     /* leaf   -> add  */
    }
}
static void pick_row_long_cb(lv_event_t *e) { pick_apply((const char *)lv_event_get_user_data(e)); }  /* hold -> add */
static void pick_up_cb(lv_event_t *e)
{
    (void)e;
    if (s_pick_depth > 0) s_pick_depth--;                                   /* up one level */
    pick_populate(pick_folder());
}
static void pick_none_cb(lv_event_t *e) { (void)e; pick_apply(""); }      /* PWR "(none)" clears the binding */

static void pick_add_row(lv_obj_t *list, const char *icon, const char *name, const char *tag,
                         lv_event_cb_t click, lv_event_cb_t longp, void *ud)
{
    lv_obj_t *row = nocsif_menu_add_row(list, icon, name, NULL, tag,
                                        tag ? NOCSIF_TAG_VALUE : NOCSIF_TAG_NONE, false, NULL);
    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    if (click) lv_obj_add_event_cb(row, click, LV_EVENT_CLICKED, ud);
    if (longp) lv_obj_add_event_cb(row, longp, LV_EVENT_LONG_PRESSED, ud);
}

static void pick_populate(const char *folder)
{
    lv_obj_t *list = s_pick_list;
    if (!list) return;
    lv_obj_clean(list);                                     /* clear the previous folder's rows */
    if (folder) {                                           /* up-row (names the parent) */
        const char *par = s_pick_depth >= 2 ? s_pick_path[s_pick_depth - 2] : NULL;
        app_t *pa = par ? app_get(par) : NULL;
        pick_add_row(list, NOCSIF_ICON_UP, (pa && pa->title) ? pa->title : "Back", NULL,
                     pick_up_cb, NULL, NULL);
    } else if (strcmp(s_pick_key, "pwr.double") == 0) {
        pick_add_row(list, NULL, "(none)", NULL, pick_none_cb, NULL, NULL);   /* clear the binding */
    }
    const char *kids[PICK_MAX_CHILDREN];
    const int n = pick_children(folder, kids, PICK_MAX_CHILDREN);
    for (int i = 0; i < n; i++) {
        const char *id = kids[i];
        const bool fold = pick_has_children(id);
        if (!fold && pick_placed(id)) continue;             /* already a planet on the edited dial */
        app_t *a = app_get(id);                             /* pick_children vetted it */
        pick_add_row(list, a->icon, a->title, fold ? ">" : "+",
                     pick_row_click_cb, pick_row_long_cb, (void *)id);   /* id = a persistent literal */
    }
}

static lv_obj_t *build_pick(void)
{
    bool for_planet = (strncmp(s_pick_key, "dial.", 5) == 0) || (strcmp(s_pick_key, "ring") == 0);
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold(for_planet ? "Add planet" : "Shortcut",
                                           "open folders " NOCSIF_DOT " hold to add", &content);
    s_pick_list  = nocsif_menu_list(content);
    s_pick_depth = 0;
    pick_populate(NULL);
    return scr;
}

/* -- passcode keypad -- */
#define PIN_MIN_DIGITS  4
#define PIN_MAX_DIGITS  8
static char      s_pin_buf[PIN_MAX_DIGITS + 1];
static int       s_pin_len;
static lv_obj_t *s_pin_dots, *s_pin_status;

static void pin_refresh_dots(void)
{
    if (!s_pin_dots) return;
    char s[PIN_MAX_DIGITS * 2 + 1];
    int n = 0;
    for (int i = 0; i < s_pin_len; i++) { s[n++] = '*'; s[n++] = ' '; }
    s[n] = '\0';
    lv_label_set_text(s_pin_dots, s);
}

static void pin_matrix_cb(lv_event_t *e)
{
    lv_obj_t *m = lv_event_get_target(e);
    uint32_t id = lv_buttonmatrix_get_selected_button(m);
    const char *txt = lv_buttonmatrix_get_button_text(m, id);
    if (txt == NULL) return;
    if (strcmp(txt, "del") == 0) {
        if (s_pin_len > 0) s_pin_buf[--s_pin_len] = '\0';
        if (s_pin_status) lv_label_set_text(s_pin_status,
            s_pin_verify ? "enter passcode" : "4" NOCSIF_NDASH "8 digits");
    } else if (strcmp(txt, "ok") == 0) {
        if (s_pin_len < PIN_MIN_DIGITS) {
            if (s_pin_status) lv_label_set_text(s_pin_status, "need 4+ digits");
        } else if (s_pin_verify) {                    /* P4.6c unlock gate — verify, don't set */
            bool ok = nocsif_settings_verify_pin(s_pin_buf);
            memset(s_pin_buf, 0, sizeof s_pin_buf);
            s_pin_len = 0;
            if (ok) {
                lv_async_call(unlock_proceed_async, NULL);   /* correct -> the deferred destination */
                return;                                      /* leaving — no need to refresh dots */
            }
            if (s_pin_status) lv_label_set_text(s_pin_status, "wrong passcode");
        } else {
            esp_err_t err = nocsif_settings_set_pin(s_pin_buf);
            memset(s_pin_buf, 0, sizeof s_pin_buf);   /* s_pin_buf is a static, not a dead local */
            s_pin_len = 0;
            if (err == ESP_OK) {
                if (s_pin_status) lv_label_set_text(s_pin_status, "passcode saved");
                lv_async_call(nav_back_async, NULL);   /* return to System; refresh the PIN tag */
                return;                                /* leaving — no need to refresh dots */
            }
            if (s_pin_status) lv_label_set_text(s_pin_status, "save failed");
        }
    } else if (txt[0] >= '0' && txt[0] <= '9' && txt[1] == '\0') {
        if (s_pin_len < PIN_MAX_DIGITS) {
            s_pin_buf[s_pin_len++] = txt[0];
            s_pin_buf[s_pin_len] = '\0';
        } else if (s_pin_status) {
            lv_label_set_text(s_pin_status, "max 8 digits");
        }
    }
    pin_refresh_dots();
}

/* Wipe the entered PIN + clear the label pointers when a keypad is freed. */
static void pin_wipe(void)
{
    s_pin_dots = NULL;
    s_pin_status = NULL;
    s_pin_len = 0;
    memset(s_pin_buf, 0, sizeof s_pin_buf);
}

/* Settings > Passcode keypad freed on nav-back. */
static void pin_deleted_cb(lv_event_t *e)
{
    (void)e;
    pin_wipe();
}

/* Build the passcode keypad widgets (masked entry, status line, 3x4 matrix) into `content`, wired to
 * the shared pin_matrix_cb. Shared by Settings > Passcode (set) and the P4.6c unlock gate (verify) —
 * the caller sets s_pin_verify. Resets the entry buffer. */
static void keypad_populate(lv_obj_t *content, const char *status0)
{
    s_pin_len = 0;
    s_pin_buf[0] = '\0';

    s_pin_dots = lv_label_create(content);
    lv_label_set_text(s_pin_dots, "");
    lv_obj_set_style_text_font(s_pin_dots, &nocsif_mono_18, 0);
    lv_obj_set_style_text_color(s_pin_dots, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_left(s_pin_dots, UI_LIST_INSET, 0);
    lv_obj_set_style_pad_top(s_pin_dots, 6, 0);
    lv_obj_set_style_min_height(s_pin_dots, 26, 0);

    s_pin_status = lv_label_create(content);
    lv_label_set_text(s_pin_status, status0);
    lv_obj_set_style_text_font(s_pin_status, &nocsif_mono_12, 0);
    lv_obj_set_style_text_color(s_pin_status, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_left(s_pin_status, UI_LIST_INSET, 0);
    lv_obj_set_style_pad_bottom(s_pin_status, 10, 0);

    static const char *map[] = { "1", "2", "3", "\n",
                                 "4", "5", "6", "\n",
                                 "7", "8", "9", "\n",
                                 "del", "0", "ok", "" };
    lv_obj_t *kp = lv_buttonmatrix_create(content);
    lv_buttonmatrix_set_map(kp, map);
    lv_obj_set_width(kp, lv_pct(88));
    lv_obj_set_height(kp, 260);
    lv_obj_set_style_margin_left(kp, UI_LIST_INSET, 0);
    lv_obj_set_style_bg_opa(kp, LV_OPA_TRANSP, 0);        /* transparent frame — orrery shows */
    lv_obj_set_style_border_width(kp, 0, 0);
    lv_obj_set_style_pad_all(kp, 4, 0);
    lv_obj_set_style_bg_color(kp, NOCSIF_PIT, LV_PART_ITEMS);
    lv_obj_set_style_bg_opa(kp, LV_OPA_COVER, LV_PART_ITEMS);
    lv_obj_set_style_text_color(kp, NOCSIF_BONE, LV_PART_ITEMS);
    lv_obj_add_style(kp, &nocsif_style_row_name, LV_PART_ITEMS);
    lv_obj_set_style_radius(kp, 4, LV_PART_ITEMS);
    lv_obj_set_style_border_width(kp, 0, LV_PART_ITEMS);
    lv_obj_add_flag(kp, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_event_cb(kp, pin_matrix_cb, LV_EVENT_VALUE_CHANGED, NULL);
}

/* Remove the passcode (Settings > Passcode, shown only when one is set) -> back to no-PIN, so the
 * lock screen stops gating (immediate unlock again). Reaching this screen already means the menu was
 * unlocked, so it does not re-prompt for the current PIN. */
static void pin_remove_cb(lv_event_t *e)
{
    (void)e;
    nocsif_settings_clear_pin();
    if (s_pin_status) lv_label_set_text(s_pin_status, "passcode removed");
    lv_async_call(nav_back_async, NULL);   /* pop to System; the PIN Lock tag refreshes to "none" */
}

/* Settings > Passcode : set / replace / remove the passcode (a nav-stack scaffold screen). */
static lv_obj_t *build_pin(void)
{
    s_pin_verify = false;
    bool had = nocsif_settings_has_pin();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold(
        "Passcode", had ? "replace, or remove below" : "set a passcode", &content);
    lv_obj_add_event_cb(scr, pin_deleted_cb, LV_EVENT_DELETE, NULL);
    keypad_populate(content, "4" NOCSIF_NDASH "8 digits");

    /* With a passcode set, offer a one-tap remove -> no-PIN. */
    if (had) {
        lv_obj_t *rm = lv_button_create(content);
        lv_obj_remove_style_all(rm);
        lv_obj_add_flag(rm, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_set_style_bg_opa(rm, LV_OPA_TRANSP, 0);
        lv_obj_set_style_bg_color(rm, NOCSIF_PIT, LV_STATE_PRESSED);   /* subtle press highlight */
        lv_obj_set_style_bg_opa(rm, LV_OPA_COVER, LV_STATE_PRESSED);
        lv_obj_set_style_radius(rm, 4, 0);
        lv_obj_set_style_pad_left(rm, UI_LIST_INSET, 0);
        lv_obj_set_style_pad_top(rm, 12, 0);
        lv_obj_set_style_pad_bottom(rm, 6, 0);
        lv_obj_add_event_cb(rm, pin_remove_cb, LV_EVENT_CLICKED, NULL);
        lv_obj_t *rl = lv_label_create(rm);
        lv_label_set_text(rl, "Remove passcode");
        lv_obj_set_style_text_font(rl, &nocsif_mono_14, 0);
        lv_obj_set_style_text_color(rl, NOCSIF_STEEL, 0);
    }
    return scr;
}

/* P4.6c — free the keypad-screen ref + wipe the entry when the unlock keypad is deleted. */
static void unlock_pin_deleted_cb(lv_event_t *e)
{
    (void)e;
    s_unlock_pin = NULL;
    pin_wipe();
}

/* Swipe down on the unlock keypad = cancel (back to the watchface). Deferred — never delete a screen
 * inside its own gesture event. */
static void unlock_gesture_cb(lv_event_t *e)
{
    (void)e;
    lv_indev_t *indev = lv_indev_active();
    if (indev != NULL && lv_indev_get_gesture_dir(indev) == LV_DIR_BOTTOM) {
        lv_async_call(unlock_cancel_async, NULL);
    }
}

/* P4.6c — the unlock keypad: a standalone screen shown OVER the watchface (transparent, orrery shows
 * through) while locked with a passcode. Same keypad widget as Settings > Passcode, in VERIFY mode.
 * Header = lock glyph + "Locked"; the status line carries "enter passcode" / "wrong passcode". */
static lv_obj_t *build_unlock_pin(void)
{
    lv_obj_t *scr = lv_obj_create(NULL);
    lv_obj_remove_style_all(scr);
    lv_obj_set_size(scr, NOCSIF_DISP_W, NOCSIF_DISP_H);
    lv_obj_set_style_bg_opa(scr, LV_OPA_TRANSP, 0);   /* orrery (bottom layer) shows through */
    lv_obj_set_scrollbar_mode(scr, LV_SCROLLBAR_MODE_OFF);
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_flex_flow(scr, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(scr, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_top(scr, 46, 0);             /* clear the top corner arc (cf. HEADER_TOP_PAD) */
    lv_obj_set_style_pad_row(scr, 4, 0);
    lv_obj_add_event_cb(scr, unlock_pin_deleted_cb, LV_EVENT_DELETE, NULL);
    lv_obj_add_event_cb(scr, unlock_gesture_cb, LV_EVENT_GESTURE, NULL);
    s_pin_verify = true;

    lv_obj_t *lock = lv_label_create(scr);
    lv_label_set_text(lock, NOCSIF_ICON_LOCK);
    lv_obj_set_style_text_font(lock, &nocsif_icons, 0);
    lv_obj_set_style_text_color(lock, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_left(lock, UI_LIST_INSET, 0);

    lv_obj_t *title = lv_label_create(scr);
    lv_label_set_text(title, "Locked");
    lv_obj_add_style(title, &nocsif_style_title, 0);
    lv_obj_set_style_text_color(title, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_left(title, UI_LIST_INSET, 0);
    lv_obj_set_style_pad_bottom(title, 2, 0);

    keypad_populate(scr, "enter passcode");
    return scr;
}

