    nocsif_menu_add_row(list, NOCSIF_ICON_NFC,  "NFC",         NULL, NULL,      NOCSIF_TAG_NONE,  true,  NULL);
    nocsif_menu_add_row(list, NOCSIF_ICON_STAR, "Open menu shell", home, "go",  NOCSIF_TAG_READY, false, NULL);

    return scr;
